	ACH_COUNTER_FALLBACK = "Gegenstände",
	ACH_NOTE_ROOKERY = "Auf der schwebenden Sunwing-Rookery-Plattform (Falconwing Square): kaufe Tasty Meat bei Farstrider Aerieminder (am Balkon) und lege es neben dem Mischievous Chick gegenüber der Truhe ab, um den Schlüssel zu erhalten. Belohnung: Sunwing-Hatchling-Haustier.",
	ACH_NOTE_SAFEBOX = "Benötigt 3 versteckte Safebox Keys — schnapp dir die violette Fackel neben der Truhe, um sie aufzudecken, und sammle dann die Schlüssel in der Nähe ein.",
	ACH_NOTE_PHOENIX = "Benutze Gift of the Phoenix und sammle dann 5 Glut von den wiedergeborenen Phönixen.",
	ACH_NOTE_STONEVAT = "Auf einer erhöhten Plattform: pflücke 10x Bunch of Ripe Grapes in der Nähe und gib sie in das Fass, kaufe dann ein Päckchen Trockenhefe bei Sheri und gib es ebenfalls hinzu.",
	ACH_NOTE_GOURD = "In einer kleinen Höhle (Eingang ~27.5, 68.0). Plündere Mysterious Red Fluid aus dem Dangling Jug und Mysterious Purple Fluid aus dem Hanging Flask, gib beide in die Durable Vase, um Fizzing Fluid herzustellen, und öffne dann den Kürbis.",
	ACH_NOTE_SPORECACHE = "Interagiere mit dem roten Fungal Mallet in Fungara Village für einen Buff und benutze ihn dann, um den Mycelium Gong zu schlagen. Der Schatz erscheint neben dem Gong.",
	ACH_NOTE_CAULDRON = "Nai'theren Grotto (unter einer Brücke etwas östlich von Har'mara). Öffne es mit 150x Crystalized Resin Fragment, geplündert vom Flame-Hardened Sap of Teldrassil. Die Säfte sind im und entlang des gesamten Flusses verstreut, der durch dieses Gebiet fließt (von Nai'theren Grotto hinab vorbei am Shrine of Ages und Vale of Secrets bis zur Den) - sie sind NICHT auf der Minikarte und respawnen, also kämme den Fluss ab (2-7 Fragmente je). Die Fragmente sind Warbound, du kannst also auf jedem Charakter farmen und sie über die Warband Bank sammeln. Tipp: ein Inky Black Potion verdunkelt die Welt, sodass die violetten Säfte auffallen. Bug: die Säfte verschwinden bei genau 149 Fragmenten - lösche 1, damit sie wieder erscheinen.",
	ACH_NOTE_GIFTCYCLE = "Erscheint in der Mitte der Den (fliege hinab zu 51.21, 52.93) nach allen 3 Altarritualen. Für jedes: hebe den Gegenstand in der Nähe auf, opfere ihn am Altar, SPRICH dann mit dem erscheinenden Geist und wähle 'offer item'. Wisdom: Rolled-Up Pillow (51.39, 56.0) -> Altar 51.15, 58.56. Vigor: Lost Hunting Knife (45.14, 54.12) -> Altar 47.18, 53.14. Innocence: Tattered Ball (51.10, 50.49) -> Altar 51.15, 47.55.",
	ACH_NOTE_HONOREDURNS = "Fülle die Truhe, indem du die 4 Honored Warrior's Urns rund um Zul'Aman plünderst; jede ruft einen Chosen-Miniboss hervor, der das Token fallen lässt, kehre dann zur Truhe zurück.",
	ACH_NOTE_SEALINGORBS = "Zerstöre die 4 Sealing Orbs rund um die Truhe, um sie zu entsiegeln.",
	ACH_NOTE_BAITTACKLE = "Hinten in einer kleinen Höhle (Eingang ~21.1, 67.1).",
	ACH_NOTE_BURROW = "In einer kleinen Höhle.",
	ACH_NOTE_MRRUK = "Bewacht vom Miniboss Mrruk the Musclefin - besiege ihn zuerst und plündere dann die Truhe.",
	ACH_NOTE_PREDAXAS = "In einer kleinen Höhle (Eingang ~48.96, 78.33). Drinnen erhältst du den Disruptive-Ozone-Debuff (keine Zauber/Fähigkeiten) - überquere das elektrifizierte Eigelege, ohne die leuchtenden Bodenkreise zu berühren, um die Truhe zu erreichen.",
	ACH_NOTE_VOIDTOMB = "Erfordert Stufe 90. Trinke den Potion of Dissociation auf dem Tisch in der Nähe, renne dann zum gegenüberliegenden Gebäude, schnapp dir den Key of Fused Darkness und schließe die Truhe auf.",
	ACH_NOTE_BLOODYSACK = "Sammle Dripping Meat von Knochenhaufen in der Nähe, um die Forgotten Oubliette zu füttern.",
	ACH_NOTE_MALIGNANT = "Betritt die Höhle bei 53.21, 44.19. Es ist immer nur ein Malignant Node aktiv - aktiviere sie der Reihe nach (1 -> 2 -> 3 -> 4), bis die Truhe erscheint.",
	ACH_NOTE_STELLAR = "In Slayer's Rise: klicke auf die Höhlentür bei 52.21, 31.16, um sie zu öffnen, gehe dann hinein und halte dich rechts bis ~53.18, 32.21 und klicke/ziehe 3 Mal daran, damit der Hort erscheint.",
	ACH_NOTE_RESEARCHER = "In einer Höhle (Lair of Predaxas, Eingang bei ~47.93, 78.51). Ein Low-Gravity-Debuff lässt dich hoch springen - steige in die Höhle hinab und meide die Bodeneffekte, springe dann über die Felsen hinauf zur Plattform, um sie zu erreichen.",
	ACH_NOTE_SCOUTPACK = "Im Unterbereich Slayer's Rise.",
	ACH_NOTE_EXALIBURN = "Trinke den Potion of Unquestionable Strength in der Nähe und ziehe dann die Exaliburn heraus.",
	ACH_NOTE_VISCERA = "In einer kleinen Höhle (Eingang ~38.06, 68.77) - laufe drum herum und gehe drinnen nach links oben.",
