	DELVE_REWARDS_UNMEASURED = "Saison 2 hat diese Gegenstandsstufen geändert, und Midnight Helper hat die neuen noch nicht gemessen. Statt dir Saison-1-Zahlen zu zeigen, die jetzt zu niedrig sind, bleibt diese Liste leer, bis ein echter Durchlauf sie füllt. Deine Endtruhe und dein Great Vault sind die ehrliche Antwort.",
	WAY_SET_HERE = "Wegpunkt gesetzt: %s.",
	WAY_SET_ELSEWHERE = "Wegpunkt gesetzt: %s, in %s. Du bist in %s — reise erst dorthin, dann übernimmt der Pfeil.",
	WAY_NO_PIN = "Diese Karte akzeptiert ohne TomTom keinen Wegpunkt, also gibt es keinen Pfeil für %s in %s. Die Koordinaten im Text stimmen trotzdem.",
	WAY_FLIGHT_HINT = "Nächster Flugpunkt dort: %s.",
	DELVE_TIP_GNARLDOR_OVERVIEW = "• Neu in 12.1, auf der Gewundenen Insel — Eingang bei {WAY:2512:64.3:77.7:Gnarldor Isle}. Scrollmaster Ruma am Eingang startet eine kurze Questkette.|n• Drei Story-Varianten, zwei Bosse (laut Method und Icy Veins — noch nicht auf deinem Client gemessen). Zwei Varianten enden bei Gralka Snake-Eater: sie frisst Schlangen für Schadens-Stacks und hinterlässt Giftpfützen — zieh sie heraus und tritt den Wellen ihres Purging Breath aus dem Weg.|n• Die dritte endet bei Osseous Amalgamation: unterbrich seinen Knochenschild, lauf vor Bonestorm weg, weiche den Knochenstacheln aus.|n• Klick die Tortollan Scrolls am Weg — Buffs, manche mit Haken.",
	DELVE_TIP_GNARLDOR_ROUTE = "• Drei Robuste Truhen — klick für einen Wegpunkt: {WAY:2635:60.44:68.12:Robuste Truhe 1} · {WAY:2635:52.41:40.84:Robuste Truhe 2} · {WAY:2635:28.67:41.69:Robuste Truhe 3}.|n• Du kommst bei etwa 77, 46 an; das Ausgangsportal steht genau dort — lauf die Truhen ab und du endest, wo du begonnen hast.",
	ARROW_LEAVE_INSTANCE_FIRST = "(erst hier raus)",
	GEM_OPEN_SOCKET_FMT = "Sockelfenster öffnen (%s)",
	DELVE_TIP_RINGOFGLORY_DANGER = "• Der Fissuring Slam des Golems lässt sich nicht unterbrechen. Ein Kick bringt nichts — die Zauberleiste trägt den Schild.|n• Er landet unter dir, es gibt also nichts, aus dem man herauslaufen könnte. Stunne ihn, oder nimm den Treffer mit einem Defensivzauber.|n• Er taucht nur in den höheren Tiers auf, und nicht allein: auf Tier 11 waren es drei, die frei umherliefen. Man kann sie einzeln pullen — tu das. Zwei zusammen sind zwei Slams, die du nicht unterbrechen kannst.|n• Midnight Helper kann dich im Moment des Zaubers nicht warnen: seit 12.1 darf ein Addon nicht mehr sehen, welchen Zauber ein Gegner wirkt. Deshalb steht es hier.",
	DELVE_TIP_RINGOFGLORY_OVERVIEW = "• Neu in 12.1, auf der Gewundenen Insel — Eingang bei {WAY:2512:71.1:56.4:The Ring of Glory}. Es ist eine Arena, und das ist wörtlich gemeint: du bekommst eine Reihe von Gegnern statt eines Endbosses.|n• |cffffffffWelche Reihe, ändert sich von Lauf zu Lauf.|r Mal ist es ein einzelner Boss, nachdem das Gelände geräumt ist; in einem Tier-11-Lauf waren es sieben — erst das Gelände (Nemesis-Gegner, kein normaler Trash), dann Crushfoot, die Bluegill Brothers (Lurgle und Smurgle, mit Adds), Brinebeater, Guth'kar the Bound, drei Arena-Champions gleichzeitig und zum Schluss Drakta. Das ist also ein Beispiel und keine Checkliste: triffst du einen Namen, der hier fehlt, hat die Arena anders gewürfelt — du machst nichts falsch.|n• |cffffffffCrushfoot|r stürmt, und dieser Ansturm ist es, der tötet. |cffffffffCrowd Control stoppt ihn|r — ein Stun oder ein Rückstoß, im Spiel bestätigt. Spieler berichten außerdem von zwei Türmen mit blau leuchtenden Kugeln, die dich hinüberteleportieren; das haben wir selbst nicht getestet.|n• |cffffffffDrakta|r setzt mit Soul Cleave einen Kreis, der eine Zone hinterlässt — bleib draußen und zieh ihn heraus. Er zieht dich auch zu sich. Es gibt Säulen, aber auf diesen Zug war keine Reaktion möglich: rechne mit Schaden, den du überlebst, nicht mit etwas, dem du ausweichst.|n• Die Tierrettung endet bei Gnok, und er kehrt auf halbem Weg untot zurück — du tötest ihn also zweimal.|n• Überall Bodenfallen — schau, wohin du trittst.|n• Unterbrich die Selbstheilung der Spiritcaller und zerstör die War Drum der Warsinger.",
	DELVE_TIP_RINGOFGLORY_ROUTE = "• Drei Robuste Truhen — klick für einen Wegpunkt: {WAY:2633:44.16:22.60:Robuste Truhe 1} · {WAY:2633:25.19:73.74:Robuste Truhe 2} · {WAY:2633:48.56:94.84:Robuste Truhe 3}.|n• Der Ausgang liegt bei {WAY:2633:80.10:53.69:Ausgang}.",
	MARK_DRAG = "Ziehen zum Bewegen (außerhalb des Kampfes)",
	MARK_CLEAR_TARGET = "Zielmarkierung entfernen",
	MARK_CLEAR_WORLD = "Alle Weltmarkierungen entfernen",
	MARK_READYCHECK = "Bereitschaftsprüfung",
	SET_MBUFF_TITLE = "Erinnerung an fehlende Buffs",
	SET_MBUFF_DESC = "Zeigt ein bewegliches Symbol, wenn du einen Klassenbuff wirken kannst, der nicht aktiv ist (Schlachtzugsbuff, Gestalt, Schild, Waffenbuff, Gift, Haltung, Begleiter). Klick es an, um zu wirken (außerhalb des Kampfes).",
	SET_MBUFF_TOGGLE_TITLE = "Symbol für fehlende Buffs anzeigen",
	SET_MBUFF_TOGGLE_DESC = "Zeigt die Erinnerung, sobald ein aufrechterhaltbarer Klassenbuff fehlt. Ziehen zum Bewegen, Umschalt+Scrollen zum Skalieren.",
	SET_OPEN_TITLE = "Öffenbares",
	SET_OPEN_DESC = "Zeigt einen beweglichen Button (mit Anzahl + Liste) für öffenbare Taschengegenstände — Horte, Schatztruhen, Beutel, Questbehälter. Klick zum Öffnen.",
	SET_OPEN_TOGGLE_TITLE = "Button für Öffenbares anzeigen",
	SET_OPEN_TOGGLE_DESC = "Zeigt den Button, sobald du öffenbare Gegenstände trägst. Linksklick öffnet, Rechts-Ziehen bewegt, Pfeil schaltet die Liste um.",
	SET_MARK_TITLE = "Schnellmarkierung",
	SET_MARK_DESC = "Zeigt eine bewegliche Leiste, um dein Ziel schnell zu markieren (Totenkopf, Kreuz, …) und Weltmarkierungen auf dem Boden zu setzen.",
	SET_MARK_TOGGLE_TITLE = "Schnellmarkierungs-Leiste anzeigen",
	SET_MARK_TOGGLE_DESC = "Erscheint nur, während du in einer Gruppe/einem Schlachtzug bist. Obere Reihe markiert dein Ziel + Bereitschaftsprüfung, untere Reihe setzt Weltmarkierungen (Linksklick setzen, Rechtsklick entfernen). Zieh den goldenen Griff zum Bewegen.",
})

