--========================================================================
-- Professions 101 (les 1-7), route-advies en de flight-master-pin
-- 56 strings die sinds v3.3.0 in enUS staan. Zeven ervan stonden in deze
-- vijf packs nog in hun oude bewoording en zijn op 21 aug verwijderd; die
-- komen hier terug als vertaling van de HUIDIGE Engelse tekst.
--
-- NAMEN VOLGEN DE CLIENT, NIET HET ENGELS. Blizzard vertaalt in deze vijf
-- taalpakketten wat wij lang Engels lieten: Silvermoon is Silbermond /
-- Lune-d'Argent / Ciudad de Lunargenta / Luaprata / Lunargenta, en
-- Multicraft is Mehrfachherstellung / Fabrication multiple / ... Een les die
-- zegt "kijk bij Multicraft" is onbruikbaar als dat woord niet op het scherm
-- van de speler staat. nlNL houdt alles Engels omdat er geen NL-client is --
-- dat is dezelfde regel, niet een andere. Per term is een bron vastgelegd
-- (Wowhead per taal + client-GlobalStrings); Wowhead is een kandidaat, de
-- client van Rob beslist. Engels gebleven waar de client Engels toont, o.a.
-- de node Reuse en de uitbreidingsnaam Midnight.
--========================================================================

fill("deDE", {
	CMDLIST_FP = "Pfeil zum nächsten Flugmeister, egal wo du gerade bist",
	CMDLIST_COURSE = "Berufe 101 in einem eigenen Fenster, neben dem Spiel",
	TOOLLP_COURSE_NAME = "Kurs: Berufe 101",
	TOOLLP_COURSE_DESC = "Der Einsteigerkurs in einem eigenen Fenster, damit die Kapitelliste die volle Höhe bekommt und der Text neben dem Spiel stehen bleibt, während du die Aufgabe machst.",
	PROFACAD_BTN_FULL_COURSE = "Ganzer Kurs",
	PROFACAD_ADVISE_NEXT_POINTS_FMT = "Tipp: nächste Punkte in %s (Wurzel %d/%d) — ziele auf etwa %d. Fahre im Spiel über den Knoten; sein Tooltip nennt die genaue Zahl, und die Guides widersprechen sich darüber.",
	PROFACAD_ADVISE_NEXT_OPEN_FMT = "Tipp: schalte %s frei — und hör dann auf. Das Freischalten ist das, was sich lohnt; Punkte darüber hinaus sind eine Wette auf Materialpreise.",
	PROFACAD_ADVISE_GOALS_FMT = "Ab hier teilt sich die Route, und die beiden Wege unterscheiden sich wirklich. %s",
	PROFACAD_ADVISE_GOAL_LINE_FMT = "%s %s (Wurzel %d/%d).",
	PROFACAD_GOAL_GOLD = "An andere verkaufen:",
	PROFACAD_GOAL_SELF = "Dich und deine Gilde ausrüsten:",
	PROFACAD_CHOICES_HEADER = "Einzelne Knoten in deinen Bäumen, die noch nicht voll sind:",
	PROFACAD_CHOICES_HEADER_MORE_FMT = "Einzelne Knoten in deinen Bäumen, die noch nicht voll sind (%d von %d):",
	PROFACAD_CH_KNOWLEDGE_BODY = "Dein Beruf wächst auf zwei Arten, und genau da sitzt die Verwirrung.\n\nDeine |cffffffffFertigkeit|r steigt, indem du Dinge herstellst. Das läuft von allein. Daneben sammelst du |cffffffffWissen|r, das du gerade nicht vom Herstellen bekommst, sondern aus Aufträgen, Schätzen und Büchern — und das gibst du in einem Baum aus, wo du wählst, worin du gut wirst.\n\nDas Bild, das hilft: |cffffffffFertigkeit ist, wie oft du es gemacht hast, Wissen ist, worin du dich vertieft hast.|r Zwei Alchemisten mit der gleichen Fertigkeit können völlig verschiedene Dinge herstellen, weil sie ihr Wissen woanders hineingesteckt haben. Deshalb kannst du auch nicht alles haben. Du musst wählen.\n\n|cffffcc00Woher die Punkte kommen — fünf Quellen, und die erste stellt alle anderen in den Schatten.|r\n\n1. Aufträge vom Spiel selbst (Kundenaufträge), an deiner eigenen Werkbank. Dazu kommt unten ein eigenes Kapitel, samt der Falle, sie alle gleich am Wochenanfang zu machen.\n2. Alles einmal herstellen. Die erste Anfertigung jedes Rezepts gibt einen Punkt. Mach das, bevor du anfängst auszugeben, dann hast du mehr zum Verteilen.\n3. Schätze draußen in der Welt. Über die Midnight-Gebiete verteilt stehen Behälter, die Punkte geben — eine ordentliche Ausbeute, wenn du sie noch nicht eingesammelt hast.\n4. Eine Wochenquest bei deinem Lehrer, und eine Abhandlung, die dir jemand mit Inschriftenkunde herstellen kann.\n5. Rufbücher. Ein paar Fraktionen verkaufen dir ein Buch, das gleich zehn auf einmal gibt.\n\nKochkunst, Angeln und Archäologie haben keine Bäume und brauchen überhaupt keine Punkte.\n\nMach dir keine Sorgen darüber, \"hinterher\" zu sein: verpasste Wochen kommen über ein Aufholsystem langsam zurück, und dieser Kurs geht es Schritt für Schritt mit dir durch.",
	PROFACAD_CH_TREES_ADVANCED = "Wo klickst du eigentlich? Öffne dein Berufsfenster (das mit deinen Rezepten) und sieh dir die Reiter unten an: Rezepte, Spezialisierungen, Handwerksaufträge. Spezialisierungen ist der Reiter, den du brauchst — dort stehen deine Bäume, und dort wird Wissen ausgegeben. Es passiert nichts, bis du bestätigst, du kannst es also gefahrlos öffnen und erst einmal nur schauen. Du weißt nicht, welcher Baum? Komm hierher zurück: die Berufsübersicht nennt dir den nächsten Knoten, sobald sie deine Bäume lesen kann.",
	PROFACAD_CH_TREES_BODY = "Dort stehen drei oder vier |cffffffffRäder|r nebeneinander. Jedes besteht aus runden Feldern, die durch Linien verbunden sind, und du erkennst eins am Ring drumherum, der sich füllt, während du Punkte hineinsteckst — fahre mit der Maus darüber, dann steht da so etwas wie \"3 / 30\": drei Punkte drin, dreißig ist voll. Guides nennen so ein Feld einen Knoten. Jedes Rad hat ein großes Feld in der Mitte (die Wurzel) und kleinere drumherum, die erst auftauchen, wenn in dem mittleren genug steckt. Schauen kostet nichts: es ändert sich erst etwas, wenn du bestätigst.\n\n|cffffcc00Die einzige Regel, die zählt: verteile deine Punkte nicht.|r\n\nÜberall ein bisschen hineinzustecken fühlt sich klug an. Es ist der teuerste Fehler überhaupt, und jeder macht ihn. Der Grund: alles, was sich wirklich lohnt, sitzt hinter einer |cffffffffSchwelle|r. Bei dreißig Punkten passiert etwas, bei fünfzehn passiert nichts. Vier halb gefüllte Felder geben dir also |cffffffffnichts|r — du hast hundert Punkte ausgegeben und kannst immer noch nichts Besonderes herstellen.\n\nWähle eins. Mach es voll. Und erst dann weiter. Wie groß so eine Schwelle ist, unterscheidet sich pro Beruf und sogar pro Feld, geh also nicht nach einer Zahl aus einem Guide: fahre über das Feld, und das Spiel sagt es dir.\n\n|cffffcc00Was du fürs Öffnen eines Zweiges bekommst|r, ist nicht das, was die meisten erwarten, und es ist eine gute Nachricht. Das Rezept hängt meistens am |cffffffffÖffnen|r eines Zweiges und nicht am Vollmachen — du öffnest ihn und kannst die Sache sofort herstellen. Die Punkte, die du danach hineinsteckst, machen es nicht möglich, sie machen es |cffffffffbesser|r. Das Öffnen kostet dich auch kein Wissen; dafür bekommst du eigene Freischaltungen, an festen Punkten im mittleren Feld. Aber du bekommst nicht unbegrenzt viele. Willst du einen zweiten Zweig öffnen, musst du erst tiefer in die Mitte. Öffnen ist gratis, aber rationiert.\n\n|cffffcc00Und manche Dinge sind schlicht ausgeschaltet,|r und das ist die Falle, bei der Leute glauben, das Spiel sei kaputt. Ein paar Zweige schalten etwas ein, das es vorher gar nicht gab. Ein Ingenieur kann alte Ausrüstung recyceln, |cffffffffentdeckt dabei aber erst Rezepte|r, nachdem Punkte drinstecken — ohne das recycelst du ewig, und es passiert nichts. Ein Schneider sieht den teuren Stoff erst fallen, sobald der passende Zweig gelernt ist. Ein Kräuterkundler kann erst vom Reittier aus pflücken, wenn er tief genug drin ist. Scheint etwas \"nicht zu funktionieren\", prüfe zuerst, ob es vielleicht noch eingeschaltet werden muss.\n\n|cffffcc00Du hast einen Versuch frei.|r Seit Patch 12.1 kannst du deine Punkte |cffffffffeinmal pro Beruf|r zurücksetzen, bei Theremis in Silbermond, gleich beim Auftragstisch. Einmal — danach stehen deine Entscheidungen fest. Du verlernst dabei auch die Rezepte, die diese Punkte freigeschaltet hatten; sie kommen zurück, sobald du die Punkte wieder setzt, aber erschrick nicht davon. Und nervös musst du deswegen nicht sein: sammelst du weiter, kannst du auf Dauer jeden Zweig füllen, Punkte können also nicht wirklich |cffffffffverschwendet|r sein — sie können nur in den Monaten, in denen es zählt, an der falschen Stelle liegen.\n\nEine Baumwahl bekommst du bei Fertigkeit 25, 50, 60 und 75. Das Spiel entscheidet nicht, welche; das machst du. Sobald du Berufe hast, geben ihre eigenen Kapitel unten einen konkreten Starter Build, und die Berufsübersicht zeigt live Tipps für deine eigenen Bäume.",
	PROFACAD_CH_QUALITY_TITLE = "Qualität — warum sein Schwert besser ist als deins",
	PROFACAD_CH_QUALITY_INTRO = "Zwei Spieler benutzen dasselbe Rezept, und das eine Ergebnis wird besser. Das ist kein Pech und kein Bug: hergestellte Dinge haben einen Qualitätsrang.",
	PROFACAD_CH_QUALITY_ADVANCED = "Wo klickst du eigentlich? Öffne ein Rezept in deinem Berufsfenster und sieh dir rechts den Kasten Fertigungsdetails an: dort steht die Rezeptschwierigkeit gegen deine Fertigkeit, und das ist die ganze Rechnung in zwei Zahlen. Klick auf eine Zutat im Rezept, und du darfst selbst wählen, welche Qualität an Material hineingeht — der Tooltip sagt: \"Linksklick, um Reagenzienqualitäten zuzuteilen.\" Es gibt auch ein Häkchen \"Verwendet Reagenzien der höchsten Qualität\", das automatisch dein bestes nimmt. Praktisch, aber es verbraucht deine teuren Materialien, ohne noch einmal nachzufragen.",
	PROFACAD_CH_QUALITY_BODY = "Das Bild, das hilft: das Rezept sagt, |cffffffffwas|r du herstellst, die Qualität sagt, wie gut es geworden ist. Zwei Bäcker mit demselben Rezept backen nicht dasselbe Brot.\n\nDu liest sie an einer kleinen |cffffffffForm|r ab, nicht an einer Zahl. Im Tooltip steht \"Qualität:\" mit dem Zeichen daneben — eine graue Raute ist niedrig, ein goldenes Fünfeck ist hoch. In deinem Berufsfenster taucht dasselbe als Leiste auf, links die niedrigste Form und rechts die höchste, mit einem weißen Strich, der zeigt, wo deine Anfertigung ungefähr landen wird.\n\nSie zählt aus drei Gründen, und der dritte erwischt jeden einmal. Bessere Ausrüstung und stärkere Tränke, klar. Mehr Gold: dasselbe Rezept, ein Schuppengewebter Balg, brachte 10g94 auf dem niedrigsten Rang und 21g12 auf dem höchsten — fast das Doppelte, für dieselben Materialien und denselben Klick. Jeder Rang ist tatsächlich ein |cffffffffeigenes Item|r mit einem eigenen Eintrag im Auktionshaus, sie stapeln sich also nicht zusammen. Und der dritte: bestellt jemand eine Mindestqualität, die du nicht erreichst, |cffffffffkannst du diesen Auftrag gar nicht abschließen|r. Nicht \"er wird eben schlechter\" — du kannst ihn buchstäblich nicht abgeben.\n\nEntschieden wird sie von einer einzigen Zahl: deiner |cffffffffFertigkeit|r in dem Moment, in dem du auf Herstellen drückst. Jedes Rezept hat eine Schwierigkeit. Liegst du bequem darüber, bekommst du den höchsten Rang; liegst du darunter, eben nicht.\n\nDiese Zahl setzt sich aus vier Dingen zusammen. Deine Grundfertigkeit, die beim Herstellen steigt und irgendwann voll ist. Dein Wissen, das Fertigkeit |cffffffffnur für genau diese Art Rezept|r gibt — Punkte in Ringen machen deine Ringe besser, nicht deine Halsketten. Deine Berufsausrüstung: ein Werkzeug und zwei Zubehörteile pro Beruf, in eigenen Ausrüstungsslots, die sehr viele Leute schlicht leer lassen. Und deine Reagenzien, die dieselben Qualitätsformen tragen — billige Materialien sind also nicht immer billiger.\n\nKommst du eine Stufe zu kurz, gibt es ein Sicherheitsnetz: Konzentration. Dazu gibt es unten ein eigenes Kapitel.\n\nEine Falle ist es wert, genannt zu werden, weil sie echtes Gold kostet: |cffffffffhalb spezialisiert zu sein ist teurer, als sich gar nicht zu spezialisieren|r. Verteilst du deine Punkte auf vier Zweige, kommst du überall zu kurz. Du kannst alles auf einem mittelmäßigen Rang herstellen, und mittelmäßig verkauft sich nicht und wird bei Aufträgen abgelehnt.\n\nSammelst du, statt herzustellen, tragen auch deine Kräuter und Erze Ränge — in Midnight aber nur |cffffffffzwei|r davon, nicht die ganze Leiter. Mehr Fertigkeit heißt öfter den besseren der beiden. Es gibt keinen dritten Rang, dem du hinterherjagen könntest.",
	PROFACAD_CH_QUALITY_TASK = "Öffne ein Rezept und finde die Qualitätsleiste und den Kasten Fertigungsdetails.",
	PROFACAD_CH_STATS_TITLE = "Die sechs Zahlen, die niemand erklärt",
	PROFACAD_CH_STATS_INTRO = "Mehrfachherstellung, Einfallsreichtum, Gewandtheit. Das Spiel sagt nirgends, was sie tun, und die meisten Spieler schlagen es jedes Mal aufs Neue nach.",
	PROFACAD_CH_STATS_ADVANCED = "Wo siehst du sie eigentlich? Öffne ein beliebiges Rezept in deinem Berufsfenster und sieh dir rechts den Kasten Fertigungsdetails an — dort stehen die sechs als Prozentwerte, zum Beispiel Einfallsreichtum 4%, Mehrfachherstellung 4%, Genialität 19%. Im selben Kasten steht die Rezeptschwierigkeit gegen deine Fertigkeit, und darunter, was Konzentration dich kosten würde, um den nächsten Qualitätsrang zu erzwingen.",
	PROFACAD_CH_STATS_BODY = "Das Bild, das hilft: |cffffffffdie Fertigkeit entscheidet, wie gut es wird, diese sechs entscheiden, wie günstig du dahin gekommen bist.|r Bei der Fertigkeit geht es um das Ergebnis; bei diesen hier um den Weg dorthin.\n\nDrei sind fürs Herstellen und drei fürs Sammeln, du brauchst also nie alle sechs gleichzeitig.\n\nBeim Herstellen. |cffffffffEinfallsreichtum|r heißt, dass eine Anfertigung manchmal weniger verbraucht, als sie sollte, und du die Materialien behältst. Er wirkt auf alles, und er ist der einzige der sechs, der deinen Gewinn bei fremden Aufträgen verbessert, weil die Reste bei dir bleiben und nicht beim Besteller. |cffffffffMehrfachherstellung|r heißt, dass manchmal mehr als eins aus denselben Materialien herauskommt. |cffffffffGenialität|r gibt dir einen Teil deiner Konzentration zurück.\n\nDie Falle in dieser Liste: |cffffffffMehrfachherstellung bringt bei Ausrüstung nichts.|r Ein zusätzliches Exemplar bedeutet nur etwas bei Dingen, die sich stapeln — Tränke, Edelsteine, Materialien. Ein Ring oder ein Brustpanzer verdoppelt sich nie, wenn du also vor allem Ausrüstung herstellst, ist Mehrfachherstellung verschenkt. Und bei fremden Aufträgen gehen die zusätzlichen Exemplare an den |cffffffffBesteller|r, nicht an dich. Das Letzte ist das, was Spieler einander berichten; Blizzard hat es nie bestätigt.\n\nBeim Sammeln. |cffffffffFinesse|r gibt dir mehr pro Vorkommen, und das ist dein Volumen und damit dein Gold. |cffffffffWahrnehmung|r gibt dir eine bessere Chance auf das seltene Material statt mehr vom gewöhnlichen. |cffffffffGewandtheit|r macht die Sammel-Animation kürzer.\n\nWelche davon zählt, hängt davon ab, was du machst, und genau das ist der nützliche Teil. Kräuterkunde will Finesse: pro Stunde verbringst du weit mehr Zeit mit Suchen und Fliegen als mit Pflücken, schneller sammeln löst also das falsche Problem. Bei Bergbau ist es genauso, und Wahrnehmung ist dort schwach, weil das seltene Erz, zu dem es dich lenkt, in Rezepten kaum gebraucht wird. |cffffffffBei Kürschnerei kehrt es sich um|r — sobald du die seltenen Bestien jagst, ist Wahrnehmung stark, denn dort liegt die teure Beute. Es ist der einzige Sammelberuf, bei dem das gilt. Diese drei sind Einschätzungen dazu, wie sich die Berufe spielen, und keine Zahlen, die jemand veröffentlicht hätte.\n\nDie Werte kommen aus zwei Quellen, die du selbst steuerst: deinem Wissen, denn viele Knoten geben einen dieser sechs, und deiner Berufsausrüstung. Schau beim Ausgeben eines Punktes also auch darauf, welcher Stat unter dem Knoten hängt und ob er zu dem passt, was du wirklich herstellen willst.\n\nWenn du dir eines merkst: |cffffffffentscheide erst, was du herstellst, und wähle dann deinen Stat.|r Jemand, der Tränke verkauft, und jemand, der Ringe herstellt, haben entgegengesetzte Interessen, und ein Guide, der \"Mehrfachherstellung ist am besten\" ruft, sagt nicht dazu, mit wem er redet.",
	PROFACAD_CH_STATS_TASK = "Öffne die Fertigungsdetails bei einem Rezept und lies deine eigenen drei Prozentwerte.",
	PROFACAD_CH_CONC_TITLE = "Konzentration, die Notbremse",
	PROFACAD_CH_CONC_INTRO = "Manchmal kommst du einen Rang zu kurz, und das Ding trotzdem herzustellen fühlt sich nach Verschwendung an. Genau dafür ist Konzentration da.",
	PROFACAD_CH_CONC_ADVANCED = "Wo findest du sie eigentlich? In deinem Berufsfenster ist sie eine Leiste ganz oben mit deinem aktuellen Vorrat, und wenn du ein Rezept öffnest, steht neben dem Herstellen-Knopf ein Flammensymbol mit dem, was genau diese Anfertigung kosten würde. Die Kosten unterscheiden sich pro Rezept, lies sie also, bevor du drückst.",
	PROFACAD_CH_CONC_BODY = "Das Bild: |cffffffffsie ist ein Akku, der sich selbst auflädt.|r Du tust nichts dafür, er füllt sich von allein, und du kannst ihn in dem Moment leeren, in dem es darauf ankommt. Setzt du sie bei einer Anfertigung ein, ist der nächste Qualitätsrang |cffffffffgarantiert|r — keine Chance, kein Würfelwurf. Das Spiel sagt es selbst: \"Wendet 358 Konzentration an, um die nächsthöhere Qualität für dieses Rezept zu garantieren.\"\n\nHier ist die ganze Geschichte, und sie ist der Grund, warum Leute sie falsch einsetzen. Der Akku fasst |cffffffff1000|r und lädt mit etwa |cffffffff250 pro Tag|r nach, also rund vier Tage von leer bis voll. Das ist langsam. Jedes Mal, wenn du sie benutzt, gibst du einen Teil deiner nächsten Tage aus, und wenn er leer ist, kannst du nur warten.\n\nJeder Beruf hat seinen |cffffffffeigenen|r Akku. Ein Alchemist, der auch Kräuter pflückt, hat zwei, und die haben nichts miteinander zu tun.\n\nBillig pro Einsatz ist sie auch nicht. Eine echte Anfertigung kostete 358 von 1000 — mehr als ein Drittel des Akkus für ein einziges Item.\n\nLohnt sich: etwas, dem ein Rang fehlt und das du selbst tragen oder benutzen wirst; ein Auftrag mit einer Mindestqualität, die du sonst nicht erreichst, denn ohne Konzentration kannst du diesen Auftrag gar nicht abschließen; und alles Teure, bei dem der Abstand zwischen den Rängen mehr wert ist als ein Tag Akku.\n\nLohnt sich nicht: etwas, das du ohnehin schon auf dem höchsten Rang herstellst, denn da kaufst du nichts und bist den Akku los. Das ist der häufigste Fehler, weil Leute den Knopf angeschaltet lassen und es nie merken. Und billige Massenware — fünfzig Tränke einen Rang höher ist nett, aber keine vier Tage wert.\n\nDu bekommst etwas davon zurück. |cffffffffGenialität|r, einer der sechs Stats, erstattet ab und zu einen Teil dessen, was du gerade ausgegeben hast, und das Spiel meldet es dir auch. Genau deshalb wird Genialität erst interessant, sobald du auf Qualität hinsteuerst: ohne Ausgaben gibt es nichts zu erstatten.\n\nNoch eine Sache, und dabei geht es um Menschen statt um Mechanik. Verbrennst du Konzentration, um die verlangte Qualität auf |cffffffffdem Auftrag eines anderen|r zu erreichen, bekommt der Besteller das bessere Item, und du zahlst aus einem Akku, der Tage zur Erholung braucht. Erfahrene Handwerker verlangen dafür mehr. Das ist keine Regel und es gibt keinen festen Satz, aber es ist gut zu wissen, dass danach zu fragen nicht gierig ist und gefragt zu werden nicht seltsam.\n\nKonzentration ist nichts, was du verwalten oder optimieren musst. Sie ist eine Bremse, und sie ist für den Moment da, in dem dir ein Rang auf etwas fehlt, das es wert ist. Läuft sie voll, während du spielst, machst du es richtig. Steht sie wochenlang auf voll, lässt du wahrscheinlich Qualität liegen.",
	PROFACAD_CH_CONC_TASK = "Finde deine Konzentrationsleiste und prüfe, ob sie schon länger auf voll steht.",
	PROFACAD_CH_GOLD_TITLE = "Gold verdienen, ohne dich selbst zu belügen",
	PROFACAD_CH_GOLD_INTRO = "Es gibt hier nur eine einzige Rechnung, und fast niemand macht sie: was du dafür bekommst, minus alles, was hineinging, minus 5% fürs Auktionshaus.",
	PROFACAD_CH_GOLD_BODY = "Das Wort, das übersprungen wird, ist |cffffffffalles|r. Selbst gepflückte Kräuter sind |cffffffffnicht gratis|r. Sie haben einen Marktpreis, und steckst du sie in einen Trank, statt sie zu verkaufen, hast du ihn ausgegeben — du hast ihn nur an dich selbst gezahlt. Ist das Kraut mehr wert als der Trank, ist Herstellen |cffffffffein Verlust, der sich wie Gewinn anfühlt|r.\n\n|cffffcc00Es gibt zwei Märkte, und sie gehorchen entgegengesetzten Gesetzen.|r Fast die ganze Verwirrung darüber, ob ein Beruf sich \"lohnt\", kommt daher, dass die beiden vermischt werden.\n\nDer erste ist |cffffffffHandelsware|r: Materialien, Tränke, Fläschchen, Edelsteine — alles, was sich stapelt. Du verkaufst Dinge, und du konkurrierst mit der ganzen Region statt nur mit deinem eigenen Realm. Käufer sehen nichts außer dem Preis.\n\nDer zweite ist |cffffffffhergestellte Ausrüstung|r. Sie bleibt auf deinem Realm, und das Beste davon bindet sich an eine Person und kann deshalb gar nicht ins Auktionshaus. Hier verkaufst du keine Dinge, hier verkaufst du dein Handwerk.\n\n|cffffcc00Warum der Markt für Handelsware immer absackt|r, ist es wert, verstanden zu werden, und keiner der Gründe lautet \"es gibt viele Spieler\". Das Spiel kauft automatisch das billigste Angebot, ein Kupferstück über dem niedrigsten Preis heißt also kein Verkauf. Du konkurrierst mit allen Realms deiner Region gleichzeitig. Mehrfachherstellung verteilt gratis zusätzliches Angebot, und sie wirkt nur bei Dingen, die sich stapeln — genau in diesem Markt. Und Verbrauchsgüter haben statt der ganzen Leiter nur zwei Qualitätsränge, es ist also ein kürzerer Fall bis zum Boden.\n\nEs gibt eine Bremse: solange Handwerker noch Konzentration brauchen, um Spitzenqualität zu erreichen, ist Spitzenqualität knapp. Sobald sie es aus eigener Kraft schaffen, löst sich die Bremse und der Preis fällt. In diesem Markt verdienst du also in dem Fenster |cffffffffdavor|r.\n\n|cffffcc00Was einen Preis wirklich schützt, ist ein Schloss auf dem Angebot.|r Davon gibt es vier Arten: ein Cooldown auf dem Rezept, eine Zutat, die der Hersteller nie selbst liefern kann, ein Rezept hinter Ruf, und Konzentration, weil sie nur langsam nachlädt. |cffffffffWo ein Schloss ist, ist Marge. Wo keines ist, ist Volumen und fast keine Marge.|r Das ist das ganze Thema in einem Satz.\n\nSammeln ist die Ausnahme, die es beweist: was du pflückst, hat keinen Einkaufspreis, du |cffffffffkannst|r also nicht verlieren — die einzige Art, Gold zu verdienen, bei der ein Einsteiger nichts falsch machen kann. Aber kein Einkaufspreis heißt auch keine Hürde, also pendelt sich der Preis dort ein, wo der anspruchsloseste Sammler noch zusagt.\n\n|cffffcc00Jedes hergestellte Item fällt in eine von drei Schubladen, und die dritte ist die Falle.|r Frei handelbar sagt es selbst in seinem Tooltip: \"Kann im Auktionshaus verkauft und erworben werden.\" Seelengebundenes kann nicht ins Auktionshaus, |cffffffffkann|r aber über einen Auftrag verkauft werden, der direkt an den Besteller liefert — da verkaufst du Arbeit, kein Produkt. Und |cffffffffWird an Kriegsmeute gebunden|r kann beides nicht: keine Auktion, kein Auftrag, nur du und deine eigenen Twinks. Das ist kein Geschäft, das ist ein Dienst.\n\nBesonders Alchemisten: die beiden Kessel, die deinen ganzen Raid versorgen, sind |cffffffffbeide|r an die Kriegsmeute gebunden. Du kannst sie nie verkaufen. Du stellst sie her, du bringst sie mit, und zurück bekommst du Wohlwollen. Das ist in Ordnung — aber es sollte eine Entscheidung sein und keine nachträgliche Entdeckung, denn es gehen teure Materialien hinein.\n\n|cffffcc00Massenware oder auf Bestellung?|r In Masse verkaufst du das Produkt, konkurrierst mit der ganzen Region über den Preis, hast unbegrenztes Volumen und eine Marge, die immer dünner wird. Über Aufträge verkaufst du dein Können, konkurrierst mit Handwerkern auf deinem eigenen Realm über deinen guten Namen, hast begrenztes Volumen und eine stabilere Marge. Daraus folgt eine Rechnung und keine Meinung: |cffffffffdie Warteschlange der öffentlichen Aufträge ist kein Geschäft.|r Du hast vier auf Vorrat und bekommst einen pro Tag zurück — ungefähr sieben pro Woche. Das ist Taschengeld. |cffffffffPersönliche Aufträge und Gildenaufträge sind unbegrenzt|r, eine Handvoll Stammkunden, die dir direkt Aufträge schicken, ist also die Stelle, an der die echte Arbeit liegt.\n\n|cffffcc00Der größte Anfängerfehler|r ist, herzustellen, bevor du nachgesehen hast, was die Materialien kosten. Er hat zwei Gesichter, und es ist derselbe Fehler: \"ich habe es selbst gepflückt, also ist es gratis\" und \"ich habe dieses Rezept, also stelle ich es her\". Ein Rezept zu haben sagt nichts darüber, ob es sich lohnt. |cffffffffSieh erst nach, was es kostet. Und entscheide dann, ob du es herstellst.|r\n\nUnd misstraue jedem \"X Gold pro Stunde\" aus einem Guide oder Video: das unterscheidet sich pro Realm und ist meistens erfunden. Miss es stattdessen auf deinem eigenen Realm. Auctionator zeigt dir, was Dinge wirklich kosten; CraftSim rechnet aus, was eine Anfertigung gegen die aktuellen Materialpreise einbringt, und ist mit Abstand das Nützlichste, das du installieren kannst, wenn du ernsthaft verdienen willst.",
	PROFACAD_CH_GOLD_DATED_202608 = "|cffffcc00Wie es Ende August 2026 aussieht — und diese Hälfte verfällt.|r Saison 2 ist ein paar Tage alt, lies die Absätze unten also als Momentaufnahme und nicht als Regel. Gut zu wissen: praktisch jeder \"Saison 2\"-Guide da draußen trägt ein Datum von vor dem Saisonstart, was seine Aussagen zu Vorhersagen macht statt zu Beobachtungen. Von niemandem existiert eine veröffentlichte Preisreihe aus diesen ersten Wochen.\n\n|cffffffffAlchemie.|r Tränke und Fläschchen sind frei handelbar und verkaufen sich gut, solange der Raid neu ist und die Nachfrage ihren Höhepunkt hat — aber das ist der Markt für Handelsware in voller Fahrt, rechne also damit, dass die Marge sinkt, je mehr Handwerker Spitzenqualität ohne Konzentration erreichen. Wundersamer Synergist ist das stabilere Einkommen: er hat einen Cooldown von ungefähr einem Tag, niemand kann den Markt also überschwemmen — genau das Schloss von oben — und er speist beide Kessel und den epischen Stein. Housing-Dekoration ist die unterschätzte Sache: sechs Rezepte, handelbar, und sie stapelt sich nicht, konkurriert also auf deinem eigenen Realm statt im regionalen Topf. Eine Marktgeschichte zum Mitnehmen: der neue Gesundheitstrank aus 12.1 verbraucht 25 des alten, der alte Trank ist damit vom Endprodukt zur Zutat befördert worden und als Produkt ungefähr auf die Hälfte gefallen. Wer im Juli einen Vorrat davon angelegt hat, ist am 11. August auf diese Halbierung gestoßen.\n\n|cffffffffKräuterkunde.|r Der Nachtlotus ist das teure Kraut, und der Grund lässt sich genau benennen: er ist das einzige Midnight-Kraut von seltener Qualität, er hat kein eigenes Vorkommen (er fällt als Beifang bei jedem anderen Kraut an), und er steckt in allen vier Fläschchen und beiden Kesseln — insgesamt elf Rezepte. Die beiden neuen Materialien von der Gewundenen Insel sind beide handelbar, mit einer Warnung: sie sind |cffffffffnicht|r exklusiv für Kräuterkundler. Bergbauer holen sie aus ihren eigenen Vorkommen, und eines davon fällt über Kürschnerei auch von Tieren. Mehrere Guides legen etwas anderes nahe.",
	PROFACAD_CH_GOLD_TASK = "Sieh vor deiner nächsten Anfertigung nach, was ihre Materialien kosten — und entscheide erst dann, ob du sie herstellst.",
	PROFACAD_CH_WORKORDERS_TITLE = "Arbeitsaufträge: das Handwerk eines anderen kaufen",
	PROFACAD_CH_WORKORDERS_INTRO = "Im Auktionshaus kaufst du Dinge, die es schon gibt. Am Auftragstisch läuft es andersherum: du bringst die Materialien und bezahlst jemanden für die Arbeit.",
	PROFACAD_CH_WORKORDERS_ADVANCED = "Zwei Dinge, durch die das System kaputt aussieht, obwohl es das nicht ist. An deiner eigenen Werkbank bleibt die Liste der öffentlichen Aufträge leer, bis du auf |cffffffffSuchen|r drückst — es ist nichts kaputt, sie lädt einfach nicht von allein. Und der Mann, der am Auftragstisch steht, Hauptmann Fackelschwur, gehört hier überhaupt nicht dazu: er gibt dir die Einstiegsquest deines Berufs, deine Wochenquests und gratis Beutel voll Material. Nützlich, aber nicht das, weswegen du gekommen bist.",
	PROFACAD_CH_WORKORDERS_BODY = "Das läuft so, weil die beste hergestellte Ausrüstung sich in dem Moment, in dem sie entsteht, an eine Person bindet. Niemand kann sie auf Vorrat herstellen und ins Regal legen, also muss jemand sie |cffffffffeigens für dich|r herstellen.\n\n|cffffcc00Es gibt zwei Schalter, und genau da geht es meistens schief.|r Willst du etwas herstellen lassen, geh zum Auftragstisch im Basar von Silbermond — der große goldene Hammer auf deiner Minikarte. Die Person, die du brauchst, ist Mar'nah. Willst du selbst etwas für jemand anderen herstellen, geh stattdessen zur |cffffffffWerkbank deines eigenen Berufs|r. Stehst du nicht direkt daneben, gibt es keinen Knopf und keine Liste, und es sieht aus, als gäbe es das System gar nicht. Das ist der häufigste Fehler, und das Spiel erklärt es nirgends.\n\n|cffffcc00Etwas herstellen lassen.|r Wähle dein Item, und wähle dann, wen du fragst. Niemanden im Besonderen (der Knopf heißt Öffentlicher Auftrag): alle auf deinem Realm sehen den Auftrag, und wer ihn zuerst nimmt, stellt ihn her. Schnell, aber du bekommst, was du bekommst — |cffffffffeine Qualität kannst du hier nicht verlangen|r, und jedes Material musst du selbst mitschicken. Einen bestimmten Spieler (Persönlicher Auftrag): hier darfst du eine Mindestqualität setzen, und ihr dürft vereinbaren, dass er eigenes Material beisteuert. Deine ganze Gilde (Gildenauftrag): das funktioniert genauso und erreicht auch Gildenmitglieder auf anderen Realms. Die Bezahlung legst du selbst fest, und ein Knopf daneben zeigt, was andere zuletzt für dasselbe Item gezahlt haben.\n\nDrei Dinge, die du wissen solltest, bevor du auf Bestellen klickst. Manche besonderen Zutaten kann der Hersteller nie selbst liefern, die schickst du immer selbst mit. Material in deiner Kriegsmeutenbank |cffffffffzählt nicht|r — leg es in deine Taschen. Und das Item bindet sich an |cffffffffdich|r, bestelle also auf dem Charakter, der es tragen wird, und nicht auf dem, der das Gold hat. Sobald jemand den Auftrag annimmt, kannst du ihn nicht mehr zurückziehen; das Item kommt danach mit der Post.\n\n|cffffcc00Für andere herstellen.|r An deiner Werkbank siehst du vor dem Start, was du daran verdienst. Sobald du anfängst, hast du |cffffffff30 Minuten|r zum Fertigwerden — genug, um noch etwas zu holen, nicht genug, um essen zu gehen.\n\nÖffentliche Aufträge kannst du nicht endlos annehmen: du hast |cffffffffvier|r auf Vorrat, und |cffffffffjeden Tag kommt einer zurück|r. Also ungefähr sieben pro Woche, nicht vier pro Tag. Aufträge, die fast abgelaufen sind, kannst du gratis annehmen.\n\nWeist ein Auftrag dich ab, liegt es an einem von vier Dingen: du kennst das Rezept nicht, deine Spezialisierung ist noch nicht weit genug für die geforderten Extras, es wird eine Qualität verlangt, die du nicht erreichst, oder dein Kontingent ist aufgebraucht.\n\nUnd eines, das dich still und leise Geld kostet: |cffffffffsieh nach, wessen Material du verbrauchst.|r Bei öffentlichen Aufträgen liefert der Besteller immer alles, bei den anderen Arten darf er aber auch gar nichts mitschicken — und dann stellst du fröhlich mit deinem eigenen teuren Vorrat für ein Trinkgeld her.",
	PROFACAD_CH_WORKORDERS_TASK = "Finde den Auftragstisch im Basar von Silbermond und danach die Werkbank deines eigenen Berufs. Das ist nicht derselbe Ort.",
	PROFACAD_CH_PATRON_TITLE = "Kundenaufträge, dein wöchentlicher Wissensmotor",
	PROFACAD_CH_PATRON_INTRO = "Die vierte Art von Auftrag kommt vom Spiel selbst und nicht von einem Spieler, und es ist die, die die meisten Leute nie finden.",
	PROFACAD_CH_PATRON_BODY = "An deiner eigenen Werkbank gibt es einen Reiter |cffffffffKunde|r, auf dem das Spiel selbst dir Aufträge gibt. Kein anderer Spieler, keine Konkurrenz — sie gehören dir allein. Bezahlt wirst du nicht wirklich in Gold, sondern in |cffffffffWissen|r: genau dem, was deinen Beruf stärker macht.\n\nDas ist mit Abstand deine größte Wochenquelle dafür. Wer sie auslässt, fällt zurück, ohne je zu verstehen, warum andere schneller vorankommen.\n\nAlle paar Tage kommt eine neue Ladung. Jeder Auftrag verlangt eine bestimmte Qualität, und manchmal musst du das Material selbst stellen — sieh das nach, denn ein teurer Auftrag für zwei Punkte lohnt sich nicht immer. Einen auszulassen ist erlaubt.\n\n|cffffcc00Und jetzt die Falle.|r Das Spiel gibt dir zusätzlich jeden Tag einen kleinen Auftrag über einen Punkt, aber |cffffffffnur solange du hinter deinem Wochenziel liegst|r. Machst du am Montag gleich alle großen Aufträge, hast du aufgeholt — und die kleinen täglichen bleiben für den Rest der Woche aus.\n\nAlso: |cfffffffflass die großen Aufträge liegen, bis sie fast ablaufen|r. Dann sammelst du in der Zwischenzeit weiter die kleinen ein und beendest die Woche mit mehr Punkten, als du sonst gehabt hättest. Es fühlt sich falsch an. Es stimmt trotzdem.",
	PROFACAD_CH_PATRON_TASK = "Öffne den Reiter Kunde an deiner eigenen Werkbank und sieh dir an, was diese Woche zu bieten hat.",
	PROFACAD_CH_ALCHEMY_BODY = "Alchemie bietet dir einen Baum bei Fertigkeit 25, 50, 60 und 75 — das Spiel wählt nicht, das machst du. Die vier sind Gekonnte Tränke (Tränke, mit einer Seite für das Licht und einer für die Leere), Fließende Fläschchenkenntnisse, Verwandlungsautorität und Meisterschaft der Alchemie.\n\n|cffffcc00Starter Build, in dieser Reihenfolge.|r Zuerst |cffffffffGekonnte Tränke|r: voll gemacht gibt dir dieser Baum den Kessel des Leerenlichttranks, und der dient deinem Gold und deiner Gilde zugleich. Danach |cffffffffPfad des Lichts|r und |cffffffffTüchtiges Tranktalent - Licht|r, der Knoten für Mehrfachherstellung — das Licht, weil das der Trank ist, der sich diese Saison verkauft. Dann |cffffffffMeisterschaft der Alchemie|r und darin |cffffffffReuse|r, der dir Kräuter zurückgibt und stark ist, wenn du sie auch selbst sammelst.\n\nDanach ungefähr 15 Punkte in |cffffffffFließende Fläschchenkenntnisse|r, wodurch deine eigenen Fläschchen doppelt so lange halten, und dann |cffffffffSpezialist der Sin'dorei|r. |cffffffffVerwandlungsautorität|r kommt zuletzt, nicht als Zweites.\n\n|cffffffffGeheimnisse der Haranir sind keine Nebensache.|r Der Tooltip dieses Knotens endet mit \"und Kesseln der Fläschchen der Sin'dorei\" — ohne Punkte dort bekommst du den Fläschchenkessel nicht auf den höchsten Rang. Guides umschreiben diesen Knoten mit \"phials only\" und lassen genau den halben Satz weg, auf den es ankommt.",
	PROFACAD_CH_HERBALISM_BODY = "Jedes Kraut wächst in jedem Gebiet, du musst dir über die Gebietswahl also nicht den Kopf zerbrechen. Die Reihenfolge unten ist das, was die Route in diesem Addon inzwischen empfiehlt, und jeder Schritt ist eine Sache, die du freischaltest, statt einer vagen Verteilung.\n\n|cffffcc00Zuerst: ungefähr 40 Punkte in Botanik.|r Das ist Pflücken vom Reittier aus, und es ist mit Abstand die größte Zeitersparnis des Berufs — ohne das steigst du bei jeder einzelnen Pflanze ab und wieder auf. Druiden lassen das aus: die sammeln ohnehin schon vom Reittier.\n\n|cffffcc00Dann ungefähr 20 in Mulchherstellung|r, die Leute auslassen und nicht auslassen sollten. Sie gibt dir Verzauberten Mulch: einen garantierten seltenen Fund bei deiner nächsten Pflückung, und dieser seltene Fund ist der Nachtlotus — das einzige Midnight-Kraut von seltener Qualität, ohne eigenes Vorkommen, und er steckt in allen vier Fläschchen und beiden Kesseln.\n\n|cffffcc00Danach Reiche Ernten|r für die lange Sicht: mehr Kräuter pro Vorkommen und mehr Fertigkeit, also öfter Spitzenqualität. Darin hat jedes Kraut einen eigenen Knoten, du kannst also auf das zielen, was sich auf deinem Realm am besten verkauft.\n\n|cffffcc00Lass die Überladung in Midnight links liegen.|r Sie wirkt nur bei den elementaren Vorkommen, kostet viele Punkte, und davon triffst du zu wenige. Nur sinnvoll, wenn du gezielt Motes farmst.\n\nDiese Punktzahlen stammen jeweils aus einer einzigen Quelle. Fahre im Spiel über den Knoten, bevor du klickst — der Tooltip hat die echte Zahl, und du bekommst nur einen Reset.",
	PROFNEXT_UNSPENT_LOCKED_FMT = "%s: %d Wissen auf der Bank, und noch kann es nirgends hin - keine Spezialisierung lässt sich freischalten, also zieh erst die Fertigkeit hoch (die erste Wahl kommt bei 25)",
	SMC_PIN_NEAREST_FP = "Richtet den Pfeil auf den nächsten Flugmeister von dort, wo du gerade stehst, nicht nur in dieser Stadt. Geht auch mit /mh fp.",
	FP_NEAREST_SET_FMT = "Pfeil steht auf dem nächsten Flugmeister: %s.",
	FP_NEAREST_NO_MAP = "Ich kann gerade nicht sehen, wo du bist, also kann ich keinen Flugmeister wählen.",
	FP_NEAREST_NONE = "Für dieses Gebiet sind noch keine Flugpunkte hinterlegt.",
	FP_NEAREST_NONE_FACTION = "Dieses Gebiet hat Flugpunkte, aber keinen, den deine Fraktion nutzen kann.",
	FP_NEAREST_NO_WAYPOINT = "Konnte dort keinen Wegpunkt setzen.",
	SMC_PIN_FLIGHTMASTER = "Silbermond hat zwei Flugmeister, die nützliche Frage ist also, welcher näher ist. Beide fliegen dieselben Routen.",
})

fill("frFR", {
	CMDLIST_FP = "Flèche vers le maître de vol le plus proche, où que tu sois",
	CMDLIST_COURSE = "Métiers 101 dans sa propre fenêtre, à côté du jeu",
	TOOLLP_COURSE_NAME = "Cours Métiers 101",
	TOOLLP_COURSE_DESC = "Le cours pour débutants dans une fenêtre à lui, pour que la liste des chapitres ait toute la hauteur et que le texte reste à côté du jeu pendant que tu fais l'exercice.",
	PROFACAD_BTN_FULL_COURSE = "Cours complet",
	PROFACAD_ADVISE_NEXT_POINTS_FMT = "Conseil : tes prochains points dans %s (racine %d/%d) — vise environ %d. Survole le nœud en jeu ; son infobulle donne le chiffre exact, et les guides ne sont pas d'accord entre eux là-dessus.",
	PROFACAD_ADVISE_NEXT_OPEN_FMT = "Conseil : ouvre %s — et arrête-toi là. C'est le déblocage qui rapporte ; les points au-delà sont un pari sur les prix des matériaux.",
	PROFACAD_ADVISE_GOALS_FMT = "À partir d'ici la route se divise, et les deux options diffèrent vraiment. %s",
	PROFACAD_ADVISE_GOAL_LINE_FMT = "%s %s (racine %d/%d).",
	PROFACAD_GOAL_GOLD = "Vendre aux autres :",
	PROFACAD_GOAL_SELF = "T'équiper, toi et ta guilde :",
	PROFACAD_CHOICES_HEADER = "Nœuds isolés dans tes arbres qui ne sont pas encore pleins :",
	PROFACAD_CHOICES_HEADER_MORE_FMT = "Nœuds isolés dans tes arbres qui ne sont pas encore pleins (%d sur %d) :",
	PROFACAD_CH_KNOWLEDGE_BODY = "Ton métier progresse de deux façons, et c'est exactement là que naît la confusion.\n\nTa |cffffffffCompétence|r monte en fabriquant des choses. Ça se fait tout seul. À côté de ça, tu accumules des |cffffffffpoints de connaissance|r, que tu ne gagnes justement pas en fabriquant mais par les commandes, les trésors et les livres — et ceux-là, tu les dépenses dans un arbre, où tu choisis ce en quoi tu deviens bon.\n\nL'image qui aide : |cffffffffla Compétence, c'est le nombre de fois où tu l'as fait ; la connaissance, c'est ce que tu as approfondi.|r Deux alchimistes à la même Compétence peuvent fabriquer des choses complètement différentes, parce qu'ils ont mis leurs points de connaissance ailleurs. C'est aussi pour ça que tu ne peux pas tout avoir. Il faut choisir.\n\n|cffffcc00D'où viennent les points — cinq sources, et la première écrase toutes les autres.|r\n\n1. Les commandes du jeu lui-même (commandes de l'onglet Client), à ton propre établi. Elles ont leur chapitre plus bas, y compris le piège qui consiste à toutes les faire en début de semaine.\n2. Fabriquer chaque chose une fois. La première fabrication de chaque recette donne un point. Fais ça avant de commencer à dépenser, tu auras plus de marge.\n3. Les trésors dans le monde. Éparpillés dans les zones de Midnight, des conteneurs donnent des points — une belle récolte si tu ne les as pas encore ramassés.\n4. Une quête hebdomadaire chez ton formateur, et un traité qu'un calligraphe peut te fabriquer.\n5. Les livres de réputation. Quelques factions te vendent un livre qui en donne dix d'un coup.\n\nLa Cuisine, la Pêche et l'Archéologie n'ont pas d'arbres et n'ont besoin d'aucun point.\n\nNe t'inquiète pas d'être \"à la traîne\" : les semaines manquées reviennent lentement grâce à un système de rattrapage, et ce cours t'accompagne pas à pas.",
	PROFACAD_CH_TREES_ADVANCED = "Où faut-il cliquer, concrètement ? Ouvre ta fenêtre de métier (celle avec tes recettes), puis regarde les onglets en bas : Recettes, Spécialisations, Commandes d'artisanat. C'est Spécialisations qu'il te faut — c'est là que vivent tes arbres et que se dépensent tes points de connaissance. Rien ne se passe tant que tu n'as pas confirmé, tu peux donc l'ouvrir et simplement regarder ce qu'il y a dedans. Tu ne sais pas quel arbre ? Reviens ici : l'aperçu Métiers te nomme le prochain nœud dès qu'il arrive à lire tes arbres.",
	PROFACAD_CH_TREES_BODY = "Trois ou quatre |cffffffffroues|r sont posées là côte à côte. Chacune est faite de cases rondes reliées par des lignes, et tu la reconnais à l'anneau qui l'entoure et qui se remplit à mesure que tu y mets des points — survole-la et tu verras quelque chose comme \"3 / 30\" : trois points dedans, trente pour être plein. Les guides appellent ces cases des nœuds. Chaque roue a une grande case au milieu (la racine) et de plus petites autour, qui n'apparaissent que lorsque celle du milieu est assez remplie. Regarder ne coûte rien : rien ne change tant que tu n'as pas confirmé.\n\n|cffffcc00La seule règle qui compte : ne disperse pas tes points.|r\n\nMettre un peu partout donne l'impression d'être malin. C'est l'erreur la plus coûteuse qui soit, et tout le monde la commet. La raison : tout ce qui vaut la peine se trouve derrière un |cffffffffseuil|r. À trente points il se passe quelque chose ; à quinze, rien du tout. Quatre cases à moitié pleines ne te donnent donc |cffffffffrien|r — tu as dépensé cent points et tu ne peux toujours rien faire de spécial.\n\nChoisis-en une. Termine-la. Passe ensuite à la suivante. La hauteur d'un seuil varie selon le métier et même selon la case, alors ne te fie pas à un chiffre lu dans un guide : survole la case et elle te le dit.\n\n|cffffcc00Ce que t'apporte l'ouverture d'une branche|r n'est pas ce que la plupart des gens imaginent, et c'est une bonne nouvelle. La recette vient en général du fait d'|cffffffffouvrir|r une branche plutôt que de la remplir — tu l'ouvres et tu peux fabriquer la chose tout de suite. Les points que tu y mets ensuite ne la rendent pas possible, ils la rendent |cffffffffmeilleure|r. Ouvrir ne te coûte pas non plus de point de connaissance ; pour ça tu reçois des déblocages séparés, à des paliers fixes dans la case du milieu. Mais tu n'en reçois pas un nombre illimité. Pour ouvrir une deuxième branche, tu dois d'abord aller plus loin au milieu. Ouvrir est gratuit, mais rationné.\n\n|cffffcc00Et certaines choses sont tout simplement éteintes,|r et c'est le piège qui fait conclure aux gens que le jeu est cassé. Quelques branches activent quelque chose qui n'existait pas avant. Un ingénieur peut recycler du vieil équipement, mais il n'en |cffffffffdécouvre des recettes|r qu'après y avoir mis des points — sans ça, tu recycles éternellement et rien ne se passe. Un couturier ne voit tomber le tissu cher qu'une fois la branche correspondante apprise. Un herboriste ne peut cueillir depuis sa monture qu'après être allé assez loin. Si quelque chose \"n'a pas l'air de marcher\", vérifie d'abord si ça ne doit pas encore être activé.\n\n|cffffcc00Tu as droit à une seule remise à zéro.|r Depuis le patch 12.1 tu peux annuler tes points |cffffffffune fois par métier|r, chez Theremis à Lune-d’Argent, près de la station de commandes. Une fois — après ça, tes choix sont définitifs. Tu désapprends aussi les recettes que ces points avaient débloquées ; elles reviennent quand tu reposes les points, mais ne te laisse pas surprendre. Et il n'y a pas de quoi s'inquiéter : continue à collecter et tu pourras à terme remplir chaque branche, donc les points ne peuvent pas vraiment être |cffffffffgaspillés|r — seulement se trouver au mauvais endroit pendant les mois où ça compte.\n\nTu as un choix d'arbre à 25, 50, 60 et 75 de Compétence. Ce n'est pas le jeu qui décide lequel ; c'est toi. Une fois que tu as des métiers, leurs propres chapitres plus bas donnent un build de départ concret, et l'aperçu Métiers montre des conseils en direct pour tes propres arbres.",
	PROFACAD_CH_QUALITY_TITLE = "La qualité — pourquoi son épée est meilleure que la tienne",
	PROFACAD_CH_QUALITY_INTRO = "Deux joueurs utilisent la même recette et l'un des deux résultats sort meilleur. Ce n'est ni de la malchance ni un bug : les objets fabriqués ont un rang de qualité.",
	PROFACAD_CH_QUALITY_ADVANCED = "Où faut-il cliquer, concrètement ? Ouvre une recette dans ta fenêtre de métier et regarde l'encadré Détails de la fabrication à droite : il montre la Difficulté face à ta Compétence, et c'est tout le calcul en deux chiffres. Clique sur n'importe quel composant de la recette et tu peux choisir quelle qualité de matériau y entre — l'infobulle dit \"Left Click to allocate reagent qualities\". Il y a aussi une case \"Use Best Quality Reagents\" qui prend automatiquement tes meilleurs. Pratique, mais ça consomme tes matériaux chers sans te le demander deux fois.",
	PROFACAD_CH_QUALITY_BODY = "L'image qui aide : la recette dit |cffffffffce que|r tu fabriques, la qualité dit à quel point c'est réussi. Deux boulangers avec la même recette ne font pas le même pain.\n\nTu ne le lis pas sur un chiffre mais sur une petite |cffffffffforme|r. L'infobulle affiche \"Qualité :\" avec la forme à côté — un losange gris, c'est bas ; un pentagone doré, c'est haut. Dans ta fenêtre de métier, la même chose apparaît sous forme de barre, la forme la plus basse à gauche et la plus haute à droite, avec un repère blanc qui montre à peu près où ta fabrication va atterrir.\n\nÇa compte pour trois raisons, et la troisième surprend tout le monde une fois. Un meilleur équipement et des potions plus fortes, évidemment. Plus d'or : la même recette, Peau tissée d’écailles, se vendait 10g94 au rang le plus bas et 21g12 au plus haut — presque le double, pour les mêmes matériaux et le même clic. Chaque rang est réellement un |cffffffffobjet distinct|r avec sa propre annonce à l'hôtel des ventes, donc ils ne s'empilent pas ensemble. Et la troisième : si quelqu'un commande une qualité minimale que tu n'atteins pas, tu |cffffffffne peux pas du tout terminer cette commande|r. Pas \"le résultat sera moins bon\" — tu ne peux littéralement pas la rendre.\n\nCe qui décide de tout, c'est un seul chiffre : ta |cffffffffCompétence|r au moment où tu appuies sur fabriquer. Chaque recette a une difficulté. Confortablement au-dessus, tu obtiens le rang maximum ; en dessous, non.\n\nCe chiffre est construit à partir de quatre choses. Ta Compétence de base, qui monte à mesure que tu fabriques et finit par plafonner. Tes points de connaissance, qui ajoutent de la Compétence |cffffffffuniquement à ce type de recette|r — des points dans les anneaux rendent tes anneaux meilleurs, pas tes colliers. Ton équipement de métier : un outil et deux accessoires par métier, dans leurs propres emplacements, qu'énormément de gens laissent tout simplement vides. Et tes composants, qui portent les mêmes formes de qualité, donc les matériaux bon marché ne sont pas toujours moins chers.\n\nSi tu atterris à un cran du but, il existe un filet de sécurité : la Concentration. Elle a son propre chapitre plus bas.\n\nUn piège mérite d'être nommé, parce qu'il coûte vraiment de l'or : |cffffffffêtre à moitié spécialisé coûte plus cher que ne pas se spécialiser du tout|r. Répartis tes points sur quatre branches et tu seras juste en dessous partout. Tu peux tout fabriquer à un rang médiocre, et le médiocre ne se vend pas et se fait refuser par les commandes.\n\nSi tu récoltes au lieu de fabriquer, tes herbes et ton minerai ont aussi des rangs — mais seulement |cffffffffdeux|r dans Midnight, pas toute l'échelle. Plus de Compétence signifie plus souvent le meilleur des deux. Il n'y a pas de troisième rang à courir après.",
	PROFACAD_CH_QUALITY_TASK = "Ouvre une recette et trouve la barre Qualité et l'encadré Détails de la fabrication.",
	PROFACAD_CH_STATS_TITLE = "Les six chiffres que personne n'explique",
	PROFACAD_CH_STATS_INTRO = "Fabrication multiple, Ingéniosité, Adresse. Le jeu ne dit jamais à quoi elles servent, et la plupart des joueurs les recherchent à nouveau à chaque fois.",
	PROFACAD_CH_STATS_ADVANCED = "Où les voit-on, concrètement ? Ouvre n'importe quelle recette dans ta fenêtre de métier et regarde l'encadré Détails de la fabrication à droite — les six y apparaissent en pourcentages, par exemple Ingéniosité 4%, Fabrication multiple 4%, Inventivité 19%. Le même encadré montre la Difficulté face à ta Compétence, et en dessous, ce que la Concentration te coûterait pour forcer le rang de qualité suivant.",
	PROFACAD_CH_STATS_BODY = "L'image qui aide : |cffffffffla Compétence décide de la qualité du résultat, ces six-là décident de ce que ça t'a coûté d'y arriver.|r La Compétence concerne le résultat ; celles-ci concernent le chemin pour y arriver.\n\nIl y en a trois pour la fabrication et trois pour la récolte, donc tu n'as jamais besoin des six à la fois.\n\nFabrication. L'|cffffffffIngéniosité|r signifie qu'une fabrication consomme parfois moins que prévu et que tu gardes les matériaux. Ça marche sur tout, et c'est la seule qui améliore ton bénéfice sur la commande de quelqu'un d'autre, parce que les restes te reviennent à toi et pas au client. La |cffffffffFabrication multiple|r signifie que tu obtiens parfois plus d'un exemplaire avec les mêmes matériaux. L'|cffffffffInventivité|r te rend une partie de ta Concentration.\n\nLe piège dans cette liste : |cffffffffla Fabrication multiple ne fait rien pour l'équipement.|r Un exemplaire supplémentaire n'a de sens que pour les choses qui s'empilent — potions, gemmes, matériaux. Un anneau ou un plastron ne double jamais, donc si tu fabriques surtout de l'équipement, la Fabrication multiple est gâchée. Et sur les commandes des autres, les exemplaires en plus vont au |cffffffffclient|r, pas à toi. Ce dernier point est ce que les joueurs se racontent entre eux ; Blizzard ne l'a jamais confirmé.\n\nRécolte. La |cffffffffFinesse|r t'en donne plus par nœud, c'est-à-dire ton volume et donc ton or. La |cffffffffPerception|r te donne une meilleure chance d'obtenir le matériau rare plutôt que davantage du matériau ordinaire. L'|cffffffffAdresse|r raccourcit l'animation de récolte.\n\nLaquelle compte dépend de ce que tu fais, et c'est ça la partie utile. L'Herboristerie veut la Finesse : sur une heure de jeu, tu passes bien plus de temps à chercher et à voler qu'à cueillir, donc récolter plus vite règle le mauvais problème. Le Minage, c'est pareil, et la Perception y est faible, parce que le minerai rare vers lequel elle t'oriente sert peu dans les recettes. |cffffffffLe Dépeçage inverse la règle|r — dès que tu chasses les bêtes rares, la Perception devient forte, parce que c'est là que se trouvent les butins chers. C'est le seul métier de récolte où c'est vrai. Ces trois-là sont des jugements sur la façon dont les métiers se jouent, pas des chiffres que quelqu'un aurait publiés.\n\nLes valeurs viennent de deux endroits que tu contrôles : tes points de connaissance, puisque beaucoup de nœuds donnent l'une de ces six, et ton équipement de métier. Donc quand tu dépenses un point, regarde quelle stat se cache sous le nœud et si elle correspond à ce que tu comptes vraiment fabriquer.\n\nSi tu ne retiens qu'une chose : |cffffffffdécide ce que tu vas fabriquer, puis choisis ta stat.|r Quelqu'un qui vend des potions et quelqu'un qui fabrique des anneaux ont des intérêts opposés, et un guide qui dit \"la Fabrication multiple, c'est le meilleur\" ne te dit pas à qui il s'adresse.",
	PROFACAD_CH_STATS_TASK = "Ouvre Détails de la fabrication sur une recette et lis tes trois pourcentages à toi.",
	PROFACAD_CH_CONC_TITLE = "La Concentration, le frein d'urgence",
	PROFACAD_CH_CONC_INTRO = "Parfois tu atterris à un rang du but, et fabriquer la chose quand même donne l'impression d'un gâchis. C'est exactement à ça que sert la Concentration.",
	PROFACAD_CH_CONC_ADVANCED = "Où la trouve-t-on, concrètement ? Dans ta fenêtre de métier c'est une barre vers le haut qui montre ton total actuel, et quand tu ouvres une recette il y a un bouton en forme de flamme à côté du bouton de fabrication qui montre ce que cette fabrication précise coûterait. Le coût varie selon la recette, alors lis-le avant d'appuyer.",
	PROFACAD_CH_CONC_BODY = "L'image : |cffffffffc'est une batterie qui se recharge toute seule.|r Tu ne fais rien pour ça, elle se remplit d'elle-même, et tu peux la vider au moment où ça compte. Dépense-la sur une fabrication et le rang de qualité suivant est |cffffffffgaranti|r — pas une chance, pas un jet de dés. Le jeu le dit lui-même : \"Apply 358 concentration to guarantee the next quality for this recipe.\"\n\nVoici toute l'histoire, et c'est pour ça que les gens s'en servent mal. La batterie contient |cffffffff1000|r et se recharge d'environ |cffffffff250 par jour|r, soit à peu près quatre jours pour passer de vide à pleine. C'est lent. Chaque fois que tu l'utilises, tu dépenses une partie de tes prochains jours, et quand elle est vide tu ne peux qu'attendre.\n\nChaque métier a sa |cffffffffpropre|r batterie. Un alchimiste qui cueille aussi des herbes en a deux, et elles n'ont rien à voir l'une avec l'autre.\n\nCe n'est pas bon marché à l'usage non plus. Une vraie fabrication a coûté 358 sur les 1000 — plus d'un tiers de la batterie pour un seul objet.\n\nÇa vaut le coup pour : un objet à un rang du but que tu vas porter ou utiliser toi-même ; une commande avec une qualité minimale que tu n'atteindrais pas autrement, puisque sans ça tu ne peux pas du tout terminer cette commande ; et tout ce qui est cher, où l'écart entre deux rangs vaut plus qu'une journée de batterie.\n\nÇa ne vaut pas le coup pour : quelque chose que tu fabriques déjà au rang maximum de toute façon, où tu ne gagnes rien et où tu perds la batterie. C'est l'erreur la plus courante, parce que les gens laissent le bouton activé et ne le remarquent jamais. Et la production de masse bon marché — cinquante potions un rang plus haut, c'est agréable, mais ça ne vaut pas quatre jours.\n\nTu en récupères une partie. L'|cffffffffInventivité|r, l'une des six stats, te rembourse de temps en temps une part de ce que tu viens de dépenser, et le jeu te le signale. C'est exactement pour ça que l'Inventivité ne devient intéressante qu'une fois que tu vises la qualité : sans dépense, il n'y a rien à rembourser.\n\nEncore une chose, qui concerne les gens plutôt que la mécanique. Si tu brûles de la Concentration pour atteindre la qualité sur la commande de |cffffffffquelqu'un d'autre|r, c'est lui qui reçoit le meilleur objet et toi qui payes avec une batterie qui met des jours à se remettre. Les artisans expérimentés facturent plus pour ça. Ce n'est pas une règle et il n'y a pas de tarif fixe, mais il est bon de savoir que demander n'est pas de la cupidité et qu'être sollicité n'a rien d'étrange.\n\nLa Concentration n'est pas un système à gérer ou à optimiser. C'est un frein, là pour le moment où tu es à un rang d'une chose qui en vaut la peine. Si elle se remplit pendant que tu joues, tout va bien. Si elle reste au maximum pendant des semaines, tu laisses probablement de la qualité de côté.",
	PROFACAD_CH_CONC_TASK = "Trouve ta barre de Concentration et vérifie si elle est restée au maximum.",
	PROFACAD_CH_GOLD_TITLE = "Gagner de l'or sans se raconter d'histoires",
	PROFACAD_CH_GOLD_INTRO = "Il n'y a qu'un seul calcul ici, et presque personne ne le fait : ce qu'on te paye, moins tout ce qui est entré dedans, moins 5% pour l'hôtel des ventes.",
	PROFACAD_CH_GOLD_BODY = "Le mot que les gens sautent, c'est |cfffffffftout|r. Les herbes que tu as cueillies toi-même ne sont |cffffffffpas gratuites|r. Elles ont un prix de marché, et les mettre dans une potion au lieu de les vendre veut dire que tu l'as dépensé — tu te l'es simplement payé à toi-même. Si l'herbe vaut plus que la potion, fabriquer revient à |cffffffffperdre de l'argent d'une manière qui donne l'impression d'en gagner|r.\n\n|cffffcc00Il y a deux marchés, et ils obéissent à des lois opposées.|r Presque toute la confusion sur le fait qu'un métier \"rapporte\" ou non vient du mélange des deux.\n\nLe premier, ce sont les |cffffffffmarchandises|r : matériaux, potions, flacons, gemmes — tout ce qui s'empile. Tu vends des objets, et tu es en concurrence avec toute la région plutôt qu'avec ton seul royaume. Les acheteurs ne voient rien d'autre que le prix.\n\nLe second, c'est l'|cfffffffféquipement fabriqué|r. Il reste sur ton royaume, et le meilleur se lie à une seule personne, donc il ne peut pas du tout aller à l'hôtel des ventes. Ici tu ne vends pas des objets, tu vends ton savoir-faire.\n\n|cffffcc00Pourquoi le marché des marchandises s'effondre toujours|r vaut la peine d'être compris, et aucune des raisons n'est \"il y a beaucoup de joueurs\". Le jeu achète automatiquement l'annonce la moins chère, donc un cuivre au-dessus du prix le plus bas signifie pas de vente. Tu es en concurrence avec tous les royaumes de ta région en même temps. La Fabrication multiple distribue de l'offre supplémentaire gratuite, et ne fonctionne que sur les choses qui s'empilent — précisément ce marché. Et les consommables n'ont que deux rangs de qualité au lieu de toute l'échelle, donc la chute jusqu'au fond est plus courte.\n\nIl y a un frein : tant que les artisans ont encore besoin de la Concentration pour atteindre la qualité maximale, cette qualité reste rare. Dès qu'ils y arrivent sans aide, le frein lâche et le prix tombe. Sur ce marché, tu gagnes donc dans la fenêtre |cffffffffavant|r que ça n'arrive.\n\n|cffffcc00Ce qui protège vraiment un prix, c'est un verrou sur l'offre.|r Il y en a quatre sortes : un cooldown sur la recette, un composant que l'artisan ne peut jamais se fournir lui-même, une recette derrière de la réputation, et la Concentration, parce qu'elle se recharge lentement. |cffffffffLà où il y a un verrou, il y a de la marge. Là où il n'y en a pas, il y a du volume et presque aucune marge.|r C'est tout le sujet en une phrase.\n\nLa récolte est l'exception qui le prouve : ce que tu cueilles n'a pas de coût, donc tu |cffffffffne peux pas|r perdre — la seule façon de gagner de l'or où un débutant ne peut pas se tromper. Mais pas de coût veut aussi dire pas de barrière, donc le prix se fixe à ce que le récolteur le moins exigeant acceptera.\n\n|cffffcc00Chaque objet fabriqué tombe dans l'une de trois cases, et la troisième est le piège.|r Librement échangeable le dit dans sa propre infobulle : \"S’achète et se vend à l’hôtel des ventes.\" Ce qui est lié ne peut pas passer à l'hôtel des ventes mais |cffffffffpeut|r se vendre via une commande, qui livre directement au client — là tu vends du travail, pas un produit. Et |cffffffffLié au bataillon|r ne peut faire ni l'un ni l'autre : pas d'hôtel des ventes, pas de commande, seulement toi et tes propres personnages. Ce n'est pas un commerce, c'est un service.\n\nLes alchimistes en particulier : les deux chaudrons qui approvisionnent tout ton raid sont |cfffffffftous les deux|r Lié au bataillon. Tu ne pourras jamais les vendre. Tu les fabriques, tu les apportes, et ce que tu récupères, c'est de la bonne volonté. C'est très bien — mais ça devrait être un choix et pas une découverte après coup, parce qu'il y entre des matériaux chers.\n\n|cffffcc00En gros ou sur commande ?|r En gros, tu vends le produit, tu concurrences toute la région sur le prix, ton volume est illimité et ta marge ne cesse de s'amincir. Sur commande, tu vends ton savoir-faire, tu concurrences les artisans de ton propre royaume sur la réputation, ton volume est limité et ta marge plus stable. D'où découle un calcul plutôt qu'une opinion : |cffffffffla file des commandes publiques n'est pas un commerce|r. Tu en gardes quatre et il t'en revient une par jour — environ sept par semaine. C'est de l'argent de poche. |cffffffffLes commandes personnelles et de guilde sont illimitées|r, donc une poignée d'habitués qui t'envoient des commandes directement, c'est là qu'est le vrai travail.\n\n|cffffcc00La plus grosse erreur de débutant|r, c'est de fabriquer avant d'avoir vérifié ce que coûtent les matériaux. Elle a deux visages et c'est la même erreur : \"je l'ai cueilli moi-même, donc c'est gratuit\" et \"j'ai cette recette, donc je vais la fabriquer\". Avoir une recette ne dit rien sur sa rentabilité. |cffffffffVérifie d'abord ce que ça coûte. Décide ensuite si tu le fabriques.|r\n\nEt méfie-toi de chaque \"X or par heure\" sorti d'un guide ou d'une vidéo : ça varie selon le royaume et c'est en général inventé. Mesure plutôt sur ton propre royaume. Auctionator montre ce que les choses coûtent vraiment ; CraftSim calcule ce que rapporte une fabrication face aux prix des matériaux du jour, et c'est la chose la plus utile à installer si tu veux gagner sérieusement.",
	PROFACAD_CH_GOLD_DATED_202608 = "|cffffcc00Où en sont les choses fin août 2026 — et cette moitié-ci se périme.|r La saison 2 a quelques jours, alors traite les paragraphes ci-dessous comme un instantané et non comme une règle. Bon à savoir : presque tous les guides \"saison 2\" qui existent sont datés d'avant même le début de la saison, ce qui fait de leurs affirmations des prédictions plutôt que des observations. Personne n'a publié la moindre série de prix pour ces premières semaines.\n\n|cffffffffAlchimie.|r Les potions et les flacons sont librement échangeables et se vendent bien tant que le raid est neuf et que la demande est à son pic — mais c'est le marché des marchandises en pleine action, alors attends-toi à voir la marge s'effondrer à mesure que davantage d'artisans atteignent la qualité maximale sans Concentration. Le Synergiste extraordinaire est le revenu le plus stable : il porte un cooldown d'environ une journée, donc personne ne peut inonder le marché, ce qui est exactement le verrou décrit plus haut, et il alimente les deux chaudrons ainsi que la pierre épique. La décoration de logement (Housing) est l'option sous-estimée — six recettes, échangeables, et ça ne s'empile pas, donc ça se joue sur ton propre royaume plutôt que dans le pot régional. Une histoire de marché à retenir : la nouvelle potion de soins de 12.1 consomme 25 exemplaires de l'ancienne, donc l'ancienne potion est passée du statut de produit fini à celui d'ingrédient et a perdu environ la moitié de sa valeur en tant que produit. Ceux qui en avaient fait des stocks en juillet ont pris cette division par deux en pleine figure le 11 août.\n\n|cffffffffHerboristerie.|r Le Lotus nocturne est l'herbe chère, et la raison est précise : c'est la seule herbe de Midnight de qualité rare, elle n'a pas de nœud à elle (elle apparaît comme prise accessoire de toutes les autres herbes), et elle figure dans les quatre flacons et les deux chaudrons — onze recettes au total. Les deux nouveaux matériaux de l'Île Annelée sont tous les deux échangeables, avec une mise en garde : ils ne sont |cffffffffpas|r exclusifs aux herboristes. Les mineurs les tirent de leurs propres nœuds, et l'un des deux tombe aussi des animaux via le Dépeçage. Plusieurs guides laissent entendre le contraire.",
	PROFACAD_CH_GOLD_TASK = "Avant ta prochaine fabrication, regarde ce que coûtent ses matériaux — et décide seulement ensuite de la faire.",
	PROFACAD_CH_WORKORDERS_TITLE = "Les commandes d'artisanat : acheter le savoir-faire d'un autre",
	PROFACAD_CH_WORKORDERS_INTRO = "À l'hôtel des ventes, tu achètes des objets qui existent déjà. À la station de commandes, ça marche dans l'autre sens : c'est toi qui apportes les matériaux et qui payes quelqu'un pour le travail.",
	PROFACAD_CH_WORKORDERS_ADVANCED = "Deux choses qui font croire que le système est cassé alors qu'il ne l'est pas. À ton propre établi, la liste des commandes publiques reste vide tant que tu n'appuies pas sur |cffffffffRecherche|r — rien d'anormal, elle ne se charge simplement pas toute seule. Et l'homme qui se tient à la station de commandes, le Capitaine Fuselige, n'a rien à voir avec tout ça : il distribue la quête d'introduction de ton métier, tes quêtes hebdomadaires et des sacs de matériaux gratuits. Utile, mais pas ce pour quoi tu es venu.",
	PROFACAD_CH_WORKORDERS_BODY = "Ça fonctionne ainsi parce que le meilleur équipement fabriqué se lie à une seule personne dès l'instant où il existe. Personne ne peut le fabriquer à l'avance et le poser en rayon, donc quelqu'un doit le faire |cffffffffspécialement pour toi|r.\n\n|cffffcc00Il y a deux guichets, et c'est là que ça coince généralement.|r Pour te faire fabriquer quelque chose, va à la station de commandes du Bazar de Lune-d’Argent — le grand marteau doré sur ta minicarte. La personne qu'il te faut est Mar'nah. Pour fabriquer quelque chose pour quelqu'un d'autre, va plutôt à |cffffffffl'établi de ton propre métier|r. Si tu n'es pas juste à côté, il n'y a ni bouton ni liste, et on dirait que le système n'existe pas. C'est l'erreur la plus courante, et le jeu ne l'explique nulle part.\n\n|cffffcc00Se faire fabriquer quelque chose.|r Choisis ton objet, puis choisis à qui tu le demandes. À personne en particulier (le bouton dit Public Order) : tout le monde sur ton royaume la voit et le premier qui la prend la fabrique. Rapide, mais tu obtiens ce que tu obtiens — |cffffffffici tu ne peux pas exiger de qualité|r, et tu dois envoyer toi-même tous les matériaux. À un joueur précis (Personal Order) : là tu peux fixer une qualité minimale, et tu peux convenir qu'il ajoute des matériaux à lui. À toute ta guilde (Guild Order) fonctionne pareil et atteint aussi les membres de guilde d'autres royaumes. C'est toi qui fixes le paiement, et un bouton à côté montre ce que d'autres ont payé récemment pour le même objet.\n\nTrois choses à savoir avant de cliquer sur commander. Certains composants spéciaux ne peuvent jamais être fournis par l'artisan, donc ceux-là tu les envoies toujours toi-même. Les matériaux dans la banque de ton bataillon |cffffffffne comptent pas|r — mets-les dans tes sacs. Et l'objet se lie à |cfffffffftoi|r, alors passe la commande sur le personnage qui va le porter, pas sur celui qui détient l'or. Une fois que quelqu'un a pris la commande, tu ne peux plus l'annuler ; l'objet arrive par la poste.\n\n|cffffcc00Fabriquer pour les autres.|r À ton établi, tu vois ce que tu vas gagner avant de commencer. Une fois lancé, tu as |cffffffff30 minutes|r pour finir — assez pour aller chercher quelque chose, pas assez pour aller manger.\n\nTu ne peux pas prendre des commandes publiques à l'infini : tu en tiens |cffffffff quatre|r, et |cffffffffil en revient une chaque jour|r. Donc environ sept par semaine, pas quatre par jour. Les commandes presque expirées sont gratuites à prendre.\n\nSi une commande te refuse, c'est l'une de ces quatre choses : tu ne connais pas la recette, ta spécialisation n'est pas assez avancée pour les extras qu'elle demande, elle veut une qualité que tu n'atteins pas, ou ton quota est épuisé.\n\nEt une qui te coûte discrètement de l'argent : |cffffffffregarde à qui appartiennent les matériaux que tu utilises.|r Sur les commandes publiques le client fournit toujours tout, mais sur les autres types il peut ne rien fournir du tout — et là tu fabriques gaiement avec ton propre stock coûteux pour un pourboire.",
	PROFACAD_CH_WORKORDERS_TASK = "Trouve la station de commandes du Bazar de Lune-d’Argent, puis trouve l'établi de ton propre métier. Ce n'est pas le même endroit.",
	PROFACAD_CH_PATRON_TITLE = "L'onglet Client, ton moteur hebdomadaire de points de connaissance",
	PROFACAD_CH_PATRON_INTRO = "Le quatrième type de commande vient du jeu lui-même plutôt que d'un joueur, et c'est celui que la plupart des gens ne trouvent jamais.",
	PROFACAD_CH_PATRON_BODY = "À ton propre établi il y a un onglet |cffffffffClient|r où le jeu te donne des commandes. Aucun autre joueur, aucune concurrence — elles sont à toi seul. Ce qu'on te paye n'est pas vraiment de l'or mais des |cffffffffpoints de connaissance|r : les mêmes points qui rendent ton métier plus fort.\n\nC'est de loin ta plus grosse source hebdomadaire de points. Saute-les et tu prends du retard sans jamais comprendre pourquoi les autres avancent plus vite.\n\nUn nouveau lot arrive tous les quelques jours. Chaque commande demande une certaine qualité, et parfois tu dois fournir les matériaux toi-même — vérifie-le, parce qu'une commande coûteuse pour deux points n'en vaut pas toujours la peine. Tu as le droit d'en sauter une.\n\n|cffffcc00Et maintenant le piège.|r Le jeu te donne aussi chaque jour une petite commande à un point, mais |cffffffffuniquement tant que tu es en retard sur ton objectif hebdomadaire|r. Fais toutes les grosses commandes le lundi et tu es à jour — donc les petites quotidiennes s'arrêtent pour le reste de la semaine.\n\nDonc : |cfffffffflaisse les grosses commandes jusqu'à ce qu'elles soient près d'expirer|r. Tu continues à ramasser les petites entre-temps, et tu termines la semaine avec plus de points que tu n'en aurais eu. Ça semble contre-intuitif. C'est vrai quand même.",
	PROFACAD_CH_PATRON_TASK = "Ouvre l'onglet Client à ton propre établi et regarde ce que cette semaine propose.",
	PROFACAD_CH_ALCHEMY_BODY = "L'Alchimie t'offre un arbre à 25, 50, 60 et 75 de Compétence — ce n'est pas le jeu qui choisit, c'est toi. Les quatre sont Prodige des potions (potions, avec un côté Lumière et un côté Vide), Maîtrise des flacons, Expertise en transmutation et Maîtrise d’alchimie.\n\n|cffffcc00Build de départ, dans cet ordre.|r |cffffffffProdige des potions|r d'abord : le remplir donne le Chaudron de potion de Lumière du Vide, qui sert ton or et ta guilde en même temps. Ensuite |cffffffffVoie de la Lumière|r et |cffffffffAlchimiste prolifique – Lumière|r, qui est le nœud Fabrication multiple — la Lumière parce que c'est la potion qui se vend cette saison. Puis |cffffffffMaîtrise d’alchimie|r et, à l'intérieur, |cffffffffReuse|r, qui te rend des herbes et qui est fort si tu les cueilles aussi toi-même.\n\nAprès ça, environ 15 points dans |cffffffffMaîtrise des flacons|r, qui double la durée de tes propres flacons, puis |cffffffffSpécialiste sin’dorei|r. |cffffffffExpertise en transmutation|r vient en dernier, pas en deuxième.\n\n|cffffffffSecrets haranir n'est pas un détail.|r Sa propre infobulle mentionne \"et du chaudron de flacons sin’dorei\" — sans points là-dedans, tu ne peux pas fabriquer le Chaudron de flacons sin’dorei au rang maximum. Les guides paraphrasent ce nœud en \"phials only\" et laissent tomber la demi-phrase qui compte.",
	PROFACAD_CH_HERBALISM_BODY = "Chaque herbe pousse dans chaque zone, tu n'as donc pas à te casser la tête pour choisir une zone. L'ordre ci-dessous est ce que l'itinéraire de cet addon recommande maintenant, et chaque étape est une chose que tu débloques plutôt qu'une répartition vague.\n\n|cffffcc00D'abord : environ 40 points dans Botanique.|r C'est la cueillette depuis ta monture, et c'est de loin le plus gros gain de temps du métier — sans ça, tu descends et remontes à chaque plante. Les druides sautent cette étape : ils récoltent déjà depuis leur monture.\n\n|cffffcc00Puis environ 20 dans Paillis|r, que les gens laissent de côté et qui ne le mérite pas. Il te donne le Paillis imprégné : une trouvaille rare garantie à ta prochaine cueillette, et cette trouvaille rare, c'est le Lotus nocturne — la seule herbe de Midnight de qualité rare, sans nœud à elle, présente dans les quatre flacons et les deux chaudrons.\n\n|cffffcc00Ensuite Récoltes abondantes|r pour le long terme : plus d'herbes par nœud et plus de Compétence, donc plus souvent la qualité maximale. À l'intérieur, chaque herbe a son propre nœud, tu peux donc viser celle qui se vend le mieux sur ton royaume.\n\n|cffffcc00Laisse Surcharge de Midnight tranquille.|r Elle ne fonctionne que sur les nœuds élémentaires, elle coûte beaucoup de points, et tu en croises trop peu. Ça ne vaut le coup que si tu farmes des motes exprès.\n\nCes nombres de points viennent chacun d'une seule source. Survole le nœud en jeu avant de cliquer — l'infobulle a le vrai chiffre, et tu n'as droit qu'à une seule remise à zéro.",
	PROFNEXT_UNSPENT_LOCKED_FMT = "%s : %d points de connaissance en réserve, et rien ne peut encore les absorber - aucune spécialisation n'est débloquable, alors monte d'abord la Compétence (le premier choix arrive à 25)",
	SMC_PIN_NEAREST_FP = "Pointe la flèche vers le maître de vol le plus proche depuis l'endroit où tu te trouves, pas seulement dans cette ville. Disponible aussi via /mh fp.",
	FP_NEAREST_SET_FMT = "Flèche placée sur le maître de vol le plus proche : %s.",
	FP_NEAREST_NO_MAP = "Je ne peux pas voir où tu es en ce moment, donc je ne peux pas choisir de maître de vol.",
	FP_NEAREST_NONE = "Aucun point de vol enregistré pour cette zone pour l'instant.",
	FP_NEAREST_NONE_FACTION = "Cette zone a des points de vol, mais aucun utilisable par ta faction.",
	FP_NEAREST_NO_WAYPOINT = "Impossible de placer un point de route là.",
	SMC_PIN_FLIGHTMASTER = "Lune-d’Argent a deux maîtres de vol, la vraie question est donc de savoir lequel est le plus proche. Les deux desservent les mêmes routes.",
})

fill("esES", {
	CMDLIST_FP = "Flecha hacia el maestro de vuelo más cercano, estés donde estés",
	CMDLIST_COURSE = "Profesiones 101 en su propia ventana, junto al juego",
	TOOLLP_COURSE_NAME = "Profesiones 101",
	TOOLLP_COURSE_DESC = "El curso para principiantes en una ventana propia, para que la lista de capítulos tenga toda la altura y el texto se quede junto al juego mientras haces la tarea.",
	PROFACAD_BTN_FULL_COURSE = "Curso completo",
	PROFACAD_ADVISE_NEXT_POINTS_FMT = "Consejo: los próximos puntos van a %s (raíz %d/%d) — apunta a unos %d. Pasa el cursor por el nodo en el juego; su tooltip da el número exacto, y las guías no se ponen de acuerdo.",
	PROFACAD_ADVISE_NEXT_OPEN_FMT = "Consejo: abre %s — y ahí párate. Lo que rinde es desbloquearlo; los puntos de más son una apuesta sobre los precios de los materiales.",
	PROFACAD_ADVISE_GOALS_FMT = "A partir de aquí la ruta se bifurca, y las dos opciones se diferencian de verdad. %s",
	PROFACAD_ADVISE_GOAL_LINE_FMT = "%s %s (raíz %d/%d).",
	PROFACAD_GOAL_GOLD = "Vender a otros:",
	PROFACAD_GOAL_SELF = "Equiparte a ti y a tu hermandad:",
	PROFACAD_CHOICES_HEADER = "Nodos sueltos dentro de tus árboles que aún no están llenos:",
	PROFACAD_CHOICES_HEADER_MORE_FMT = "Nodos sueltos dentro de tus árboles que aún no están llenos (%d de %d):",
	PROFACAD_CH_KNOWLEDGE_BODY = "Tu profesión crece de dos maneras, y ahí es exactamente donde está la confusión.\n\nTu |cffffffffhabilidad|r sube fabricando cosas. Eso ocurre solo. Junto a ella vas reuniendo |cffffffffpuntos de conocimiento|r, que no se consiguen fabricando en absoluto sino con pedidos, tesoros y libros — y esos los gastas en un árbol, donde eliges en qué te vuelves bueno.\n\nLa imagen que ayuda: |cffffffffla habilidad es cuántas veces lo has hecho; el conocimiento es en qué has profundizado.|r Dos alquimistas con la misma habilidad pueden fabricar cosas completamente distintas, porque han puesto su conocimiento en otro sitio. Por eso tampoco puedes tenerlo todo. Tienes que elegir.\n\n|cffffcc00De dónde salen los puntos — cinco fuentes, y la primera deja pequeñas a las demás.|r\n\n1. Pedidos del propio juego (los de la pestaña Cliente), en tu banco de trabajo. Tienen su propio capítulo más adelante, incluida la trampa de hacerlos todos al principio de la semana.\n2. Fabricar todo una vez. La primera fabricación de cada receta da un punto de conocimiento. Haz esto antes de empezar a gastar, así tendrás más con lo que trabajar.\n3. Tesoros por el mundo. Repartidos por las zonas de Midnight hay contenedores que dan puntos — un buen botín si aún no los has recogido.\n4. Una misión semanal con tu instructor, y un tratado que un escriba puede hacerte.\n5. Libros de reputación. Unas cuantas facciones te venden un libro que da diez de golpe.\n\nCocina, Pesca y Arqueología no tienen árboles y no necesitan puntos en absoluto.\n\nNo te preocupes por ir \"por detrás\": las semanas perdidas vuelven poco a poco mediante un sistema de recuperación, y este curso te lleva de la mano paso a paso.",
	PROFACAD_CH_TREES_ADVANCED = "¿Dónde se hace clic exactamente? Abre tu ventana de profesión (la de tus recetas) y mira las pestañas de abajo: Recetas, Especializaciones, Pedidos de fabricación. Especializaciones es la buena — ahí viven tus árboles y ahí se gasta el conocimiento. No pasa nada hasta que confirmas, así que puedes abrirla y echar un vistazo sin miedo. ¿No sabes qué árbol? Vuelve aquí: el resumen de Profesiones te nombra el siguiente nodo siempre que pueda leer tus árboles.",
	PROFACAD_CH_TREES_BODY = "Ahí hay tres o cuatro |cffffffffruedas|r una al lado de la otra. Cada una está hecha de casillas redondas unidas por líneas, y la reconoces por el anillo que la rodea y que se va llenando según metes puntos — pasa el cursor por encima y verás algo como \"3 / 30\", es decir tres puntos puestos y treinta para llenarla. Las guías llaman nodos a esas casillas. Cada rueda tiene una casilla grande en el centro (la raíz) y otras más pequeñas alrededor que solo aparecen cuando la del centro tiene suficiente dentro. Mirar no cuesta nada: no cambia nada hasta que confirmas.\n\n|cffffcc00La única regla que importa: no repartas tus puntos.|r\n\nMeter un poco en todo parece muy listo. Es el error más caro que existe, y lo comete todo el mundo. La razón es que todo lo que merece la pena está detrás de un |cffffffffumbral|r. A los treinta puntos pasa algo; a los quince no pasa nada. Cuatro casillas a medio llenar te dan por tanto |cffffffffnada|r — has gastado cien puntos y sigues sin poder hacer nada especial.\n\nElige una. Termínala. Y luego pasa a la siguiente. Lo alto que es un umbral cambia según la profesión e incluso según la casilla, así que no te fíes del número de una guía: pasa el cursor por la casilla y te lo dice.\n\n|cffffcc00Lo que ganas al abrir una rama|r no es lo que espera la mayoría, y es una buena noticia. La receta suele venir de |cffffffffabrir|r una rama, no de llenarla — la abres y ya puedes fabricar la cosa enseguida. Los puntos que metas después no la hacen posible, la hacen |cffffffffmejor|r. Abrir tampoco te cuesta ningún punto de conocimiento; para eso recibes desbloqueos aparte al llegar a ciertas cantidades de puntos en la casilla central. Pero no recibes ilimitados. Para abrir una segunda rama tienes que profundizar antes en el centro. Abrir es gratis, pero está racionado.\n\n|cffffcc00Y algunas cosas están sencillamente apagadas,|r que es la trampa en la que la gente concluye que el juego está roto. Unas cuantas ramas encienden algo que antes no existía. Un ingeniero puede reciclar equipo viejo, pero solo |cffffffffdescubre recetas|r con ello después de meter puntos — sin eso reciclas eternamente y no pasa nada. Un sastre solo ve caer la tela cara una vez aprendida la rama correspondiente. Un herborista solo puede recolectar desde la montura tras profundizar lo suficiente. Si algo \"parece que no funciona\", mira si todavía hay que encenderlo.\n\n|cffffcc00Tienes una segunda oportunidad.|r Desde el parche 12.1 puedes deshacer tus puntos |cffffffffuna vez por profesión|r, con Theremis en la Ciudad de Lunargenta, junto a la mesa de pedidos. Una vez — después tus decisiones quedan fijadas. También te hace olvidar las recetas que esos puntos habían desbloqueado; vuelven cuando colocas los puntos otra vez, pero que no te asuste. Y tampoco hace falta ponerse nervioso: si sigues reuniendo puntos podrás llenar con el tiempo todas las ramas, así que los puntos no se pueden |cffffffffdesperdiciar|r de verdad — solo estar en el sitio equivocado durante los meses en que importa.\n\nEliges árbol con habilidad 25, 50, 60 y 75. El juego no decide cuál; lo decides tú. Cuando ya tengas profesiones, sus propios capítulos de más abajo te dan una build inicial concreta, y el resumen de Profesiones muestra consejos en vivo para tus propios árboles.",
	PROFACAD_CH_QUALITY_TITLE = "Calidad — por qué su espada es mejor que la tuya",
	PROFACAD_CH_QUALITY_INTRO = "Dos jugadores usan la misma receta y un resultado sale mejor. No es mala suerte ni un fallo del juego: las cosas fabricadas tienen un rango de calidad.",
	PROFACAD_CH_QUALITY_ADVANCED = "¿Dónde se hace clic exactamente? Abre una receta en tu ventana de profesión y mira el recuadro Detalles de fabricación de la derecha: muestra la Dificultad de la receta frente a tu Habilidad, que es todo el cálculo en dos números. Haz clic en cualquier componente de la receta y podrás elegir qué calidad de material entra — el tooltip dice \"Left Click to allocate reagent qualities\". También hay una casilla \"Use Best Quality Reagents\" que escoge automáticamente lo mejor que tengas. Cómodo, pero gasta tus materiales caros sin preguntar dos veces.",
	PROFACAD_CH_QUALITY_BODY = "La imagen que ayuda: la receta dice |cffffffffqué|r estás fabricando, la calidad dice cómo ha salido. Dos panaderos con la misma receta no hornean el mismo pan.\n\nEsto se lee en una pequeña |cffffffffforma|r, no en un número. El tooltip pone \"Calidad:\" con la forma al lado — un rombo gris es bajo, un pentágono dorado es alto. En tu ventana de profesión aparece lo mismo como una barra, la forma más baja a la izquierda y la más alta a la derecha, con una marca blanca que indica más o menos dónde va a caer tu fabricación.\n\nImporta por tres razones, y la tercera pilla a todo el mundo alguna vez. Mejor equipo y pociones más fuertes, evidentemente. Más oro: la misma receta, el Pellejo tejido de escamas, se vendía por 10g94 en el rango más bajo y por 21g12 en el más alto — casi el doble, con los mismos materiales y el mismo clic. Cada rango es de verdad un |cffffffffobjeto distinto|r con su propia entrada en la subasta, así que no se apilan juntos. Y la tercera: si alguien pide una calidad mínima que tú no alcanzas, |cffffffffno puedes completar ese pedido en absoluto|r. No es que \"salga peor\" — es que literalmente no lo puedes entregar.\n\nLo que lo decide es un solo número: tu |cffffffffhabilidad|r en el momento de pulsar fabricar. Cada receta tiene una dificultad. Si estás holgadamente por encima sacas el rango más alto; si estás por debajo, no.\n\nEse número se compone de cuatro cosas. Tu habilidad base, que sube según fabricas y acaba llenándose. Tus puntos de conocimiento, que dan habilidad |cffffffffsolo a ese tipo de receta|r — puntos en anillos hacen mejores tus anillos, no tus collares. Tu equipo de profesión: una herramienta y dos accesorios por profesión, en sus propias ranuras, que muchísima gente deja sencillamente vacías. Y tus componentes, que llevan las mismas formas de calidad, así que los materiales baratos no siempre salen más baratos.\n\nSi te quedas a un paso hay una red de seguridad, que se llama Concentración. Tiene su propio capítulo más abajo.\n\nHay una trampa que merece ser nombrada, porque cuesta oro de verdad: |cffffffffestar especializado a medias es más caro que no especializarse|r. Reparte tus puntos entre cuatro ramas y te quedarás corto en todas. Podrás fabricar cualquier cosa en un rango mediocre, y lo mediocre no se vende y los pedidos lo rechazan.\n\nSi recolectas en vez de fabricar, tus hierbas y tu mineral también llevan rangos — pero en Midnight solo |cffffffffdos|r, no la escalera completa. Más habilidad significa el mejor de los dos más a menudo. No hay un tercer rango que perseguir.",
	PROFACAD_CH_QUALITY_TASK = "Abre una receta y localiza la barra de Calidad y el recuadro Detalles de fabricación.",
	PROFACAD_CH_STATS_TITLE = "Los seis números que nadie explica",
	PROFACAD_CH_STATS_INTRO = "Multifabricación, Ingenio, Destreza. El juego no dice en ningún sitio qué hacen, y la mayoría de los jugadores lo busca otra vez cada vez.",
	PROFACAD_CH_STATS_ADVANCED = "¿Dónde se ven exactamente? Abre cualquier receta en tu ventana de profesión y mira el recuadro Detalles de fabricación de la derecha — las seis aparecen ahí como porcentajes, por ejemplo Ingenio 4%, Multifabricación 4%, Inventiva 19%. Ese mismo recuadro muestra la Dificultad de la receta frente a tu Habilidad y, debajo, lo que te costaría en Concentración forzar el siguiente rango de calidad.",
	PROFACAD_CH_STATS_BODY = "La imagen que ayuda: |cffffffffla habilidad decide cómo de bien sale; estas seis deciden lo barato que te ha salido llegar ahí.|r La habilidad va del resultado; estas van del camino hasta él.\n\nHay tres para fabricar y tres para recolectar, así que nunca necesitas las seis a la vez.\n\nFabricar. |cffffffffEl Ingenio|r significa que una fabricación consume a veces menos de lo que debería y tú te quedas los materiales. Funciona con todo, y es el único que mejora tu beneficio en el pedido de otra persona, porque las sobras se quedan contigo y no con el cliente. |cffffffffLa Multifabricación|r significa que a veces sacas más de uno con los mismos materiales. |cffffffffLa Inventiva|r te devuelve parte de tu Concentración.\n\nLa trampa de esa lista: |cffffffffla Multifabricación no hace nada con el equipo.|r Una copia de más solo significa algo en cosas que se apilan — pociones, gemas, materiales. Un anillo o un peto nunca se duplican, así que si fabricas sobre todo equipo, la Multifabricación está desperdiciada. Y en los pedidos de otros las copias de más van al |cffffffffcliente|r, no a ti. Esto último es lo que se cuentan los jugadores entre sí; Blizzard nunca lo ha confirmado.\n\nRecolectar. |cffffffffLa Sutileza|r te da más por nodo, que es tu volumen y por tanto tu oro. |cffffffffLa Percepción|r te da más posibilidades de sacar el material raro en vez de más del corriente. |cffffffffLa Destreza|r acorta la animación de recolección.\n\nCuál importa depende de lo que hagas, y esa es la parte útil. La Herboristería quiere Sutileza: por hora pasas mucho más tiempo buscando y volando que recolectando, así que recolectar más rápido resuelve el problema equivocado. Con la Minería pasa lo mismo, y ahí la Percepción es floja, porque el mineral raro al que te dirige tiene poco uso en las recetas. |cffffffffEl Desuello le da la vuelta|r — en cuanto cazas las bestias raras, la Percepción es fuerte, porque ahí es donde está el botín caro. Es la única profesión de recolección donde eso se cumple. Esos tres son juicios sobre cómo se juegan las profesiones, no números que nadie haya publicado.\n\nLos valores vienen de dos sitios que tú controlas: tus puntos de conocimiento, ya que muchos nodos conceden una de estas seis, y tu equipo de profesión. Así que cuando gastes un punto, mira qué stat hay debajo del nodo y si encaja con lo que de verdad piensas fabricar.\n\nSi te quedas con una sola cosa: |cffffffffdecide qué vas a fabricar y luego elige tu stat.|r Quien vende pociones y quien fabrica anillos tienen intereses opuestos, y una guía que dice \"la Multifabricación es lo mejor\" no te cuenta a quién se lo está diciendo.",
	PROFACAD_CH_STATS_TASK = "Abre Detalles de fabricación en una receta y lee tus propios tres porcentajes.",
	PROFACAD_CH_CONC_TITLE = "Concentración, el freno de emergencia",
	PROFACAD_CH_CONC_INTRO = "A veces te quedas a un rango, y fabricar la cosa igualmente parece un desperdicio. Para eso existe exactamente la Concentración.",
	PROFACAD_CH_CONC_ADVANCED = "¿Dónde se encuentra exactamente? En tu ventana de profesión es una barra de arriba con tu total actual, y cuando abres una receta hay un botón con una llama junto al botón de fabricar que muestra lo que costaría esa fabricación concreta. El coste cambia según la receta, así que léelo antes de pulsar.",
	PROFACAD_CH_CONC_BODY = "La imagen: |cffffffffes una batería que se carga sola.|r Tú no haces nada por ello, se rellena por su cuenta, y puedes vaciarla en el momento en que importa. Gástala en una fabricación y el siguiente rango de calidad está |cffffffffgarantizado|r — no es una probabilidad, no es una tirada. El propio juego lo dice: \"Apply 358 concentration to guarantee the next quality for this recipe.\"\n\nAquí está la historia completa, y es la razón de que la gente la use mal. La batería aguanta |cffffffff1000|r y se rellena a unos |cffffffff250 al día|r, así que de vacía a llena hay unos cuatro días. Eso es lento. Cada vez que la usas estás gastando parte de tus próximos días, y cuando está vacía solo puedes esperar.\n\nCada profesión tiene su |cffffffffpropia|r batería. Un alquimista que además recoge hierbas tiene dos, y no tienen nada que ver entre sí.\n\nTampoco sale barata por uso. Una fabricación real costó 358 de los 1000 — más de un tercio de la batería por un solo objeto.\n\nMerece la pena gastarla en: algo que se queda a un rango y que vas a llevar o usar tú; un pedido con una calidad mínima que de otro modo no alcanzas, ya que sin ella no puedes completar ese pedido en absoluto; y cualquier cosa cara, donde la diferencia entre rangos vale más que un día de batería.\n\nNo merece la pena gastarla en: algo que ya fabricas al rango más alto de todas formas, donde no compras nada y pierdes la batería. Ese es el error más habitual, porque la gente deja el botón activado y no se da cuenta. Y en el volumen barato — cincuenta pociones un rango más arriba está bien, pero no vale cuatro días.\n\nAlgo se recupera. |cffffffffLa Inventiva|r, una de las seis stats, devuelve de vez en cuando parte de lo que acabas de gastar, y el juego te avisa cuando ocurre. Justo por eso la Inventiva solo se vuelve interesante cuando ya vas a por calidad: si no gastas nada, no hay nada que devolver.\n\nUna cosa más, y va de personas más que de mecánicas. Si quemas Concentración para alcanzar la calidad en el pedido de |cffffffffotra persona|r, esa persona se lleva el objeto mejor y tú pagas de una batería que tarda días en recuperarse. Los fabricantes con experiencia cobran más por eso. No es una regla y no hay tarifa fija, pero conviene saber que pedirlo no es codicia y que te lo pidan no es raro.\n\nLa Concentración no es un sistema que haya que gestionar ni optimizar. Es un freno, y está ahí para el momento en que te quedas a un rango de algo que lo merece. Si se llena mientras juegas, vas bien. Si lleva semanas al máximo, probablemente estás dejando calidad sobre la mesa.",
	PROFACAD_CH_CONC_TASK = "Busca tu barra de Concentración y mira si lleva tiempo parada al máximo.",
	PROFACAD_CH_GOLD_TITLE = "Hacer oro sin engañarte",
	PROFACAD_CH_GOLD_INTRO = "Aquí solo hay una cuenta, y casi nadie la hace: lo que te pagan, menos todo lo que ha entrado, menos un 5% para la casa de subastas.",
	PROFACAD_CH_GOLD_BODY = "La palabra que la gente se salta es |cfffffffftodo|r. Las hierbas que has recogido tú |cffffffffno son gratis|r. Tienen un precio de mercado, y meterlas en una poción en vez de venderlas significa que lo has gastado — solo que te lo has pagado a ti mismo. Si la hierba vale más que la poción, fabricar es |cffffffffperder dinero de una forma que se siente como ganarlo|r.\n\n|cffffcc00Hay dos mercados, y obedecen a leyes opuestas.|r Casi toda la confusión sobre si una profesión \"renta\" viene de mezclarlos.\n\nEl primero es el de |cffffffffmercancías|r: materiales, pociones, frascos, gemas — todo lo que se apila. Vendes cosas, y compites con toda la región en vez de con tu propio reino. Los compradores no ven más que el precio.\n\nEl segundo es el del |cffffffffequipo fabricado|r. Se queda en tu reino, y lo mejor se vincula a una sola persona, así que ni siquiera puede ir a la casa de subastas. Aquí no vendes cosas, vendes tu artesanía.\n\n|cffffcc00Por qué el mercado de mercancías siempre se hunde|r merece entenderse, y ninguna de las razones es \"hay muchos jugadores\". El juego compra automáticamente la oferta más barata, así que una moneda de cobre por encima del precio más bajo significa no vender. Compites contra todos los reinos de tu región a la vez. La Multifabricación reparte oferta extra gratis, y solo funciona con cosas que se apilan — precisamente este mercado. Y los consumibles tienen solo dos rangos de calidad en lugar de la escalera completa, así que la caída hasta el fondo es más corta.\n\nHay un freno: mientras los fabricantes sigan necesitando Concentración para alcanzar la calidad máxima, la calidad máxima es escasa. En cuanto la alcancen sin ayuda, el freno se suelta y el precio cae. Así que en este mercado ganas en la ventana |cffffffffanterior|r a que eso ocurra.\n\n|cffffcc00Lo que de verdad protege un precio es un candado sobre la oferta.|r Hay cuatro tipos: un cooldown en la receta, un componente que el fabricante nunca puede conseguirse él mismo, una receta detrás de reputación, y la Concentración, porque se rellena despacio. |cffffffffDonde hay candado hay margen. Donde no lo hay, hay volumen y casi ningún margen.|r Ese es todo el tema en una frase.\n\nRecolectar es la excepción que lo demuestra: lo que recoges no tiene coste, así que |cffffffffno puedes|r perder — la única forma de hacer oro en la que un principiante no puede equivocarse. Pero no tener coste significa tampoco tener barrera, así que el precio se asienta en lo que acepte el recolector menos exigente.\n\n|cffffcc00Cada objeto fabricado cae en una de tres cajas, y la tercera es la trampa.|r Lo libremente comerciable lo dice en su propio tooltip: \"Se puede comprar y vender en la casa de subastas.\" Lo que sale \"Ligado\" no se puede subastar pero |cffffffffsí|r se puede vender mediante un pedido, que lo entrega directamente al cliente — ahí vendes trabajo, no producto. Y lo que |cffffffffse liga a la banda de guerra|r no permite ninguna de las dos cosas: ni subasta, ni pedido, solo tú y tus propios alts. Eso no es un negocio, es un servicio.\n\nAlquimistas sobre todo: los dos calderos que abastecen a toda tu Raid llevan |cffffffffambos|r \"Se liga a la banda de guerra\". Nunca los vas a poder vender. Los fabricas, los llevas, y lo que recibes a cambio es buena voluntad. Eso está bien — pero debería ser una decisión y no un descubrimiento, porque entran materiales caros.\n\n|cffffcc00¿En volumen o por pedido?|r En volumen vendes el producto, compites en precio con toda la región, tienes volumen ilimitado y un margen que no deja de adelgazar. Por pedido vendes tu artesanía, compites en reputación con los fabricantes de tu propio reino, tienes volumen limitado y un margen más estable. De ahí se sigue una aritmética, no una opinión: |cffffffffla cola de pedidos públicos no es un negocio.|r Guardas cuatro y recuperas uno al día — unos siete a la semana. Eso es calderilla. |cffffffffLos pedidos personales y los de hermandad son ilimitados|r, así que un puñado de clientes fijos que te manden pedidos directamente es donde está el trabajo de verdad.\n\n|cffffcc00El mayor error de principiante|r es fabricar antes de mirar lo que cuestan los materiales. Tiene dos caras y son el mismo error: \"lo he recogido yo, así que es gratis\" y \"tengo esta receta, así que la voy a fabricar\". Tener una receta no dice nada sobre si renta. |cffffffffMira primero lo que cuesta. Y luego decide si lo fabricas.|r\n\nY desconfía de todo \"X de oro por hora\" de una guía o un vídeo: cambia según el reino y suele estar inventado. Mídelo tú en tu propio reino. Auctionator muestra lo que cuestan las cosas de verdad; CraftSim calcula lo que rinde una fabricación frente a los precios de materiales de hoy, y es con diferencia lo más útil que puedes instalar si quieres ganar en serio.",
	PROFACAD_CH_GOLD_DATED_202608 = "|cffffcc00Cómo está la cosa a finales de agosto de 2026 — y esta mitad caduca.|r La temporada 2 tiene pocos días, así que trata los párrafos de abajo como una foto fija y no como una regla. Conviene saberlo: casi todas las guías de \"temporada 2\" que hay están fechadas antes incluso de que empezara la temporada, lo que convierte sus afirmaciones en predicciones y no en observaciones. No existe ninguna serie de precios publicada de estas primeras semanas, de nadie.\n\n|cffffffffAlquimia.|r Las pociones y los frascos son libremente comerciables y se venden bien mientras la Raid es nueva y la demanda está en su pico — pero esto es el mercado de mercancías a pleno rendimiento, así que cuenta con que el margen se hunda a medida que más fabricantes alcancen la calidad máxima sin Concentración. El Principio sinergético maravilloso es el ingreso más estable: lleva un cooldown de aproximadamente un día, así que nadie puede inundar el mercado, que es exactamente el candado descrito arriba, y alimenta tanto a los calderos como a la piedra épica. La decoración de vivienda es la infravalorada — seis recetas, comerciables, y no se apila, así que compite en tu propio reino en vez de en la bolsa regional. Una historia de mercado que conviene llevarse: la nueva poción de salud de 12.1 consume 25 de la antigua, así que la poción vieja pasó de producto acabado a ingrediente y perdió aproximadamente la mitad de su valor como producto. Quien la acumuló en julio se encontró con esa caída a la mitad el 11 de agosto.\n\n|cffffffffHerboristería.|r El Loto nocturno es la hierba cara, y la razón es precisa: es la única hierba de Midnight de calidad rara, no tiene nodo propio (aparece como captura accidental de cualquier otra hierba) y sale en los cuatro frascos y en los dos calderos — once recetas en total. Los dos materiales nuevos de la Isla Serpenteante son ambos comerciables, con una advertencia: |cffffffffno|r son exclusivos de los herboristas. Los mineros los sacan de sus propios nodos, y uno de ellos también cae de animales mediante Desuello. Varias guías dan a entender lo contrario.",
	PROFACAD_CH_GOLD_TASK = "Antes de tu próxima fabricación, busca lo que cuestan sus materiales — y solo entonces decide si la haces.",
	PROFACAD_CH_WORKORDERS_TITLE = "Pedidos de fabricación: comprar la artesanía de otro",
	PROFACAD_CH_WORKORDERS_INTRO = "La casa de subastas te vende cosas que ya existen. En la mesa de pedidos funciona al revés: tú traes los materiales y le pagas a alguien por el trabajo.",
	PROFACAD_CH_WORKORDERS_ADVANCED = "Dos cosas que hacen que el sistema parezca roto cuando no lo está. En tu propio banco de trabajo, la lista de pedidos públicos se queda vacía hasta que pulsas |cffffffffBuscar|r — no pasa nada malo, simplemente no se carga sola. Y el hombre que está junto a la mesa de pedidos, el Capitán Jurabengala, no tiene nada que ver con esto: él reparte la misión de introducción de tu profesión, tus misiones semanales y bolsas gratis de materiales. Útil, pero no es a lo que vienes.",
	PROFACAD_CH_WORKORDERS_BODY = "Funciona así porque el mejor equipo fabricado se vincula a una sola persona en el momento en que existe. Nadie puede hacerlo por adelantado y ponerlo en el estante, así que alguien tiene que fabricarlo |cffffffffespecialmente para ti|r.\n\n|cffffcc00Hay dos mostradores, y aquí es donde suele torcerse.|r Para que te fabriquen algo, ve a la mesa de pedidos del Bazar de Lunargenta — el gran martillo dorado de tu minimapa. La persona que necesitas es Mar'nah. Para fabricar algo para otra persona, ve en cambio al |cffffffffbanco de trabajo de tu propia profesión|r. Si no estás justo al lado no hay botón ni lista, y parece que el sistema no existiera. Ese es el error más habitual, y el juego no lo explica en ninguna parte.\n\n|cffffcc00Que te fabriquen algo.|r Elige tu objeto y elige después a quién se lo pides. A nadie en particular (un pedido de fabricación público): todo tu reino lo ve y lo fabrica el primero que lo coja. Rápido, pero te llevas lo que salga — |cffffffffaquí no puedes exigir una calidad|r, y tienes que enviar tú todos los materiales. A un jugador concreto (un pedido de fabricación personal): aquí sí puedes fijar una calidad mínima, y podéis acordar que ponga materiales suyos. A toda tu hermandad (un pedido de fabricación de hermandad) funciona igual y llega a compañeros de hermandad de otros reinos. Tú fijas el pago, y un botón al lado muestra lo que han pagado otros hace poco por el mismo objeto.\n\nTres cosas que saber antes de pulsar el botón de pedir. Algunos componentes especiales no los puede aportar nunca el fabricante, así que esos los envías siempre tú. Los materiales de tu banco de la banda de guerra |cffffffffno cuentan|r — ponlos en tus bolsas. Y el objeto se vincula a |cffffffffti|r, así que haz el pedido con el personaje que lo va a llevar, no con el que guarda el oro. Una vez que alguien coge el pedido ya no lo puedes cancelar; el objeto llega por correo.\n\n|cffffcc00Fabricar para otros.|r En tu banco de trabajo ves lo que vas a ganar antes de empezar. En cuanto empiezas tienes |cffffffff30 minutos|r para terminar — suficiente para ir a por algo, no para irte a comer.\n\nNo puedes coger pedidos públicos sin parar: guardas |cffffffffcuatro|r, y |cffffffffvuelve uno cada día|r. Así que unos siete a la semana, no cuatro al día. Los pedidos casi caducados se pueden coger gratis.\n\nSi un pedido te rechaza es por una de cuatro cosas: no conoces la receta, tu especialización no llega para los extras que pide, quiere una calidad que no alcanzas, o has agotado tu cupo.\n\nY uno que te cuesta dinero en silencio: |cffffffffmira de quién son los materiales que estás usando.|r En los pedidos públicos el cliente aporta siempre todo, pero en los otros tipos puede no aportar nada — y entonces estás fabricando alegremente con tus propias existencias caras a cambio de una propina.",
	PROFACAD_CH_WORKORDERS_TASK = "Encuentra la mesa de pedidos en el Bazar de Lunargenta y encuentra después el banco de trabajo de tu propia profesión. No son el mismo sitio.",
	PROFACAD_CH_PATRON_TITLE = "La pestaña Cliente, tu motor semanal de conocimiento",
	PROFACAD_CH_PATRON_INTRO = "El cuarto tipo de pedido viene del propio juego y no de un jugador, y es el que la mayoría de la gente no encuentra nunca.",
	PROFACAD_CH_PATRON_BODY = "En tu propio banco de trabajo hay una pestaña |cffffffffCliente|r donde el juego te da pedidos. Ningún otro jugador, ninguna competencia — son solo tuyos. Lo que te pagan no es tanto oro como |cffffffffpuntos de conocimiento|r: los mismos puntos que hacen más fuerte tu profesión.\n\nEs con diferencia tu mayor fuente semanal de ellos. Sáltatelo y te quedarás atrás sin entender nunca por qué los demás avanzan más rápido.\n\nCada pocos días llega una tanda nueva. Cada pedido pide una calidad determinada, y a veces tienes que aportar tú los materiales — compruébalo, porque un pedido caro por dos puntos no siempre compensa. Saltarse alguno está permitido.\n\n|cffffcc00Y ahora la trampa.|r El juego también te da un pedido pequeño de un punto cada día, pero |cffffffffsolo mientras vas por detrás de tu objetivo semanal|r. Haz todos los pedidos grandes el lunes y estarás al día — así que los pequeños diarios se paran el resto de la semana.\n\nAsí que: |cffffffffdeja los pedidos grandes hasta que estén a punto de caducar|r. Mientras tanto sigues recogiendo los pequeños, y terminas la semana con más puntos de los que habrías tenido. Parece que está mal. Aun así es verdad.",
	PROFACAD_CH_PATRON_TASK = "Abre la pestaña Cliente en tu propio banco de trabajo y mira lo que ofrece esta semana.",
	PROFACAD_CH_ALCHEMY_BODY = "La Alquimia te ofrece un árbol con habilidad 25, 50, 60 y 75 — el juego no elige, eliges tú. Los cuatro son Destreza en pociones (pociones, con un lado de Luz y un lado de Vacío), Versado en frascos, Autoridad en transmutaciones y Maestría alquímica.\n\n|cffffcc00Build inicial, en este orden.|r Primero |cffffffffDestreza en pociones|r: llenarla da el Caldero de pociones de luz del Vacío, que sirve a la vez a tu oro y a tu hermandad. Después |cffffffffCamino de la Luz|r y |cffffffffAlquimista prolífico - Luz|r, que es el nodo de Multifabricación — la Luz porque es la poción que se vende esta temporada. Luego |cffffffffMaestría alquímica|r y, dentro, |cffffffffReuse|r, que te devuelve hierbas y es fuerte si además las recoges tú.\n\nDespués, unos 15 puntos en |cffffffffVersado en frascos|r, que duplica lo que duran tus propios frascos, y a continuación |cffffffffEspecialista sin'dorei|r. |cffffffffAutoridad en transmutaciones|r va la última, no la segunda.\n\n|cffffffffLos Secretos de los haranir no son un añadido de última hora.|r Su propio tooltip dice \"al fabricar ampollas y el caldero de frascos sin'dorei\" — sin puntos ahí no puedes fabricar el Caldero de frascos sin'dorei al rango más alto. Las guías parafrasean ese nodo como \"phials only\" y se dejan por el camino la media frase que importa.",
	PROFACAD_CH_HERBALISM_BODY = "Cada hierba aparece en todas las zonas, así que no hay que agonizar eligiendo zona. El orden de abajo es lo que recomienda ahora la ruta de este addon, y cada paso es una cosa que desbloqueas en vez de un reparto vago.\n\n|cffffcc00Primero: unos 40 puntos en Botánica.|r Eso es recolectar montado, y es con diferencia el mayor ahorro de tiempo de la profesión — sin ello te bajas y te vuelves a subir en cada planta. Los druidas se lo saltan: ya recolectan montados.\n\n|cffffcc00Después unos 20 en Preparación de mantillo|r, que la gente deja fuera y no debería. Te da Mantillo imbuido: un hallazgo raro garantizado en tu siguiente recolección, y ese hallazgo raro es el Loto nocturno — la única hierba de Midnight de calidad rara, sin nodo propio, presente en los cuatro frascos y en los dos calderos.\n\n|cffffcc00Luego Cosechas generosas|r para el largo plazo: más hierbas por nodo y más habilidad, así que calidad máxima más a menudo. Dentro, cada hierba tiene su propio nodo, así que puedes apuntar a la que mejor se venda en tu reino.\n\n|cffffcc00Deja la Sobrecarga de Midnight en paz.|r Solo funciona en los nodos elementales, cuesta muchos puntos, y te encuentras demasiado pocos. Solo merece la pena si estás farmeando motas a propósito.\n\nEsos recuentos de puntos vienen de una sola fuente cada uno. Pasa el cursor por el nodo en el juego antes de hacer clic — el tooltip tiene el número real, y solo tienes un reinicio.",
	PROFNEXT_UNSPENT_LOCKED_FMT = "%s: %d puntos de conocimiento en el banco, y todavía no hay dónde meterlos - ninguna especialización se puede desbloquear, así que sube primero la habilidad (la primera elección llega a 25)",
	SMC_PIN_NEAREST_FP = "Apunta la flecha al maestro de vuelo más cercano desde donde estés, no solo en esta ciudad. También disponible con /mh fp.",
	FP_NEAREST_SET_FMT = "Flecha puesta en el maestro de vuelo más cercano: %s.",
	FP_NEAREST_NO_MAP = "Ahora mismo no puedo saber dónde estás, así que no puedo elegir un maestro de vuelo.",
	FP_NEAREST_NONE = "Todavía no hay puntos de vuelo registrados para esta zona.",
	FP_NEAREST_NONE_FACTION = "Esta zona tiene puntos de vuelo, pero ninguno que tu facción pueda usar.",
	FP_NEAREST_NO_WAYPOINT = "No se ha podido poner un punto de ruta ahí.",
	SMC_PIN_FLIGHTMASTER = "Lunargenta tiene dos maestros de vuelo, así que la pregunta útil es cuál está más cerca. Los dos hacen las mismas rutas.",
})

fill("ptBR", {
	CMDLIST_FP = "Seta para o mestre de voo mais próximo, esteja você onde estiver",
	CMDLIST_COURSE = "Professions 101 em uma janela própria, ao lado do jogo",
	TOOLLP_COURSE_NAME = "Curso Professions 101",
	TOOLLP_COURSE_DESC = "O curso para iniciantes em uma janela própria, para que a lista de capítulos ganhe toda a altura e o texto fique ao lado do jogo enquanto você faz a tarefa.",
	PROFACAD_BTN_FULL_COURSE = "Curso inteiro",
	PROFACAD_ADVISE_NEXT_POINTS_FMT = "Conselho: seus próximos pontos em %s (raiz %d/%d) — mire em cerca de %d. Passe o mouse sobre o nó no jogo; a tooltip dele traz o número exato, e os guias discordam sobre isso.",
	PROFACAD_ADVISE_NEXT_OPEN_FMT = "Conselho: abra %s — e então pare. Desbloquear é o que compensa; pontos além disso são uma aposta nos preços dos materiais.",
	PROFACAD_ADVISE_GOALS_FMT = "Daqui a rota se divide, e as duas realmente diferem. %s",
	PROFACAD_ADVISE_GOAL_LINE_FMT = "%s %s (raiz %d/%d).",
	PROFACAD_GOAL_GOLD = "Vender para outros:",
	PROFACAD_GOAL_SELF = "Equipar você e sua guilda:",
	PROFACAD_CHOICES_HEADER = "Nós soltos dentro das suas árvores que ainda não estão cheios:",
	PROFACAD_CHOICES_HEADER_MORE_FMT = "Nós soltos dentro das suas árvores que ainda não estão cheios (%d de %d):",
	PROFACAD_CH_KNOWLEDGE_BODY = "Sua profissão cresce de duas maneiras, e é exatamente aí que mora a confusão.\n\nSua |cffffffffPerícia|r sobe fabricando coisas. Isso acontece sozinho. Ao lado dela você junta |cffffffffpontos de Conhecimento|r, que você não ganha fabricando, e sim de encomendas, tesouros e livros — e esses pontos você gasta em uma árvore, onde escolhe no que vai ficar bom.\n\nA imagem que ajuda: |cffffffffperícia é quantas vezes você já fez aquilo, conhecimento é aquilo em que você se aprofundou.|r Dois alquimistas com a mesma perícia podem fabricar coisas completamente diferentes, porque colocaram o conhecimento em lugares diferentes. É por isso também que você não pode ter tudo. Você precisa escolher.\n\n|cffffcc00De onde vêm os pontos — cinco fontes, e a primeira é muito maior que as outras.|r\n\n1. Encomendas do próprio jogo (a aba Cliente), na bancada da sua profissão. Elas ganham um capítulo próprio mais abaixo, incluindo a armadilha de fazer todas no começo da semana.\n2. Fabricar tudo uma vez. A primeira fabricação de cada receita vale um ponto. Faça isso antes de começar a gastar, assim você tem mais com que trabalhar.\n3. Tesouros pelo mundo. Espalhados pelas zonas de Midnight há contêineres que dão pontos — uma boa colheita se você ainda não os pegou.\n4. Uma missão semanal no seu treinador, e um tratado que um escrivão pode fabricar para você.\n5. Livros de reputação. Algumas facções vendem um livro que dá dez de uma vez.\n\nCulinária, Pesca e Arqueologia não têm árvores e não precisam de ponto nenhum.\n\nNão se preocupe em estar \"atrasado\": semanas perdidas voltam devagar por um sistema de recuperação, e este curso caminha com você um passo de cada vez.",
	PROFACAD_CH_TREES_ADVANCED = "Onde você clica de verdade? Abra sua janela de profissão (aquela com as suas receitas) e olhe as abas na parte de baixo: Receitas, Especializações, Pedidos de Criação. Especializações é a que interessa — é ali que ficam as suas árvores e é ali que o Conhecimento é gasto. Nada acontece até você confirmar, então é seguro abrir e só dar uma olhada primeiro. Não tem certeza de qual árvore? Volte aqui: o resumo Profissões diz qual é o próximo nó sempre que consegue ler as suas árvores.",
	PROFACAD_CH_TREES_BODY = "Ali ficam três ou quatro |cffffffffrodas|r lado a lado. Cada uma é feita de espaços redondos ligados por linhas, e você reconhece uma pelo anel em volta que vai enchendo conforme você coloca pontos — passe o mouse por cima e vai ver algo como \"3 / 30\", ou seja, três pontos dentro e trinta é o cheio. Os guias chamam esses espaços de nós. Cada roda tem um espaço grande no meio (a raiz) e outros menores em volta, que só aparecem quando o do meio já tem o bastante. Olhar não custa nada: nada muda até você confirmar.\n\n|cffffcc00A única regra que importa: não espalhe os seus pontos.|r\n\nColocar um pouquinho em tudo parece esperto. É o erro mais caro que existe, e todo mundo comete. O motivo é que tudo que vale a pena está atrás de um |cffffffffpatamar|r. Aos trinta pontos alguma coisa acontece; aos quinze, nada. Portanto, quatro espaços pela metade não dão |cffffffffnada|r a você — você gastou cem pontos e continua sem conseguir fazer nada de especial.\n\nEscolha um. Termine. Só então siga em frente. O tamanho do patamar varia por profissão e até por espaço, então não vá por um número tirado de um guia: passe o mouse sobre o espaço e ele te diz.\n\n|cffffcc00O que você ganha ao abrir um ramo|r não é o que a maioria espera, e é uma boa notícia. A receita costuma vir de |cffffffffabrir|r um ramo, e não de enchê-lo — você abre e já pode fabricar a coisa. Os pontos que você coloca depois não tornam aquilo possível, eles tornam aquilo |cffffffffmelhor|r. Abrir também não custa ponto de Conhecimento nenhum; para isso você ganha desbloqueios separados, em marcos fixos do espaço do meio. Mas eles não são infinitos. Para abrir um segundo ramo você precisa antes ir mais fundo no meio. Abrir é de graça, mas é racionado.\n\n|cffffcc00E algumas coisas simplesmente estão desligadas,|r e é aí que está a armadilha em que as pessoas concluem que o jogo está quebrado. Alguns ramos ligam algo que antes não existia. Um engenheiro pode reciclar equipamento velho, mas só |cffffffffdescobre receitas|r com isso depois de colocar pontos — sem isso você recicla para sempre e nada acontece. Um alfaiate só vê o tecido caro cair quando o ramo correspondente foi aprendido. Um herbalista só colhe montado depois de ir fundo o bastante. Se alguma coisa \"parece não funcionar\", veja se ela ainda precisa ser ligada.\n\n|cffffcc00Você tem uma segunda chance.|r Desde o patch 12.1 você pode desfazer os seus pontos |cffffffffuma vez por profissão|r, com Theremis em Luaprata, perto da mesa de encomendas. Uma vez — depois disso as suas escolhas valem. Isso também desaprende as receitas que aqueles pontos tinham desbloqueado; elas voltam quando você recolocar os pontos, mas não se assuste. E não precisa ficar nervoso: continue juntando e com o tempo você consegue encher todos os ramos, então pontos não podem realmente ser |cffffffffdesperdiçados|r — só ficar no lugar errado durante os meses em que isso importa.\n\nVocê recebe uma escolha de árvore com 25, 50, 60 e 75 de Perícia. O jogo não decide qual; você decide. Assim que você tiver profissões, os capítulos delas mais abaixo dão uma build inicial concreta, e o resumo Profissões mostra conselhos ao vivo para as suas próprias árvores.",
	PROFACAD_CH_QUALITY_TITLE = "Qualidade — por que a espada dele é melhor que a sua",
	PROFACAD_CH_QUALITY_INTRO = "Dois jogadores usam a mesma receita e um dos resultados sai melhor. Não é azar e não é bug: coisas fabricadas têm um grau de qualidade.",
	PROFACAD_CH_QUALITY_ADVANCED = "Onde você clica de verdade? Abra uma receita na sua janela de profissão e olhe o quadro Detalhes da criação à direita: ele mostra a Dificuldade da receita contra a sua Perícia, que é a conta inteira em dois números. Clique em qualquer reagente da receita e você pode escolher qual qualidade de material entra — a tooltip diz \"Left Click to allocate reagent qualities\". Também existe uma marcação \"Use Best Quality Reagents\" que pega os seus melhores automaticamente. Prático, mas gasta os seus materiais caros sem perguntar duas vezes.",
	PROFACAD_CH_QUALITY_BODY = "A imagem que ajuda: a receita diz |cffffffffo que|r você está fabricando, a qualidade diz o quão bem aquilo saiu. Dois padeiros com a mesma receita não assam o mesmo pão.\n\nVocê lê isso em um pequeno |cffffffffsímbolo|r, e não em um número. A tooltip diz \"Qualidade:\" com o símbolo ao lado — um losango cinza é baixo, um pentágono dourado é alto. Na sua janela de profissão a mesma coisa aparece como uma barra, o símbolo mais baixo à esquerda e o mais alto à direita, com um marcador branco mostrando mais ou menos onde a sua fabricação vai cair.\n\nIsso importa por três motivos, e o terceiro pega todo mundo uma vez. Equipamento melhor e poções mais fortes, claro. Mais ouro: a mesma receita, Pelego Tecido em Escamas, vendia por 10g94 no grau mais baixo e 21g12 no mais alto — quase o dobro, com os mesmos materiais e o mesmo clique. Cada grau é de verdade um |cffffffffitem separado|r, com anúncio próprio no leilão, então eles não empilham juntos. E o terceiro: se alguém encomenda uma qualidade mínima que você não alcança, você |cffffffffnão consegue concluir aquela encomenda de jeito nenhum|r. Não é \"sai pior\" — você literalmente não consegue entregar.\n\nO que decide isso é um número: a sua |cffffffffPerícia|r no momento em que você aperta fabricar. Toda receita tem uma dificuldade. Confortavelmente acima dela você tira o grau máximo; abaixo dela, não.\n\nEsse número é feito de quatro coisas. A sua perícia básica, que sobe conforme você fabrica e uma hora enche. Os seus pontos de Conhecimento, que dão perícia |cffffffffsó para aquele tipo de receita|r — pontos em anéis deixam os seus anéis melhores, não os seus colares. O seu equipamento de profissão: uma ferramenta e dois acessórios por profissão, em slots próprios, que muitíssima gente simplesmente deixa vazios. E os seus reagentes, que carregam os mesmos símbolos de qualidade, então material barato nem sempre sai mais barato.\n\nSe você ficar a um degrau de distância, existe uma rede de segurança chamada Concentração. Ela tem um capítulo próprio mais abaixo.\n\nUma armadilha que vale nomear, porque custa ouro de verdade: |cffffffffestar meio especializado é mais caro do que não se especializar|r. Espalhe os seus pontos por quatro ramos e você fica devendo em todos. Você fabrica qualquer coisa em um grau mediano, e mediano não vende e é recusado nas encomendas.\n\nSe você coleta em vez de fabricar, as suas ervas e o seu minério também têm graus — mas apenas |cffffffffdois|r deles em Midnight, e não a escada inteira. Mais Perícia significa o melhor dos dois com mais frequência. Não há um terceiro grau para perseguir.",
	PROFACAD_CH_QUALITY_TASK = "Abra uma receita e encontre a barra de Qualidade e o quadro Detalhes da criação.",
	PROFACAD_CH_STATS_TITLE = "Os seis números que ninguém explica",
	PROFACAD_CH_STATS_INTRO = "Multicriação, Desenvoltura, Destreza. O jogo nunca diz o que eles fazem, e a maioria dos jogadores procura de novo toda santa vez.",
	PROFACAD_CH_STATS_ADVANCED = "Onde você vê isso de verdade? Abra qualquer receita na sua janela de profissão e olhe o quadro Detalhes da criação à direita — os seis aparecem ali como porcentagens, por exemplo Desenvoltura 4%, Multicriação 4%, Engenhosidade 19%. O mesmo quadro mostra a Dificuldade da receita contra a sua Perícia e, abaixo disso, quanto de Concentração custaria forçar o próximo grau de qualidade.",
	PROFACAD_CH_STATS_BODY = "A imagem que ajuda: |cffffffffa Perícia decide o quão bom fica, esses seis decidem o quão barato você chegou lá.|r A Perícia é sobre o resultado; estes são sobre o caminho até ele.\n\nSão três para fabricar e três para coletar, então você nunca precisa dos seis ao mesmo tempo.\n\nFabricar. |cffffffffDesenvoltura|r significa que uma fabricação às vezes consome menos do que deveria e você fica com os materiais. Funciona em tudo, e é a única que melhora o seu lucro na encomenda de outra pessoa, porque as sobras ficam com você e não com o cliente. |cffffffffMulticriação|r significa que às vezes sai mais de um com os mesmos materiais. |cffffffffEngenhosidade|r devolve parte da sua Concentração.\n\nA armadilha dessa lista: |cffffffffMulticriação não faz nada por equipamento.|r Uma cópia extra só significa alguma coisa para o que empilha — poções, gemas, materiais. Um anel ou um peitoral nunca dobra, então, se você fabrica principalmente equipamento, a Multicriação é desperdício. E nas encomendas dos outros as cópias extras vão para o |cffffffffcliente|r, não para você. Essa última parte é o que os jogadores relatam entre si; a Blizzard nunca confirmou.\n\nColetar. |cffffffffFinesse|r dá mais por nó, que é o seu volume e portanto o seu ouro. |cffffffffPercepção|r dá uma chance melhor do material raro em vez de mais do comum. |cffffffffDestreza|r encurta a animação de coleta.\n\nQual deles pesa mais depende do que você faz, e é aí que está a parte útil. O Herborismo quer Finesse: por hora você passa muito mais tempo procurando e voando do que colhendo, então colher mais rápido resolve o problema errado. A Mineração é igual, e a Percepção é fraca ali, porque o minério raro para o qual ela te empurra tem pouco uso em receitas. |cffffffffO Esfolamento inverte isso|r — quando você já está caçando as feras raras, a Percepção é forte, porque é ali que estão os drops caros. É a única profissão de coleta em que isso vale. Esses três são julgamentos sobre como as profissões se jogam, e não números que alguém publicou.\n\nOs valores vêm de dois lugares que você controla: os seus pontos de Conhecimento, já que muitos nós dão um desses seis, e o seu equipamento de profissão. Então, ao gastar um ponto, olhe qual atributo está por baixo do nó e se ele combina com o que você realmente pretende fabricar.\n\nSe você guardar só uma coisa: |cffffffffdecida o que vai fabricar e só então escolha o seu atributo.|r Quem vende poções e quem faz anéis têm interesses opostos, e um guia que diz \"a Multicriação é a melhor\" não diz com quem está falando.",
	PROFACAD_CH_STATS_TASK = "Abra o Detalhes da criação em uma receita e leia as suas próprias três porcentagens.",
	PROFACAD_CH_CONC_TITLE = "Concentração, o freio de emergência",
	PROFACAD_CH_CONC_INTRO = "Às vezes você fica a um grau de distância, e fabricar a coisa mesmo assim parece desperdício. É exatamente para isso que serve a Concentração.",
	PROFACAD_CH_CONC_ADVANCED = "Onde você encontra isso de verdade? Na sua janela de profissão é uma barra perto do topo mostrando o seu total atual e, quando você abre uma receita, há um botão de chama ao lado do botão de fabricar mostrando quanto aquela fabricação específica custaria. O custo varia por receita, então leia antes de apertar.",
	PROFACAD_CH_CONC_BODY = "A imagem: |cffffffffé uma bateria que se enche sozinha.|r Você não faz nada por ela, ela recarrega por conta própria, e você pode drená-la no momento em que isso importa. Gaste em uma fabricação e o próximo grau de qualidade é |cffffffffgarantido|r — não é chance, não é rolagem. O próprio jogo diz: \"Apply 358 concentration to guarantee the next quality for this recipe.\"\n\nAqui está a história inteira, e é por isso que as pessoas usam mal. A bateria comporta |cffffffff1000|r e recarrega cerca de |cffffffff250 por dia|r, ou seja, uns quatro dias do vazio até o cheio. Isso é lento. Toda vez que você usa, está gastando parte dos seus próximos dias, e quando ela está vazia só resta esperar.\n\nCada profissão tem a sua |cffffffffprópria|r bateria. Um alquimista que também colhe ervas tem duas, e elas não têm relação entre si.\n\nTambém não é barato por uso. Uma fabricação real custou 358 dos 1000 — mais de um terço da bateria por um único item.\n\nVale gastar: em algo que ficou a um grau de distância e que você mesmo vai usar ou vestir; em uma encomenda com uma qualidade mínima que você não alcança de outro jeito, já que sem isso você não consegue concluir aquela encomenda; e em qualquer coisa cara, em que a diferença entre os graus vale mais do que um dia de bateria.\n\nNão vale gastar: em algo que você já fabrica no grau máximo de qualquer forma, em que você não compra nada e perde a bateria. Esse é o erro mais comum, porque as pessoas deixam o botão ligado e nunca percebem. E em produção barata em massa — cinquenta poções um grau acima é agradável, mas não vale quatro dias.\n\nVocê recupera parte disso. |cffffffffEngenhosidade|r, um dos seis atributos, de vez em quando devolve parte do que você acabou de gastar, e o jogo avisa quando acontece. É exatamente por isso que a Engenhosidade só fica interessante quando você começa a mirar em qualidade: sem gasto, não há o que devolver.\n\nMais uma coisa, e ela é sobre pessoas e não sobre mecânica. Se você queima Concentração para atingir a qualidade na encomenda |cffffffffde outra pessoa|r, ela leva o item melhor e você paga de uma bateria que leva dias para se recuperar. Artesãos experientes cobram mais por isso. Não é uma regra e não existe tabela, mas vale saber que pedir não é ganância e que peçam a você não é estranho.\n\nConcentração não é um sistema para gerenciar ou otimizar. É um freio, ali para o momento em que você fica a um grau de algo que vale a pena. Se ela enche sozinha enquanto você joga, está tudo bem. Se ela fica semanas no máximo, você provavelmente está deixando qualidade na mesa.",
	PROFACAD_CH_CONC_TASK = "Encontre a sua barra de Concentração e veja se ela está parada no máximo.",
	PROFACAD_CH_GOLD_TITLE = "Fazer ouro sem se enganar",
	PROFACAD_CH_GOLD_INTRO = "Existe só uma conta aqui, e quase ninguém faz: o que você recebe, menos tudo o que entrou, menos 5% para a Casa de Leilões.",
	PROFACAD_CH_GOLD_BODY = "A palavra que as pessoas pulam é |cfffffffftudo|r. Ervas que você mesmo colheu |cffffffffnão são de graça|r. Elas têm preço de mercado, e colocá-las em uma poção em vez de vendê-las significa que você gastou esse valor — só que pagou a si mesmo. Se a erva vale mais do que a poção, fabricar é |cffffffffperder dinheiro de um jeito que parece ganhar|r.\n\n|cffffcc00Existem dois mercados, e eles obedecem a leis opostas.|r Quase toda a confusão sobre se uma profissão \"compensa\" vem de misturar os dois.\n\nO primeiro é o de |cffffffffmercadorias|r: materiais, poções, frascos, gemas — tudo o que empilha. Você vende coisas, e concorre com a região inteira em vez de com o seu próprio reino. Os compradores não veem nada além do preço.\n\nO segundo é o de |cffffffffequipamento fabricado|r. Ele fica no seu reino, e o melhor dele se vincula a uma pessoa, então nem sequer pode ir à Casa de Leilões. Aqui você não vende coisas, você vende o seu ofício.\n\n|cffffcc00Por que o mercado de mercadorias sempre afunda|r vale entender, e nenhum dos motivos é \"tem muito jogador\". O jogo compra automaticamente o anúncio mais barato, então um cobre acima do preço mais baixo significa não vender nada. Você concorre com todos os reinos da sua região ao mesmo tempo. A Multicriação distribui oferta extra de graça, e só funciona no que empilha — exatamente este mercado. E consumíveis têm apenas dois graus de qualidade em vez da escada inteira, então a queda até o fundo é mais curta.\n\nExiste um freio: enquanto os artesãos ainda precisam de Concentração para chegar à qualidade máxima, a qualidade máxima é escassa. Assim que eles conseguem sozinhos, o freio solta e o preço cai. Então, neste mercado, você ganha na janela |cffffffffantes|r de isso acontecer.\n\n|cffffcc00O que realmente protege um preço é uma trava na oferta.|r São quatro tipos: um cooldown na receita, um reagente que o artesão nunca consegue fornecer sozinho, uma receita atrás de reputação, e a Concentração, porque ela recarrega devagar. |cffffffffOnde há trava, há margem. Onde não há, há volume e quase nenhuma margem.|r Esse é o assunto inteiro em uma frase.\n\nColetar é a exceção que confirma isso: o que você colhe não tem custo, então você |cffffffffnão pode|r perder — a única maneira de fazer ouro em que um iniciante não erra. Mas custo zero também significa barreira zero, então o preço se acomoda no que o coletor menos exigente aceitar.\n\n|cffffcc00Todo item fabricado cai em uma de três caixas, e a terceira é a armadilha.|r Livremente negociável diz isso na própria tooltip: \"Pode ser comprado e vendido na Casa de Leilões.\" O item Vinculado não pode ir a leilão, mas |cffffffffpode|r ser vendido por encomenda, que entrega direto ao cliente — ali você vende mão de obra, e não produto. E o que |cffffffffVincula ao Bando de Guerra|r não pode nenhum dos dois: sem leilão, sem encomenda, só você e os seus próprios alts. Isso não é um negócio, é um serviço.\n\nAlquimistas em especial: os dois caldeirões que abastecem o seu raid inteiro têm |cffffffffambos|r a marca Vincula ao Bando de Guerra. Você nunca poderá vendê-los. Você os fabrica, você os leva, e o que recebe de volta é boa vontade. Tudo bem — mas isso deveria ser uma escolha, e não uma descoberta, porque entram materiais caros.\n\n|cffffcc00Em massa ou sob encomenda?|r Em massa você vende o produto, concorre com a região inteira no preço, tem volume ilimitado e uma margem que só afina. Nas encomendas você vende a sua habilidade, concorre com os artesãos do seu próprio reino na reputação, tem volume limitado e margem mais estável. Daí sai uma aritmética, e não uma opinião: |cffffffffa fila de encomendas públicas não é um negócio.|r Você guarda quatro e recebe uma de volta por dia — cerca de sete por semana. Isso é dinheiro de bolso. |cffffffffEncomendas pessoais e de guilda são ilimitadas|r, então um punhado de clientes fiéis que mandam encomendas direto para você é onde está o trabalho de verdade.\n\n|cffffcc00O maior erro de iniciante|r é fabricar antes de conferir quanto custam os materiais. Ele tem duas caras e as duas são o mesmo erro: \"eu mesmo colhi, então é de graça\" e \"eu tenho essa receita, então vou fabricar\". Ter uma receita não diz nada sobre se aquilo compensa. |cffffffffConfira primeiro quanto custa. E só então decida se vai fabricar.|r\n\nE desconfie de todo \"X de ouro por hora\" de guia ou de vídeo: isso varia por reino e normalmente é inventado. Meça no seu próprio reino. O Auctionator mostra quanto as coisas custam de verdade; o CraftSim calcula quanto uma fabricação rende contra os preços de material de hoje, e é de longe a coisa mais útil de instalar se você quer ganhar a sério.",
	PROFACAD_CH_GOLD_DATED_202608 = "|cffffcc00Como está no fim de agosto de 2026 — e esta metade expira.|r A Temporada 2 tem poucos dias, então trate os parágrafos abaixo como uma foto do momento, e não como regra. Vale saber: quase todo guia de \"Season 2\" por aí é datado de antes de a temporada começar, o que faz das afirmações deles previsões, e não observações. Não existe série de preços publicada dessas primeiras semanas, de ninguém.\n\n|cffffffffAlquimia.|r Poções e frascos são livremente negociáveis e vendem bem enquanto o raid é novo e a demanda está no pico — mas este é o mercado de mercadorias a todo vapor, então espere a margem afundar conforme mais artesãos alcançam a qualidade máxima sem Concentração. Sinergista Maravilhoso é a renda mais estável: ele tem um cooldown de cerca de um dia, então ninguém consegue inundar o mercado — que é exatamente a trava descrita acima — e alimenta os dois caldeirões e a pedra épica. A decoração de moradia é a subestimada — seis receitas, negociáveis, e não empilha, então concorre no seu próprio reino em vez de no bolo regional. Uma história de mercado que vale levar: a nova poção de vida do 12.1 consome 25 da antiga, então a poção antiga foi promovida de produto final a ingrediente e caiu quase pela metade como produto. Quem estocou em julho encontrou essa queda em 11 de agosto.\n\n|cffffffffHerborismo.|r Lótus Noturno é a erva cara, e o motivo é preciso: é a única erva de Midnight de qualidade rara, não tem nó próprio (aparece como captura acidental de qualquer outra erva) e entra nos quatro frascos e nos dois caldeirões — onze receitas no total. Os dois materiais novos da Ilha Enrolada são ambos negociáveis, com um aviso: eles |cffffffffnão|r são exclusivos dos herbalistas. Mineradores os tiram dos próprios nós, e um deles também cai de animais por Esfolamento. Vários guias sugerem o contrário.",
	PROFACAD_CH_GOLD_TASK = "Antes da sua próxima fabricação, veja quanto custam os materiais dela — e só então decida se vai fazer.",
	PROFACAD_CH_WORKORDERS_TITLE = "Encomendas (Pedidos de Criação): comprando o ofício de outra pessoa",
	PROFACAD_CH_WORKORDERS_INTRO = "A Casa de Leilões te vende coisas que já existem. Na mesa de encomendas funciona ao contrário: você leva os materiais e paga alguém pelo trabalho.",
	PROFACAD_CH_WORKORDERS_ADVANCED = "Duas coisas que fazem o sistema parecer quebrado quando ele não está. Na sua própria bancada, a lista de encomendas públicas fica vazia até você apertar |cffffffffProcurar|r — não há nada errado, ela simplesmente não carrega sozinha. E o homem que fica na mesa de encomendas, Capitão Claranjuro, não faz parte disso: ele entrega a missão introdutória da sua profissão, as suas missões semanais e sacos grátis de material. Útil, mas não é o que você veio buscar.",
	PROFACAD_CH_WORKORDERS_BODY = "Funciona assim porque o melhor equipamento fabricado se vincula a uma pessoa no instante em que existe. Ninguém consegue fabricá-lo com antecedência e deixá-lo na prateleira, então alguém tem de fabricá-lo |cffffffffespecificamente para você|r.\n\n|cffffcc00Existem dois balcões, e é aqui que costuma dar errado.|r Para mandar fazer algo, vá até a mesa de encomendas no Bazar de Luaprata — o grande martelo dourado no seu minimapa. A pessoa que você procura é Mar'nah. Para fabricar algo para outra pessoa, vá até a |cffffffffbancada da sua própria profissão|r. Se você não estiver ao lado dela, não há botão e não há lista, e parece que o sistema não existe. Esse é o erro mais comum, e o jogo não explica isso em lugar nenhum.\n\n|cffffcc00Mandar fazer algo.|r Escolha o seu item e depois escolha a quem você está pedindo. A ninguém em particular (o botão diz Public Order): todo mundo no seu reino vê a encomenda e o primeiro que pegar é quem fabrica. Rápido, mas você recebe o que vier — |cffffffffaqui você não pode exigir qualidade|r, e precisa mandar todos os materiais você mesmo. A um jogador específico (Personal Order): aqui você pode definir uma qualidade mínima e pode combinar que ele entre com material próprio. Para a guilda inteira (Guild Order) funciona igual e alcança colegas de guilda em outros reinos. Você define o pagamento, e um botão ao lado mostra quanto outros pagaram recentemente pelo mesmo item.\n\nTrês coisas para saber antes de clicar em encomendar. Alguns reagentes especiais nunca podem ser fornecidos pelo artesão, então esses você manda sempre. Material no seu banco do Bando de Guerra |cffffffffnão conta|r — coloque nas suas bolsas. E o item se vincula a |cffffffffvocê|r, então encomende no personagem que vai usá-lo, e não naquele que está com o ouro. Depois que alguém pega a encomenda você não pode mais cancelá-la; o item chega pelo correio.\n\n|cffffcc00Fabricar para os outros.|r Na sua bancada você vê quanto vai ganhar antes de começar. Assim que começa, você tem |cffffffff30 minutos|r para terminar — dá para buscar alguma coisa, não dá para ir comer.\n\nVocê não pode pegar encomendas públicas sem parar: você guarda |cffffffff quatro|r, e |cffffffffuma volta a cada dia|r. Ou seja, umas sete por semana, e não quatro por dia. Encomendas quase expiradas podem ser pegas de graça.\n\nSe uma encomenda te recusa, é uma de quatro coisas: você não conhece a receita, a sua especialização não está avançada o bastante para os extras que ela pede, ela quer uma qualidade que você não alcança, ou a sua cota acabou.\n\nE uma que te custa dinheiro em silêncio: |cffffffffveja de quem são os materiais que você está usando.|r Nas encomendas públicas o cliente sempre fornece tudo, mas nos outros tipos ele pode não fornecer nada — e aí você fabrica alegremente com o seu próprio estoque caro em troca de uma gorjeta.",
	PROFACAD_CH_WORKORDERS_TASK = "Encontre a mesa de encomendas no Bazar de Luaprata e depois encontre a bancada da sua própria profissão. Não são o mesmo lugar.",
	PROFACAD_CH_PATRON_TITLE = "A aba Cliente, o seu motor semanal de Conhecimento",
	PROFACAD_CH_PATRON_INTRO = "O quarto tipo de encomenda vem do próprio jogo em vez de vir de um jogador, e é aquele que a maioria das pessoas nunca encontra.",
	PROFACAD_CH_PATRON_BODY = "Na sua própria bancada existe uma aba |cffffffffCliente|r onde o jogo te dá encomendas. Nenhum outro jogador, nenhuma concorrência — elas são só suas. O que você recebe não é bem ouro, e sim |cffffffffpontos de Conhecimento|r: os mesmos pontos que deixam a sua profissão mais forte.\n\nEsta é de longe a sua maior fonte semanal deles. Pule isso e você fica para trás sem nunca entender por que os outros avançam mais rápido.\n\nUma leva nova chega a cada poucos dias. Cada encomenda pede uma certa qualidade, e às vezes você precisa fornecer material — confira isso, porque uma encomenda cara por dois pontos nem sempre vale a pena. Pode pular uma.\n\n|cffffcc00E agora a armadilha.|r O jogo também te dá uma encomendinha de um ponto por dia, mas |cffffffffsó enquanto você estiver atrás da sua meta semanal|r. Faça todas as encomendas grandes na segunda-feira e você fica em dia — então as pequenas diárias param pelo resto da semana.\n\nEntão: |cffffffffdeixe as encomendas grandes até que estejam perto de expirar|r. Você continua recebendo as pequenas nesse meio-tempo, e termina a semana com mais pontos do que teria. Parece errado. Mesmo assim é verdade.",
	PROFACAD_CH_PATRON_TASK = "Abra a aba Cliente na sua própria bancada e veja o que esta semana está oferecendo.",
	PROFACAD_CH_ALCHEMY_BODY = "A Alquimia te oferece uma árvore com 25, 50, 60 e 75 de Perícia — o jogo não escolhe, você escolhe. As quatro são Proeza em Poções (poções, com um lado voltado para a Luz e outro para o Vazio), Fluente em Frascos, Autoridade em Transmutação e Maestria Alquímica.\n\n|cffffcc00Build inicial, nesta ordem.|r |cffffffffProeza em Poções|r primeiro: enchê-la dá o Caldeirão de Poções da Luz Caótica, que serve ao seu ouro e à sua guilda ao mesmo tempo. Depois |cffffffffCaminho da Luz|r e |cffffffffPocionista Prolífico - Luz|r, que é o nó de Multicriação — Luz porque é essa a poção que vende nesta temporada. Então |cffffffffMaestria Alquímica|r e, dentro dela, |cffffffffReuse|r, que devolve ervas para você e é forte se você também as colhe.\n\nDepois disso, cerca de 15 pontos em |cffffffffFluente em Frascos|r, que dobra a duração dos seus próprios frascos, e então |cffffffffEspecialista Sin'dorei|r. |cffffffffAutoridade em Transmutação|r vem por último, e não em segundo.\n\n|cffffffffSegredos Haranir não são um detalhe.|r A tooltip do nó termina com \"e Caldeirão de Frascos Sin'dorei\" — sem pontos ali você não consegue fabricar o caldeirão de frascos no grau máximo. Os guias parafraseiam esse nó como \"phials only\" e cortam justamente a meia frase que importa.",
	PROFACAD_CH_HERBALISM_BODY = "Toda erva nasce em toda zona, então não há zona para escolher e sofrer com isso. A ordem abaixo é a que a rota deste addon recomenda hoje, e cada passo é uma coisa que você desbloqueia, e não uma distribuição vaga.\n\n|cffffcc00Primeiro: cerca de 40 pontos em Botânica.|r Isso é colher montado, e é de longe a maior economia de tempo da profissão — sem isso você desmonta e monta de novo a cada planta. Druidas pulam esta parte: eles já coletam montados.\n\n|cffffcc00Depois cerca de 20 em Húmus|r, que as pessoas deixam de fora e não deveriam. Ele dá o Húmus Imbuído: um achado raro garantido na sua próxima colheita, e o achado raro é o Lótus Noturno — a única erva de Midnight de qualidade rara, sem nó próprio, presente nos quatro frascos e nos dois caldeirões.\n\n|cffffcc00Depois Colheitas Fartas|r para o longo prazo: mais ervas por nó e mais Perícia, ou seja, qualidade máxima com mais frequência. Dentro desse ramo cada erva tem o seu próprio nó, então você pode mirar na que vende melhor no seu reino.\n\n|cffffcc00Deixe a Sobrecarga da Meia-noite de lado.|r Ela só funciona nos nós elementais, custa muitos pontos, e você encontra poucos deles. Só vale se você estiver farmando motes de propósito.\n\nEsses números de pontos vêm de uma fonte cada. Passe o mouse sobre o nó no jogo antes de clicar — a tooltip tem o número real, e você só ganha um reset.",
	PROFNEXT_UNSPENT_LOCKED_FMT = "%s: %d de Conhecimento guardados, e ainda não há onde colocar - nenhuma especialização é desbloqueável, então suba a Perícia primeiro (a primeira escolha vem no 25)",
	SMC_PIN_NEAREST_FP = "Aponta a seta para o mestre de voo mais próximo de onde você estiver, e não só nesta cidade. Também disponível como /mh fp.",
	FP_NEAREST_SET_FMT = "Seta apontada para o mestre de voo mais próximo: %s.",
	FP_NEAREST_NO_MAP = "Não consigo ver onde você está agora, então não consigo escolher um mestre de voo.",
	FP_NEAREST_NONE = "Ainda não há pontos de voo registrados para esta zona.",
	FP_NEAREST_NONE_FACTION = "Esta zona tem pontos de voo, mas nenhum que a sua facção possa usar.",
	FP_NEAREST_NO_WAYPOINT = "Não foi possível marcar um waypoint ali.",
	SMC_PIN_FLIGHTMASTER = "Luaprata tem dois mestres de voo, então a pergunta útil é qual está mais perto. Os dois fazem as mesmas rotas.",
})

fill("itIT", {
	CMDLIST_FP = "Freccia verso il maestro di volo più vicino, ovunque tu sia",
	CMDLIST_COURSE = "Professions 101 in una finestra tutta sua, accanto al gioco",
	TOOLLP_COURSE_NAME = "Corso Professions 101",
	TOOLLP_COURSE_DESC = "Il corso per principianti in una finestra tutta sua, così l'elenco dei capitoli ha tutta l'altezza e il testo resta accanto al gioco mentre fai il compito.",
	PROFACAD_BTN_FULL_COURSE = "Corso completo",
	PROFACAD_ADVISE_NEXT_POINTS_FMT = "Consiglio: prossimi punti in %s (radice %d/%d) — punta a circa %d. Passa il mouse sul nodo nel gioco; la sua tooltip ha il numero esatto, e le guide non sono d'accordo tra loro.",
	PROFACAD_ADVISE_NEXT_OPEN_FMT = "Consiglio: sblocca %s — e poi fermati. È lo sblocco a rendere; i punti oltre quello sono una scommessa sui prezzi dei materiali.",
	PROFACAD_ADVISE_GOALS_FMT = "Da qui il percorso si divide, e i due sono davvero diversi. %s",
	PROFACAD_ADVISE_GOAL_LINE_FMT = "%s %s (radice %d/%d).",
	PROFACAD_GOAL_GOLD = "Vendere ad altri:",
	PROFACAD_GOAL_SELF = "Equipaggiare te e la tua gilda:",
	PROFACAD_CHOICES_HEADER = "Singoli nodi nei tuoi alberi che non sono ancora pieni:",
	PROFACAD_CHOICES_HEADER_MORE_FMT = "Singoli nodi nei tuoi alberi che non sono ancora pieni (%d di %d):",
	PROFACAD_CH_KNOWLEDGE_BODY = "La tua professione cresce in due modi, ed è esattamente lì che nasce la confusione.\n\nLa tua |cffffffffCompetenza|r sale craftando. Succede da sé. Accanto ad essa raccogli la |cffffffffConoscenza|r, che dal crafting non arriva affatto ma da ordini, tesori e libri — e quella la spendi in un albero, dove scegli in cosa diventi bravo.\n\nL'immagine che aiuta: |cffffffffla competenza è quante volte l'hai fatto, la conoscenza è ciò su cui sei andato a fondo.|r Due alchimisti con la stessa competenza possono fare cose completamente diverse, perché hanno messo la loro conoscenza altrove. È anche per questo che non puoi avere tutto. Devi scegliere.\n\n|cffffcc00Da dove arrivano i punti — cinque fonti, e la prima fa impallidire tutte le altre.|r\n\n1. Ordini dal gioco stesso (la tab Cliente), al tuo banco da lavoro. Hanno un capitolo tutto loro più avanti, compresa la trappola di farli tutti a inizio settimana.\n2. Craftare tutto una volta. Il primo craft di ogni ricetta vale un punto. Fallo prima di iniziare a spendere, così hai più margine.\n3. Tesori nel mondo aperto. Sparsi per le zone di Midnight ci sono contenitori che danno punti — un bel bottino se non li hai ancora raccolti.\n4. Una quest settimanale dal tuo addestratore, e un trattato che uno scriba della Runografia può craftarti.\n5. Libri di reputazione. Qualche fazione ti vende un libro che ne dà dieci in un colpo solo.\n\nCucina, Pesca e Archeologia non hanno alberi e non hanno bisogno di punti.\n\nNon preoccuparti di essere \"indietro\": le settimane saltate tornano lentamente grazie a un sistema di recupero, e questo corso te lo fa percorrere un passo alla volta.",
	PROFACAD_CH_TREES_ADVANCED = "Dove si clicca davvero? Apri la finestra delle professioni (quella con le tue ricette), poi guarda le tab in basso: Ricette, Specializzazioni, Ordini d'Artigianato. Specializzazioni è quella giusta — lì stanno i tuoi alberi ed è lì che si spende la Conoscenza. Non succede nulla finché non confermi, quindi puoi aprirla in tutta tranquillità e dare solo un'occhiata. Non sai quale albero? Torna qui: la Panoramica delle professioni ti indica il prossimo nodo ogni volta che riesce a leggere i tuoi alberi.",
	PROFACAD_CH_TREES_BODY = "Lì trovi tre o quattro |cffffffffruote|r affiancate. Ognuna è fatta di caselle rotonde unite da linee, e la riconosci dall'anello attorno che si riempie man mano che ci metti punti — passaci sopra il mouse e vedrai qualcosa come \"3 / 30\": tre punti dentro, trenta è il pieno. Le guide chiamano nodi queste caselle. Ogni ruota ha una casella grande al centro (la radice) e altre più piccole intorno, che compaiono solo quando quella centrale ha abbastanza punti dentro. Guardarsi intorno non costa nulla: non cambia niente finché non confermi.\n\n|cffffcc00L'unica regola che conta: non distribuire i tuoi punti.|r\n\nMetterne un po' ovunque sembra furbo. È l'errore più costoso che ci sia, e lo fanno tutti. Il motivo è che tutto ciò che vale davvero sta dietro una |cffffffffsoglia|r. A trenta punti succede qualcosa; a quindici non succede niente. Quattro caselle riempite a metà quindi ti danno |cffffffffzero|r — hai speso cento punti e continui a non saper fare niente di speciale.\n\nScegline una. Finiscila. Solo dopo passa oltre. Quanto è alta una soglia cambia da professione a professione e persino da casella a casella, quindi non fidarti di un numero preso da una guida: passaci sopra il mouse e te lo dice.\n\n|cffffcc00Quello che ottieni aprendo un ramo|r non è ciò che la maggior parte si aspetta, ed è una buona notizia. Di solito la ricetta arriva dall'|cffffffffaprire|r un ramo, non dal riempirlo — lo apri e puoi fare subito quella cosa. I punti che ci metti dopo non la rendono possibile, la rendono |cffffffffmigliore|r. Aprire non ti costa nemmeno un punto di Conoscenza; per quello ricevi sblocchi separati, a quote fisse nella casella centrale. Ma non sono infiniti. Per aprire un secondo ramo devi prima andare più a fondo nel centro. Aprire è gratis, ma razionato.\n\n|cffffcc00E alcune cose sono semplicemente spente,|r ed è la trappola in cui la gente conclude che il gioco è rotto. Qualche ramo accende qualcosa che prima non esisteva. Chi ha l'Ingegneria può riciclare il vecchio equipaggiamento, ma ne |cffffffffscopre le ricette|r solo dopo averci messo punti — senza quelli ricicli all'infinito e non succede niente. Chi ha la Sartoria vede cadere la stoffa costosa solo quando ha imparato il ramo giusto. Chi ha l'Erbalismo può raccogliere da cavallo solo dopo essere andato abbastanza a fondo. Se qualcosa \"sembra non funzionare\", controlla prima se non debba ancora essere acceso.\n\n|cffffcc00Hai un solo ripensamento.|r Dalla patch 12.1 puoi annullare i tuoi punti |cffffffffuna volta per professione|r, da Theremis a Lunargenta, vicino al tavolo degli ordini. Una volta — dopodiché le tue scelte restano. Ti fa anche disimparare le ricette che quei punti avevano sbloccato; tornano appena rimetti i punti, ma non spaventarti. E non c'è motivo di essere nervoso: se continui a raccogliere, prima o poi puoi riempire ogni ramo, quindi i punti non si possono davvero |cffffffffsprecare|r — possono solo stare nel posto sbagliato nei mesi in cui conta.\n\nRicevi una scelta di albero a competenza 25, 50, 60 e 75. Non è il gioco a decidere quale; decidi tu. Quando hai delle professioni, i loro capitoli qui sotto danno una build iniziale concreta, e la Panoramica delle professioni mostra consigli in tempo reale sui tuoi alberi.",
	PROFACAD_CH_QUALITY_TITLE = "Qualità — perché la sua spada è migliore della tua",
	PROFACAD_CH_QUALITY_INTRO = "Due giocatori usano la stessa ricetta e uno dei due risultati viene meglio. Non è sfortuna e non è un bug: gli oggetti craftati hanno un grado di qualità.",
	PROFACAD_CH_QUALITY_ADVANCED = "Dove si clicca davvero? Apri una ricetta nella finestra delle professioni e guarda a destra il riquadro Dettagli creazione: mostra la Difficoltà ricetta contro la tua Competenza, cioè l'intero calcolo in due numeri. Clicca un reagente qualsiasi nella ricetta e puoi scegliere quale qualità di materiale ci va — la tooltip dice \"Clicca col pulsante sinistro per assegnare le qualità dei reagenti\". C'è anche una spunta \"Usa i Reagenti della migliore qualità\" che sceglie automaticamente i tuoi migliori. Comoda, ma consuma i tuoi materiali costosi senza chiedertelo due volte.",
	PROFACAD_CH_QUALITY_BODY = "L'immagine che aiuta: la ricetta dice |cffffffffcosa|r stai facendo, la qualità dice quanto bene è venuto. Due fornai con la stessa ricetta non sfornano lo stesso pane.\n\nLo leggi da una piccola |cffffffffforma|r, non da un numero. La tooltip dice \"Qualità:\" con la forma di fianco — un rombo grigio è basso, un pentagono dorato è alto. Nella finestra delle professioni la stessa cosa compare come una barra, la forma più bassa a sinistra e la più alta a destra, con un indicatore bianco che mostra all'incirca dove finirà il tuo craft.\n\nConta per tre motivi, e il terzo frega tutti almeno una volta. Equipaggiamento migliore e pozioni più forti, ovvio. Più oro: la stessa ricetta, Pelle Intessuta a Scaglie, si vendeva a 10g94 al grado più basso e a 21g12 al più alto — quasi il doppio, con gli stessi materiali e lo stesso clic. Ogni grado è davvero un |cffffffffoggetto separato|r con la sua inserzione all'asta, quindi non si impilano tra loro. E il terzo: se qualcuno ordina una qualità minima che non riesci a raggiungere, |cffffffffquell'ordine non puoi proprio completarlo|r. Non \"viene peggio\" — non puoi letteralmente consegnarlo.\n\nA deciderlo è un solo numero: la tua |cffffffffCompetenza|r nel momento in cui premi craft. Ogni ricetta ha una difficoltà. Se le stai comodamente sopra ottieni il grado massimo; se le stai sotto, no.\n\nQuel numero è composto da quattro cose. La tua competenza di base, che sale craftando e prima o poi arriva al massimo. La tua Conoscenza, che dà competenza |cffffffffsolo a quel tipo di ricetta|r — punti negli anelli rendono migliori i tuoi anelli, non le tue collane. Il tuo equipaggiamento da professione: uno strumento e due accessori per professione, in slot dedicati, che moltissimi lasciano semplicemente vuoti. E i tuoi reagenti, che portano le stesse forme di qualità, quindi i materiali economici non sono sempre più convenienti.\n\nSe ti fermi a un gradino di distanza c'è una rete di sicurezza, si chiama Concentrazione. Ha un capitolo tutto suo più sotto.\n\nVale la pena nominare una trappola, perché costa oro vero: |cffffffffessere specializzato a metà è più costoso che non specializzarsi affatto|r. Distribuisci i punti su quattro rami e resti sotto ovunque. Riesci a fare qualunque cosa a un grado mediocre, e il mediocre non si vende e viene rifiutato dagli ordini.\n\nSe raccogli invece di craftare, anche le tue erbe e i tuoi minerali hanno dei gradi — ma in Midnight solo |cffffffffdue|r, non tutta la scala. Più competenza significa più spesso il migliore dei due. Non c'è un terzo grado da inseguire.",
	PROFACAD_CH_QUALITY_TASK = "Apri una ricetta e trova la barra Qualità e il riquadro Dettagli creazione.",
	PROFACAD_CH_STATS_TITLE = "I sei numeri che nessuno spiega",
	PROFACAD_CH_STATS_INTRO = "Creazione multipla, Parsimonia, Velocità. Il gioco non dice mai cosa fanno, e la maggior parte dei giocatori le ricerca daccapo ogni singola volta.",
	PROFACAD_CH_STATS_ADVANCED = "Dove si vedono davvero? Apri una ricetta qualsiasi nella finestra delle professioni e guarda a destra il riquadro Dettagli creazione — i sei compaiono lì come percentuali, per esempio Parsimonia 4%, Creazione multipla 4%, Ingegno 19%. Lo stesso riquadro mostra la Difficoltà ricetta contro la tua Competenza, e sotto quanto ti costerebbe la Concentrazione per forzare il grado di qualità successivo.",
	PROFACAD_CH_STATS_BODY = "L'immagine che aiuta: |cffffffffla Competenza decide quanto bene viene, questi sei decidono quanto ti è costato arrivarci.|r La Competenza riguarda il risultato; questi riguardano la strada per arrivarci.\n\nCe ne sono tre per il crafting e tre per la raccolta, quindi non ti servono mai tutti e sei insieme.\n\nCrafting. |cffffffffLa Parsimonia|r significa che a volte un craft consuma meno del dovuto e i materiali restano a te. Funziona su tutto, ed è l'unica che migliora il tuo guadagno sull'ordine di qualcun altro, perché gli avanzi restano a te e non al cliente. |cffffffffLa Creazione multipla|r significa che a volte ottieni più di un pezzo dagli stessi materiali. |cffffffffL'Ingegno|r ti restituisce una parte della tua Concentrazione.\n\nLa trappola in quell'elenco: |cffffffffLa Creazione multipla non fa nulla sull'equipaggiamento.|r Una copia in più ha senso solo per le cose che si impilano — pozioni, gemme, materiali. Un anello o una corazza non raddoppiano mai, quindi se crafti soprattutto equipaggiamento, la Creazione multipla è sprecata. E sugli ordini altrui le copie extra vanno al |cffffffffcliente|r, non a te. Quest'ultima parte è ciò che i giocatori si raccontano tra loro; Blizzard non l'ha mai confermata.\n\nRaccolta. |cffffffffLa Precisione|r ti dà di più per nodo, cioè il tuo volume e quindi il tuo oro. |cffffffffLa Percezione|r ti dà più possibilità di trovare il materiale raro invece di più materiale comune. |cffffffffLa Velocità|r accorcia l'animazione di raccolta.\n\nQuale conta di più dipende da cosa fai, ed è questa la parte utile. L'Erbalismo vuole la Precisione: in un'ora passi molto più tempo a cercare e a volare che a raccogliere, quindi raccogliere più in fretta risolve il problema sbagliato. L'Estrazione è uguale, e lì la Percezione è debole, perché il minerale raro verso cui ti spinge serve a poco nelle ricette. |cffffffffLa Scuoiatura ribalta la cosa|r — quando vai a caccia delle bestie rare, la Percezione diventa forte, perché è lì che stanno i drop costosi. È l'unica professione di raccolta in cui vale. Questi tre sono giudizi su come si giocano le professioni, non numeri che qualcuno abbia pubblicato.\n\nI valori vengono da due posti che controlli tu: la tua Conoscenza, dato che molti nodi ne danno uno dei sei, e il tuo equipaggiamento da professione. Quindi quando spendi un punto, guarda quale stat sta sotto il nodo e se corrisponde a quello che davvero hai intenzione di craftare.\n\nSe devi ricordare una cosa sola: |cffffffffdecidi cosa vuoi craftare, poi scegli la tua stat.|r Chi vende pozioni e chi fa anelli hanno interessi opposti, e una guida che dice \"la Creazione multipla è la migliore\" non ti dice a chi si sta rivolgendo.",
	PROFACAD_CH_STATS_TASK = "Apri i Dettagli creazione su una ricetta e leggi le tue tre percentuali.",
	PROFACAD_CH_CONC_TITLE = "Concentrazione, il freno d'emergenza",
	PROFACAD_CH_CONC_INTRO = "A volte ti manca un grado, e craftare comunque l'oggetto sembra uno spreco. È esattamente a questo che serve la Concentrazione.",
	PROFACAD_CH_CONC_ADVANCED = "Dove la trovi davvero? Nella finestra delle professioni è una barra in alto che mostra il tuo totale attuale, e quando apri una ricetta c'è un pulsante a fiamma accanto al pulsante di craft che mostra quanto costerebbe quel craft specifico. Il costo cambia da ricetta a ricetta, quindi leggilo prima di premere.",
	PROFACAD_CH_CONC_BODY = "L'immagine: |cffffffffè una batteria che si ricarica da sola.|r Non fai nulla per averla, si riempie da sé, e puoi scaricarla nel momento che conta. Spendila su un craft e il grado di qualità successivo è |cffffffffgarantito|r — non una probabilità, non un tiro di dado. Lo dice il gioco stesso: \"Applica 358 Concentrazione per garantire la qualità successiva per questa ricetta.\"\n\nEcco tutta la storia, ed è il motivo per cui la gente la usa male. La batteria arriva a |cffffffff1000|r e si ricarica di circa |cffffffff250 al giorno|r, quindi da vuota a piena passano più o meno quattro giorni. È lenta. Ogni volta che la usi stai spendendo una parte dei tuoi prossimi giorni, e quando è vuota puoi solo aspettare.\n\nOgni professione ha la |cffffffffsua|r batteria. Un alchimista che raccoglie anche erbe ne ha due, e non c'entrano nulla l'una con l'altra.\n\nNemmeno per singolo utilizzo è economica. Un craft reale è costato 358 su 1000 — più di un terzo della batteria per un solo oggetto.\n\nVale la pena spenderla su: qualcosa a cui manca un grado e che indosserai o userai tu; un ordine con una qualità minima che altrimenti non raggiungi, dato che senza non puoi completare quell'ordine affatto; e qualsiasi cosa costosa, dove il salto tra un grado e l'altro vale più di un giorno di batteria.\n\nNon vale la pena spenderla su: qualcosa che comunque fai già al grado massimo, dove non compri nulla e perdi la batteria. È l'errore più comune, perché la gente lascia il pulsante attivo e non se ne accorge. E la roba economica in serie — cinquanta pozioni un grado più su fa piacere, ma non vale quattro giorni.\n\nQualcosa torna indietro. |cffffffffL'Ingegno|r, una delle sei stat, ogni tanto rimborsa parte di quello che hai appena speso, e il gioco te lo segnala. È proprio per questo che l'Ingegno diventa interessante solo quando cominci a puntare alla qualità: se non spendi nulla, non c'è nulla da rimborsare.\n\nUn'ultima cosa, che riguarda le persone più che le meccaniche. Se bruci Concentrazione per raggiungere la qualità sull'ordine di |cffffffffqualcun altro|r, quello riceve l'oggetto migliore e tu paghi da una batteria che ci mette giorni a riprendersi. Gli artigiani esperti si fanno pagare di più per questo. Non è una regola e non c'è una tariffa fissa, ma è utile sapere che chiederlo non è avidità e sentirselo chiedere non è strano.\n\nLa Concentrazione non è un sistema da gestire o ottimizzare. È un freno, sta lì per il momento in cui ti manca un grado su qualcosa che ne vale la pena. Se si riempie mentre giochi, stai andando bene. Se resta piena per settimane, probabilmente stai lasciando qualità sul tavolo.",
	PROFACAD_CH_CONC_TASK = "Trova la tua barra della Concentrazione e controlla se è rimasta ferma sul pieno.",
	PROFACAD_CH_GOLD_TITLE = "Fare oro senza prendersi in giro",
	PROFACAD_CH_GOLD_INTRO = "Qui c'è una sola somma, e quasi nessuno la fa: quello che ti pagano, meno tutto quello che ci è entrato, meno il 5% per la Casa d'Aste.",
	PROFACAD_CH_GOLD_BODY = "La parola che tutti saltano è |cfffffffftutto|r. Le erbe che hai raccolto tu |cffffffffnon sono gratis|r. Hanno un prezzo di mercato, e metterle in una pozione invece di venderle significa che quel prezzo l'hai speso — l'hai solo pagato a te stesso. Se l'erba vale più della pozione, craftare è |cffffffffperdere soldi in un modo che sembra guadagnarli|r.\n\n|cffffcc00Ci sono due mercati, e obbediscono a leggi opposte.|r Quasi tutta la confusione sul fatto che una professione \"renda\" nasce dal confonderli.\n\nIl primo è quello delle |cffffffffmerci|r: materiali, pozioni, tonici, gemme — tutto ciò che si impila. Vendi oggetti, e competi con l'intera regione invece che con il tuo reame. I compratori non vedono altro che il prezzo.\n\nIl secondo è quello dell'|cffffffffequipaggiamento craftato|r. Resta sul tuo reame, e il meglio si lega a una sola persona, quindi alla Casa d'Aste non ci può proprio andare. Qui non vendi oggetti, vendi la tua maestria.\n\n|cffffcc00Perché il mercato delle merci scende sempre|r vale la pena capirlo, e nessuno dei motivi è \"ci sono tanti giocatori\". Il gioco compra automaticamente l'inserzione più economica, quindi un rame sopra il prezzo più basso significa nessuna vendita. Competi con tutti i reami della tua regione in una volta sola. La Creazione multipla distribuisce offerta extra gratis, e funziona solo sulle cose che si impilano — esattamente questo mercato. E i consumabili hanno solo due gradi di qualità invece di tutta la scala, quindi la caduta fino al fondo è più corta.\n\nC'è un freno: finché gli artigiani hanno ancora bisogno della Concentrazione per arrivare alla qualità massima, la qualità massima è scarsa. Quando ci arrivano da soli il freno molla e il prezzo scende. Quindi in questo mercato guadagni nella finestra |cffffffffprima|r che succeda.\n\n|cffffcc00Quello che protegge davvero un prezzo è un lucchetto sull'offerta.|r Ce ne sono di quattro tipi: un cooldown sulla ricetta, un reagente che l'artigiano non può mai procurarsi da solo, una ricetta dietro la reputazione, e la Concentrazione, perché si ricarica lentamente. |cffffffffDove c'è un lucchetto c'è margine. Dove non ce n'è, c'è volume e quasi nessun margine.|r Ecco tutto l'argomento in una frase.\n\nLa raccolta è l'eccezione che lo dimostra: quello che raccogli non ha costo, quindi |cffffffffnon puoi|r perderci — l'unico modo di fare oro in cui un principiante non può sbagliare. Ma nessun costo significa anche nessuna barriera, quindi il prezzo si assesta su quanto accetta il raccoglitore meno esigente.\n\n|cffffcc00Ogni oggetto craftato finisce in una di tre caselle, e la terza è la trappola.|r Liberamente commerciabile lo dice da sé nella propria tooltip: \"Può essere comprato e venduto alla Casa d'Aste.\" Vincolato non si può mettere all'asta ma |cffffffffsi può|r vendere tramite un ordine, che consegna dritto al cliente — lì vendi lavoro, non un prodotto. E |cffffffffSi vincola alla Brigata|r non permette né l'uno né l'altro: niente asta, niente ordine, solo tu e i tuoi alt. Non è un'attività, è un servizio.\n\nAlchimisti in particolare: i due calderoni che riforniscono tutto il tuo raid si vincolano |cffffffffentrambi|r alla Brigata. Non potrai mai venderli. Li fai, li porti, e quello che ti torna indietro è la riconoscenza. Va benissimo — ma dovrebbe essere una scelta e non una scoperta, perché ci entrano materiali costosi.\n\n|cffffcc00In serie o su ordinazione?|r In serie vendi il prodotto, competi sul prezzo con l'intera regione, hai volume illimitato e un margine che si assottiglia sempre di più. Sugli ordini vendi la tua bravura, competi sulla reputazione con gli artigiani del tuo reame, hai volume limitato e un margine più stabile. Da cui segue un conto e non un'opinione: |cffffffffla coda degli ordini pubblici non è un'attività.|r Ne tieni quattro e ne recuperi uno al giorno — circa sette a settimana. Sono spiccioli. |cffffffffGli ordini personali e gli ordini di gilda sono illimitati|r, quindi una manciata di clienti fissi che ti mandano ordini diretti è dove sta il lavoro vero.\n\n|cffffcc00L'errore più grande dei principianti|r è craftare prima di aver controllato quanto costano i materiali. Ha due facce ed è lo stesso errore: \"l'ho raccolto io, quindi è gratis\" e \"ho questa ricetta, quindi la crafto\". Avere una ricetta non dice nulla su quanto renda. |cffffffffControlla prima quanto costa. Poi decidi se craftarlo.|r\n\nE diffida di ogni \"X oro all'ora\" preso da una guida o da un video: cambia da reame a reame ed è di solito inventato. Misura invece sul tuo reame. Auctionator mostra quanto costano davvero le cose; CraftSim calcola quanto rende un craft ai prezzi dei materiali di oggi, ed è la singola cosa più utile da installare se vuoi guadagnare sul serio.",
	PROFACAD_CH_GOLD_DATED_202608 = "|cffffcc00Come stanno le cose a fine agosto 2026 — e questa metà scade.|r La Stagione 2 ha pochi giorni, quindi tratta i paragrafi qui sotto come un'istantanea e non come una regola. Utile sapere: quasi tutte le guide \"Stagione 2\" in circolazione portano una data precedente all'inizio della stagione, il che rende le loro affermazioni previsioni e non osservazioni. Non esiste, di nessuno, una serie di prezzi pubblicata per queste prime settimane.\n\n|cffffffffAlchimia.|r Pozioni e tonici sono liberamente commerciabili e si vendono bene mentre il raid è nuovo e la domanda è al picco — ma questo è il mercato delle merci in piena attività, quindi aspettati che il margine scenda man mano che più artigiani raggiungono la qualità massima senza Concentrazione. Il Sinergico Meraviglioso è l'entrata più stabile: ha un cooldown di circa un giorno, quindi nessuno può inondare il mercato, che è esattamente il lucchetto descritto sopra, e alimenta entrambi i calderoni e la pietra epica. La decorazione per gli Alloggi è quella sottovalutata: sei ricette, commerciabili, e non si impilano, quindi competono sul tuo reame invece che nel bacino regionale. Una storia di mercato da portarsi dietro: la nuova pozione di cura della 12.1 consuma 25 di quella vecchia, quindi la vecchia pozione è stata promossa da prodotto finito a ingrediente e come prodotto ha più o meno dimezzato il proprio valore. Chi ne aveva fatto scorta a luglio si è trovato davanti quel dimezzamento l'11 agosto.\n\n|cffffffffErbalismo.|r Il Loto Notturno è l'erba costosa, e il motivo è preciso: è l'unica erba di Midnight di qualità rara, non ha un nodo tutto suo (salta fuori come pescato accessorio di ogni altra erba), e compare in tutti e quattro i tonici e in entrambi i calderoni — undici ricette in totale. I due nuovi materiali dell'Isola Serpeggiante sono entrambi commerciabili, con un avvertimento: |cffffffffnon|r sono esclusivi di chi ha l'Erbalismo. Chi ha l'Estrazione li tira fuori dai propri nodi, e uno dei due cade anche dagli animali con la Scuoiatura. Diverse guide lasciano intendere il contrario.",
	PROFACAD_CH_GOLD_TASK = "Prima del tuo prossimo craft, controlla quanto costano i suoi materiali — e solo dopo decidi se craftarlo.",
	PROFACAD_CH_WORKORDERS_TITLE = "Ordini d'Artigianato: comprare la maestria di qualcun altro",
	PROFACAD_CH_WORKORDERS_INTRO = "Alla Casa d'Aste compri cose che esistono già. Al tavolo degli ordini funziona al contrario: porti tu i materiali e paghi qualcuno per il lavoro.",
	PROFACAD_CH_WORKORDERS_ADVANCED = "Due cose che fanno sembrare rotto il sistema quando non lo è. Al tuo banco da lavoro la lista degli ordini pubblici resta vuota finché non premi |cffffffffCerca|r — non c'è niente che non va, semplicemente non si carica da sola. E l'uomo in piedi al tavolo degli ordini, il Capitano Brillovoto, non c'entra affatto: lui dà la quest introduttiva della tua professione, le tue quest settimanali e sacchetti di materiali gratis. Utile, ma non è quello per cui sei venuto.",
	PROFACAD_CH_WORKORDERS_BODY = "Funziona così perché il miglior equipaggiamento craftato si lega a una sola persona nell'istante in cui esiste. Nessuno può farlo in anticipo e metterlo sullo scaffale, quindi qualcuno deve farlo |cffffffffapposta per te|r.\n\n|cffffcc00Ci sono due sportelli, ed è qui che di solito si sbaglia.|r Per farti fare qualcosa, vai al tavolo degli ordini nel Bazar di Lunargenta — il grande martello dorato sulla minimappa. La persona che ti serve è Mar'nah. Per craftare qualcosa per qualcun altro, vai invece al |cffffffffbanco da lavoro della tua professione|r. Se non ci sei accanto non c'è nessun pulsante e nessuna lista, e sembra che il sistema non esista. È l'errore più comune, e il gioco non lo spiega da nessuna parte.\n\n|cffffcc00Farsi fare qualcosa.|r Scegli l'oggetto, poi scegli a chi lo chiedi. A nessuno in particolare (il pulsante dice Ordine pubblico): tutti sul tuo reame lo vedono e il primo che lo prende lo crafta. Veloce, ma prendi quel che viene — |cffffffffqui non puoi pretendere una qualità|r, e ogni materiale devi mandarlo tu. A un giocatore preciso (Ordine Personale): lì puoi impostare una qualità minima, e puoi accordarti perché ci metta materiali suoi. A tutta la tua gilda (Ordine di Gilda) funziona allo stesso modo e raggiunge i compagni di gilda su altri reami. Il pagamento lo stabilisci tu, e un pulsante lì accanto mostra quanto hanno pagato altri di recente per lo stesso oggetto.\n\nTre cose da sapere prima di cliccare su ordina. Alcuni reagenti speciali l'artigiano non può mai procurarli, quindi quelli li mandi sempre tu. I materiali nella tua Banca della Brigata |cffffffffnon contano|r — mettili nelle borse. E l'oggetto si lega a |cffffffffte|r, quindi ordina con il personaggio che lo indosserà, non con quello che ha l'oro. Quando qualcuno prende l'ordine non puoi più annullarlo; l'oggetto arriva per posta.\n\n|cffffcc00Craftare per gli altri.|r Al tuo banco da lavoro vedi quanto guadagnerai prima ancora di iniziare. Una volta iniziato hai |cffffffff30 minuti|r per finire — abbastanza per andare a prendere qualcosa, non abbastanza per andare a mangiare.\n\nNon puoi prendere ordini pubblici all'infinito: ne tieni |cffffffff quattro|r, e |cffffffffne torna uno al giorno|r. Quindi circa sette a settimana, non quattro al giorno. Gli ordini quasi scaduti si prendono gratis.\n\nSe un ordine ti rifiuta è per una di queste quattro cose: non conosci la ricetta, la tua specializzazione non è abbastanza avanti per gli extra che chiede, vuole una qualità che non raggiungi, oppure il tuo credito è esaurito.\n\nE una che ti costa soldi in silenzio: |cffffffffcontrolla di chi sono i materiali che stai usando.|r Sugli ordini pubblici il cliente fornisce sempre tutto, ma sugli altri tipi può non fornire niente — e allora stai craftando allegramente con le tue scorte costose per una mancia.",
	PROFACAD_CH_WORKORDERS_TASK = "Trova il tavolo degli ordini nel Bazar di Lunargenta, poi trova il banco da lavoro della tua professione. Non sono lo stesso posto.",
	PROFACAD_CH_PATRON_TITLE = "Ordini dalla tab Cliente, il tuo motore settimanale di Conoscenza",
	PROFACAD_CH_PATRON_INTRO = "Il quarto tipo di ordine viene dal gioco stesso invece che da un giocatore, ed è quello che la maggior parte delle persone non trova mai.",
	PROFACAD_CH_PATRON_BODY = "Al tuo banco da lavoro c'è una tab |cffffffffCliente|r dove è il gioco a darti gli ordini. Nessun altro giocatore, nessuna concorrenza — sono soltanto tuoi. Quello che ti pagano non è tanto oro quanto |cffffffffConoscenza|r: gli stessi punti che rendono più forte la tua professione.\n\nQuesta è di gran lunga la tua fonte settimanale più grande. Saltala e resti indietro senza mai capire perché gli altri vanno più veloci.\n\nOgni pochi giorni arriva un nuovo lotto. Ogni ordine chiede una certa qualità, e a volte i materiali devi metterceli tu — controlla, perché un ordine costoso per due punti non sempre ne vale la pena. Saltarne uno è permesso.\n\n|cffffcc00E adesso la trappola.|r Il gioco ti dà anche un piccolo ordine da un punto ogni giorno, ma |cffffffffsolo finché sei indietro rispetto al tuo obiettivo settimanale|r. Fai tutti gli ordini grossi di lunedì e sei in pari — così i piccoli ordini giornalieri si fermano per il resto della settimana.\n\nQuindi: |cfffffffflascia stare gli ordini grossi finché non sono vicini alla scadenza|r. Intanto continui a ricevere i piccoli, e chiudi la settimana con più punti di quanti ne avresti avuti. Sembra sbagliato. È vero lo stesso.",
	PROFACAD_CH_PATRON_TASK = "Apri la tab Cliente al tuo banco da lavoro e guarda cosa offre questa settimana.",
	PROFACAD_CH_ALCHEMY_BODY = "L'Alchimia ti offre un albero a competenza 25, 50, 60 e 75 — non sceglie il gioco, scegli tu. I quattro sono Perizia nelle Pozioni (pozioni, con un lato Luce e un lato Vuoto), Arte dei Tonici, Autorità della Trasmutazione e Maestria Alchemica.\n\n|cffffcc00Build iniziale, in quest'ordine.|r Prima |cffffffffPerizia nelle Pozioni|r: riempirla dà il Calderone di Pozioni di Lucevuota, che serve al tuo oro e alla tua gilda nello stesso momento. Poi |cffffffffSentiero di Luce|r e |cffffffffPozioni Prolifiche - Luce|r, che è il nodo della Creazione multipla — Luce perché è quella la pozione che vende questa stagione. Poi |cffffffffMaestria Alchemica|r e al suo interno |cffffffffReuse|r, che ti restituisce erbe ed è forte se le raccogli anche tu.\n\nDopodiché circa 15 punti in |cffffffffArte dei Tonici|r, che raddoppia la durata dei tuoi tonici, poi |cffffffffSpecialista dei Sin'dorei|r. |cffffffffL'Autorità della Trasmutazione|r viene per ultima, non per seconda.\n\n|cffffffffI Segreti degli Haranir non sono un ripiego.|r La tooltip del nodo finisce con \"e Calderone di Tonici dei Sin'dorei\" — senza punti lì il Calderone di Tonici dei Sin'dorei non ti viene al grado massimo. Le guide parafrasano quel nodo come \"phials only\" e tagliano proprio la mezza frase che conta.",
	PROFACAD_CH_HERBALISM_BODY = "Ogni erba compare in ogni zona, quindi non c'è nessuna scelta di zona su cui angosciarsi. L'ordine qui sotto è quello che il percorso di questo addon consiglia adesso, e ogni passo è una cosa che sblocchi invece di una distribuzione vaga.\n\n|cffffcc00Per prima cosa: circa 40 punti in Botanica.|r Vuol dire raccogliere da cavallo, ed è di gran lunga il maggior risparmio di tempo della professione — senza, scendi e risali a ogni singola pianta. I Druidi saltano questo passaggio: raccolgono già da cavallo.\n\n|cffffcc00Poi circa 20 in Pacciamatura|r, che la gente tralascia e non dovrebbe. Ti dà il Concime Infuso: un ritrovamento raro garantito alla tua prossima raccolta, e il ritrovamento raro è il Loto Notturno — l'unica erba di Midnight di qualità rara, senza un nodo tutto suo, presente in tutti e quattro i tonici e in entrambi i calderoni.\n\n|cffffcc00Poi Raccolto Abbondante|r per il lungo periodo: più erbe per nodo e più competenza, quindi qualità massima più spesso. Al suo interno ogni erba ha il proprio nodo, così puoi puntare a quella che si vende meglio sul tuo reame.\n\n|cffffcc00Lascia perdere il Sovraccarico di Midnight.|r Funziona solo sui nodi elementali, costa parecchi punti, e ne incontri troppo pochi. Vale la pena solo se stai farmando mote di proposito.\n\nQuei numeri di punti vengono ciascuno da una fonte sola. Passa il mouse sul nodo nel gioco prima di cliccare — la tooltip ha il numero vero, e hai un solo reset.",
	PROFNEXT_UNSPENT_LOCKED_FMT = "%s: %d Conoscenza in banca, e non c'è ancora niente che possa riceverla - nessuna specializzazione è sbloccabile, quindi alza prima la competenza (la prima scelta arriva a 25)",
	SMC_PIN_NEAREST_FP = "Punta la freccia verso il maestro di volo più vicino a dove ti trovi, non solo in questa città. Disponibile anche come /mh fp.",
	FP_NEAREST_SET_FMT = "Freccia impostata sul maestro di volo più vicino: %s.",
	FP_NEAREST_NO_MAP = "Non riesco a capire dove ti trovi adesso, quindi non posso scegliere un maestro di volo.",
	FP_NEAREST_NONE = "Per questa zona non ci sono ancora punti volo registrati.",
	FP_NEAREST_NONE_FACTION = "Questa zona ha punti volo, ma nessuno utilizzabile dalla tua fazione.",
	FP_NEAREST_NO_WAYPOINT = "Non è stato possibile impostare un waypoint lì.",
	SMC_PIN_FLIGHTMASTER = "Lunargenta ha due maestri di volo, quindi la domanda utile è quale sia più vicino. Prendono entrambi le stesse rotte.",
})

