fill("deDE", {
	PROFACAD_ADVISE_NODE_FINISH_FMT = "Darüber hinaus gibt es keine geprüfte nächste Wahl. Deine bisherigen Punkte sind in %s (%d/%d) gegangen.",
	PROFACAD_ADVISE_NODE_FMT = "Tipp: steck deine nächsten Punkte in %s (%d/%d).",
	PROFACAD_ADVISE_LOCKED = "Noch kann keine Spezialisierung Punkte aufnehmen, also gibt es nichts zu raten. Steigere zuerst die Fertigkeit — die erste Wahl öffnet bei 25. Dein Wissen bleibt bis dahin erhalten; nichts davon verfällt.",
	PROFACAD_ADVISE_SEE_COURSE = "Öffne oben Kurs (101): dort steht, welcher Zweig es ist und warum.",
	PROFACAD_BTN_GLAMOUR = "Route zu Jennara Sonnenglanz (+24 Wissen)",
	PROFACAD_CH_ALCHEMY_INTRO = "Alchemie stellt die Tränke und Fläschchen her, die vor jedem Boss getrunken werden — Nachfrage gibt es also immer. Dein erster Schritt ist schlicht: weiterbrauen, während deine Fertigkeit steigt.",
	PROFACAD_CH_BLACKSMITHING_INTRO = "Plattenträger holen sich hier ihre Ausrüstung, und alle anderen kommen wegen Steinen und Werkzeugen. Dein erster Schritt: Zieh die Fertigkeit an den billigen Gegenständen hoch, bevor du überhaupt Wissen ausgibst.",
	PROFACAD_CH_ENCHANTING_ADVANCED = "Über den Starter Build hinaus? Sobald diese drei Wurzeln stehen, gibt es keinen einzig richtigen nächsten Knoten - es hängt davon ab, was der Beruf für dich tun soll. Punkte im Waffen/Ring/Brust-Zweig kaufen dir die Verzauberungen, nach denen tatsächlich gefragt wird. Punkte in Entzauberungsentsandter heißen, dass du weniger Material selbst kaufen musst. Mehr Punkte in Zauberzerschmetterer verstärken den Buff Essenz zertrümmern, sodass alles, was du herstellst, ein Stück besser wird. Was du auch wählst: gib sie aus. Ungenutztes Wissen bringt überhaupt nichts, und keine dieser Wahlen ist falsch genug, um dafür Punkte zu sparen.",
	PROFACAD_CH_ENCHANTING_INTRO = "Verzauberkunst setzt dauerhafte Werte auf deine Ausrüstung, und sie ist der einzige Beruf, der ungewollte Beute in Fortschritt verwandelt. Entzaubern heißt schlicht: einen grünen oder blauen Gegenstand für Materialien zerlegen. Dein erster Schritt: Entzaubere den Kram in deinen Taschen. Die Reihenfolge unten ist für später, wenn du dich sicher fühlst.",
	PROFACAD_CH_ENGINEERING_INTRO = "Ingenieurskunst ist der schräge, spaßige Beruf: Gadgets, Schusswaffen und Schutzbrillen, die nur du tragen kannst. Erwarte eher Nutzen und Kuriosität als rohe Kraft.",
	PROFACAD_CH_GEARUP_INTRO = "Berufe sind nach Erweiterung getrennt, deshalb kann das Fenster leer wirken, obwohl es nur die falsche Ära zeigt. Schritt eins ist sicherzugehen, dass du wirklich Midnight vor dir hast.",
	PROFACAD_CH_HERBALISM_INTRO = "Sammeln ist der ruhigste Einstieg in die Berufe: keine Rezepte zu jagen, kein Baum, den du erst planen musst, einfach Dinge aufheben. Die Verbesserung, die alle wollen, ist Sammeln ohne abzusteigen.",
	PROFACAD_CH_INSCRIPTION_INTRO = "Inschriftenkunde ist die stille Nummer: Vieles, was Schreiber herstellen, landet in den Taschen anderer Spieler statt in den eigenen — und genau deshalb gibt es dafür stetige Nachfrage.",
	PROFACAD_CH_JEWELCRAFTING_INTRO = "Ringe und Halsketten sind zwei Slots, die sonst niemand herstellen kann — Juwelieren gehen die Kunden also nie aus.",
	PROFACAD_CH_KNOWLEDGE_INTRO = "Zuerst das Wichtigste: Ein Beruf hat zwei Zahlen. Die Fertigkeit steigt allein vom Herstellen. Wissen ist die Zahl, auf die es ankommt — es ist begrenzt, kommt meist wöchentlich, und es entscheidet, was du herstellen kannst. In diesem Kapitel geht es um die zweite.",
	PROFACAD_CH_LEATHERWORKING_INTRO = "Lederverarbeitung deckt zwei Rüstungsarten auf einmal ab, deshalb hat sie zwei Bäume. Entscheide früh, welche du tatsächlich trägst, damit dein Wissen auf die richtige Seite geht.",
	PROFACAD_CH_MINING_INTRO = "Bergbau versorgt Schmiedekunst, Juwelierskunst und Ingenieurskunst, verdient also auch dann, wenn du selbst nie etwas herstellst. Erstes Ziel: Sammeln ohne abzusteigen.",
	PROFACAD_CH_MOXIE_INTRO = "Jeder Beruf hat seine eigene Währung, und sie kauft nur Dinge für diesen Beruf. Gut zu wissen, bevor du mit der falschen einkaufen gehst.",
	PROFACAD_CH_RECIPES_INTRO = "Nicht zu wissen, woher Rezepte kommen, ist der häufigste Grund, warum sich ein Beruf festgefahren anfühlt. Es gibt fünf Quellen, und nur eine davon ist dein Lehrer.",
	PROFACAD_CH_SKINNING_INTRO = "Kürschnerei macht aus dem, was du ohnehin getötet hast, Material. Sie passt natürlich zur Lederverarbeitung, verdient aber auch ganz allein bestens.",
	PROFACAD_CH_TAILORING_INTRO = "Wenn du Stoff trägst, stellt die Schneiderei deine Ausrüstung her — und den Stoff, den jeder andere Handwerker braucht. Dein erster Schritt: den Stoff aufheben, an dem du längst vorbeiläufst.",
	PROFACAD_CH_TREES_INTRO = "In deinen Spezialisierungsbaum geht dein Wissen. Denk an einen Talentbaum für dein Handwerk: Was du hineinsteckst, entscheidet, was du herstellen kannst — und wie gut.",
	PROFACAD_CH_WEEKLY_INTRO = "Das meiste Wissen kommt jede Woche zurück, was heißt: Eine verpasste Woche ist endgültig weg. Das ist die Routine, aus der sich eine Gewohnheit zu machen lohnt.",
	PROFACAD_WAYPOINT_GLAMOUR = "Jennara Sonnenglanz - Freudenzauber, oberstes Stockwerk",
	PROFGUIDE_SUB_DAWNCREST = "Wappen",
	PROFHUB_GOAL_ALLROUND = "Ausgewogen",
	PROFHUB_WEEKLY_ESSENCE_NOTE_FMT = "(die ersten %d pro Woche geben Wissen)",
	PROFHUB_WEEKLY_ESSENCE_NOTE_ONE = "(das erste pro Woche gibt Wissen)",
	PROFNEXT_NONE = "Bei deinen Berufen wartet nichts.",
	PROFNEXT_PANEL_TITLE = "Berufe",
	PROFNEXT_UNSPENT_FMT = "%s: %d Wissen nicht ausgegeben - gib es aus",
	PROFNEXT_WEEKLY_DONE_FMT = "%s: Lehrer-Wochenquest diese Woche erledigt",
	PROFNEXT_WEEKLY_PICKED_FMT = "%s: Lehrer-Wochenquest angenommen - gib es ab",
	PROFNEXT_WEEKLY_TODO_FMT = "%s: Lehrer-Wochenquest noch nicht abgeholt",
})

fill("frFR", {
	PROFACAD_ADVISE_NODE_FINISH_FMT = "Pas de suite vérifiée au-delà. Jusqu'ici, tes points sont allés dans %s (%d/%d).",
	PROFACAD_ADVISE_NODE_FMT = "Conseil : mets tes prochains points dans %s (%d/%d).",
	PROFACAD_ADVISE_LOCKED = "Aucune spécialisation ne peut encore recevoir de points, il n'y a donc rien à conseiller. Monte d'abord la compétence — le premier choix s'ouvre à 25. Ton Savoir reste acquis jusque-là ; rien n'est perdu.",
	PROFACAD_ADVISE_SEE_COURSE = "Ouvre Cours (101) ci-dessus : il nomme la branche et explique pourquoi.",
	PROFACAD_BTN_GLAMOUR = "Itinéraire vers Jennara Soléclat (+24 points de connaissance)",
	PROFACAD_CH_ALCHEMY_INTRO = "L'Alchimie fabrique les potions et les flacons que tout le monde boit avant chaque boss : la demande ne s'arrête jamais. Ta première étape, c'est simplement de continuer à distiller pendant que ta Compétence monte.",
	PROFACAD_CH_BLACKSMITHING_INTRO = "Les porteurs de plaques trouvent leur équipement ici, et tous les autres viennent pour les pierres et les outils. Ta première étape : monte ta Compétence sur les objets bon marché avant de dépenser le moindre point de connaissance.",
	PROFACAD_CH_ENCHANTING_ADVANCED = "Tu as dépassé le build de départ ? Une fois ces trois racines en place, il n'y a pas un seul nœud correct pour la suite — ça dépend de ce que tu veux faire de ton métier. Des points dans la branche Arme/Anneau/Torse t'achètent les enchantements que les gens demandent vraiment. Des points dans Délégation désenchantée, c'est moins de matériaux à acheter toi-même. Plus de points dans Fracassement envoûté renforcent le buff Fragmentation d'essence, donc tout ce que tu fabriques sort un peu meilleur. Quel que soit ton choix, dépense-les : de la connaissance qui dort ne fait absolument rien, et aucune de ces options n'est un assez mauvais choix pour valoir la peine de garder tes points.",
	PROFACAD_CH_ENCHANTING_INTRO = "L'Enchantement ajoute des stats permanentes à ton équipement, et c'est le seul métier qui transforme le butin dont tu ne veux pas en progression. Désenchanter, c'est simplement détruire un objet vert ou bleu pour en récupérer des matériaux. Ta première étape : désenchante ce qui traîne dans tes sacs. L'ordre de build ci-dessous, c'est pour quand tu seras à l'aise.",
	PROFACAD_CH_ENGINEERING_INTRO = "L'Ingénierie est le métier bizarre et amusant : gadgets, armes à feu et lunettes que toi seul peux porter. Attends-toi à de l'utilitaire et de la fantaisie plus qu'à de la puissance brute.",
	PROFACAD_CH_GEARUP_INTRO = "Les métiers sont découpés par extension : ta fenêtre peut sembler vide alors qu'elle affiche simplement la mauvaise époque. Première étape : vérifie que tu regardes bien Midnight.",
	PROFACAD_CH_HERBALISM_INTRO = "La récolte est la façon la plus tranquille d'entrer dans les métiers : pas de recettes à chasser, pas d'arbre à planifier d'abord, tu ramasses et c'est tout. L'amélioration que tout le monde veut, c'est récolter sans descendre de monture.",
	PROFACAD_CH_INSCRIPTION_INTRO = "La Calligraphie est la discrète : une grande partie de ce que fabriquent les calligraphes finit entre les mains d'autres joueurs plutôt que dans leurs propres sacs, et c'est justement pour ça que la demande ne faiblit pas.",
	PROFACAD_CH_JEWELCRAFTING_INTRO = "Anneaux et colliers sont deux emplacements que personne d'autre ne peut fabriquer : les joailliers ne manquent jamais de clients.",
	PROFACAD_CH_KNOWLEDGE_INTRO = "Avant tout le reste : un métier a deux chiffres. La Compétence monte rien qu'en fabriquant. La connaissance, c'est celle qui compte — elle est limitée, surtout hebdomadaire, et c'est elle qui décide de ce que tu peux fabriquer. Ce chapitre parle de la seconde.",
	PROFACAD_CH_LEATHERWORKING_INTRO = "Le Travail du cuir couvre deux types d'armure à la fois, et c'est pour ça qu'il a deux arbres. Décide tôt lequel tu portes vraiment, pour que ta connaissance parte du bon côté.",
	PROFACAD_CH_MINING_INTRO = "Le Minage alimente la Forge, la Joaillerie et l'Ingénierie : il rapporte même si tu ne fabriques jamais rien toi-même. Premier objectif : récolter sans descendre de monture.",
	PROFACAD_CH_MOXIE_INTRO = "Chaque métier a sa propre monnaie, et elle n'achète que des choses de ce métier-là. Bon à savoir avant d'aller faire tes courses avec la mauvaise.",
	PROFACAD_CH_RECIPES_INTRO = "Ne pas savoir d'où viennent les recettes est la raison la plus courante pour laquelle un métier semble bloqué. Il y a cinq sources, et une seule est ton formateur.",
	PROFACAD_CH_SKINNING_INTRO = "Le Dépeçage transforme en matériaux ce que tu tuais de toute façon. Il se marie naturellement avec le Travail du cuir, mais il rapporte très bien tout seul.",
	PROFACAD_CH_TAILORING_INTRO = "Si tu portes du tissu, la Couture fabrique ton équipement — et le tissu dont tous les autres artisans ont besoin. Ta première étape : ramasse le tissu devant lequel tu passes déjà.",
	PROFACAD_CH_TREES_INTRO = "Ton arbre de spécialisation, c'est là que va la connaissance. Vois-le comme un arbre de talents pour ton métier : ce que tu y mets décide de ce que tu peux fabriquer, et à quel point c'est réussi.",
	PROFACAD_CH_WEEKLY_INTRO = "L'essentiel de la connaissance revient chaque semaine, ce qui veut dire qu'une semaine ratée est perdue pour de bon. Voici la routine dont il vaut la peine de faire une habitude.",
	PROFACAD_WAYPOINT_GLAMOUR = "Jennara Soléclat - Glamours enjoués, dernier étage",
	PROFGUIDE_SUB_DAWNCREST = "Écus",
	PROFHUB_WEEKLY_ESSENCE_NOTE_FMT = "(les %d premiers de chaque semaine donnent de la connaissance)",
	PROFHUB_WEEKLY_ESSENCE_NOTE_ONE = "(le premier de chaque semaine donne de la connaissance)",
	PROFNEXT_NONE = "Rien en attente sur tes métiers.",
	PROFNEXT_PANEL_TITLE = "Métiers",
	PROFNEXT_UNSPENT_FMT = "%s : %d points de connaissance non dépensés - dépense-les",
	PROFNEXT_WEEKLY_DONE_FMT = "%s : quête hebdo du formateur faite cette semaine",
	PROFNEXT_WEEKLY_PICKED_FMT = "%s : quête hebdo du formateur prise - rends-la",
	PROFNEXT_WEEKLY_TODO_FMT = "%s : quête hebdo du formateur pas encore prise",
})

fill("esES", {
	PROFACAD_ADVISE_NODE_FINISH_FMT = "Más allá de esto no hay una siguiente elección verificada. Tus puntos hasta ahora han ido a %s (%d/%d).",
	PROFACAD_ADVISE_NODE_FMT = "Consejo: mete tus próximos puntos en %s (%d/%d).",
	PROFACAD_ADVISE_LOCKED = "Todavía ninguna especialización puede recibir puntos, así que no hay nada que aconsejar. Sube primero la habilidad: la primera elección se abre a 25. Tu Conocimiento se conserva hasta entonces; no se pierde nada.",
	PROFACAD_ADVISE_SEE_COURSE = "Abre arriba Curso (101): ahí se nombra la rama y se explica por qué.",
	PROFACAD_BTN_GLAMOUR = "Ruta a Jennara Brillosol (+24 de conocimiento)",
	PROFACAD_CH_ALCHEMY_INTRO = "La Alquimia hace las pociones y los frascos que todo el mundo bebe antes de cada jefe, así que siempre hay demanda. Tu primer paso es sencillamente seguir fabricando mientras sube tu habilidad.",
	PROFACAD_CH_BLACKSMITHING_INTRO = "Quien lleva placas consigue aquí su equipo, y el resto viene por piedras y herramientas. Tu primer paso: sube habilidad con los objetos baratos antes de gastar nada de conocimiento.",
	PROFACAD_CH_ENCHANTING_ADVANCED = "¿Ya has pasado de la build inicial? Una vez metidas esas tres raíces no hay un único nodo siguiente correcto: depende de lo que quieras que haga la profesión. Los puntos en la rama de arma, anillo y torso compran los encantamientos que la gente pide de verdad. Los puntos en Delegación de desencantamientos significan comprar menos materiales tú. Más puntos en Destrucción de vínculos suben la mejora Esencia destrozada, así que todo lo que fabricas sale un poco mejor. Elijas lo que elijas, gástalos: el conocimiento sin gastar no hace absolutamente nada, y ninguna de estas opciones es lo bastante mala como para merecer guardar puntos.",
	PROFACAD_CH_ENCHANTING_INTRO = "El Encantamiento añade estadísticas permanentes a tu equipo, y es la única profesión que convierte el botín que no quieres en progreso. Desencantar no es más que destruir un objeto verde o azul para sacar materiales. Tu primer paso: desencanta lo que te sobra en las bolsas. El orden de puntos de abajo es para cuando ya te manejes con soltura.",
	PROFACAD_CH_ENGINEERING_INTRO = "La Ingeniería es la rara y divertida: artilugios, armas de fuego y gafas que solo puedes llevar tú. Espera utilidad y novedad más que potencia pura.",
	PROFACAD_CH_GEARUP_INTRO = "Las profesiones están separadas por expansión, así que la ventana puede parecer vacía cuando en realidad solo está mostrando la época equivocada. El primer paso es asegurarte de que estás mirando Midnight.",
	PROFACAD_CH_HERBALISM_INTRO = "Recolectar es la forma más tranquila de entrar en las profesiones: no hay recetas que perseguir ni árbol que planear antes, solo recoger cosas. La mejora que quiere todo el mundo es recolectar sin bajarte de la montura.",
	PROFACAD_CH_INSCRIPTION_INTRO = "La Inscripción es la discreta: mucho de lo que hacen los escribas acaba en manos de otros jugadores en vez de en sus propias bolsas, y justo por eso tiene una demanda constante.",
	PROFACAD_CH_JEWELCRAFTING_INTRO = "Los anillos y los collares son dos ranuras que nadie más puede fabricar, así que a los joyeros nunca les faltan compradores.",
	PROFACAD_CH_KNOWLEDGE_INTRO = "Antes que nada: una profesión tiene dos números. La habilidad sube solo con fabricar. El conocimiento es el que importa — es limitado, casi todo semanal, y decide lo que puedes hacer. Este capítulo va del segundo.",
	PROFACAD_CH_LEATHERWORKING_INTRO = "La Peletería cubre dos tipos de armadura a la vez, y por eso tiene dos árboles. Decide pronto cuál llevas de verdad, para que tu conocimiento vaya al lado correcto.",
	PROFACAD_CH_MINING_INTRO = "La Minería alimenta la Herrería, la Joyería y la Ingeniería, así que da dinero aunque tú no fabriques nunca nada. Primer objetivo: recolectar sin bajarte de la montura.",
	PROFACAD_CH_MOXIE_INTRO = "Cada profesión tiene su propia moneda, y solo compra cosas de esa profesión. Conviene saberlo antes de ir de compras con la equivocada.",
	PROFACAD_CH_RECIPES_INTRO = "No saber de dónde salen las recetas es la razón más común de que una profesión parezca atascada. Hay cinco fuentes, y solo una de ellas es tu instructor.",
	PROFACAD_CH_SKINNING_INTRO = "El Desuello convierte en materiales cosas que ibas a matar de todos modos. Combina de forma natural con la Peletería, pero por sí solo también da dinero de sobra.",
	PROFACAD_CH_TAILORING_INTRO = "Si llevas tela, la Sastrería hace tu equipo — y la tela que necesitan todos los demás fabricantes. Tu primer paso es recoger la tela por la que ya pasas de largo.",
