--========================================================================
-- Codex vertaald (23 aug)
-- Nieuwe vertalingen voor het naslagdeel; deze sleutels stonden in deze
-- vijf packs nog volledig in het Engels. De namen erin komen uit de
-- termenlijst die per taal is opgezocht (wave 1 en 2), niet uit de oude
-- regel dat eigennamen Engels blijven. Waar geen naam opgezocht was,
-- staat het Engels er nog -- dat is een gat in de lijst, geen keuze.
--========================================================================

fill("deDE", {
	CODEX_127_RITUALRENOWN_TITLE = "Ritualstätten-Renown (12.0.7)",
	CODEX_ACCOUNT_TITLE = "Account-Snapshot",
	CODEX_CAT_COILEDISLE = "Die Gewundene Insel",
	CODEX_CAT_CURRENCIES = "Währungen",
	CODEX_CAT_PROFESSIONS = "Berufe",
	CODEX_CAT_WORLD = "Weltinhalte",
	CODEX_CRAFTGEAR_BODY = "• Du brauchst den Beruf nicht selbst — ein anderer Spieler kann es über eine |cffffffffCrafting Order|r für dich herstellen.|n• Hergestellte Ausrüstung ist der |cffffffffverlässliche|r Weg: kein Glück mit Drops nötig. Sie ist außerdem die einzige Ausrüstung, die ein |cffffffffEmbellishment|r tragen kann (ein Sondereffekt — du trägst höchstens zwei).|n• |cffffffffWas du zuerst besorgst:|r einen |cffffffffSpark|r (2 für ein Rüstungsteil oder eine Einhandwaffe, 4 für eine Zweihandwaffe) aus der Wochenquest in Silbermond; |cffffffffWappen|r, wenn du die höhere Version willst; ein |cffffffffMissive|r, um deine Sekundärwerte zu wählen (Auktionshaus); und die Materialien.|n• |cffffffffDer Schritt mit den Wappen entscheidet:|r ohne Wappen bekommst du die Basisversion. Legst du Wappen einer höheren Tier dazu, steigt die Gegenstandsstufe, die das Teil erreichen kann — die Wappen der höchsten Tier ergeben die stärkste Herstellung. Dein eigener Wappen-Tab zeigt dir, was du hast.|n• |cffffffffDann bestellst du:|r Sprich mit dem Crafting-Orders-NPC im Basar von Silbermond, wähle den Gegenstand, häng deinen Spark, deine Wappen und dein Missive an und stell ihn als Public Order ein oder schick ihn an einen Hersteller, den du kennst. Leg ein Trinkgeld dazu, damit ihn auch jemand annimmt.|n• |cffffffffSparks und Wappen kann der Hersteller nicht beisteuern|r — die musst du selbst besitzen. Genau daran scheitern die meisten ersten Bestellungen.|n• Das Können des Herstellers entscheidet über die Qualität, ein Hersteller, den du kennst, ist also besser als eine zufällige Public Order.|n• Lohnt sich, wenn in einem Slot einfach nichts droppen will, oder für ein Embellishment. Fallen dir in dem Slot leicht gute Drops zu, spar dir die Wappen.",
	CODEX_CRAFTGEAR_TITLE = "Ausrüstung herstellen lassen",
	CODEX_CUR_ACCOLADES_TITLE = "Feldauszeichnungen",
	CODEX_CUR_DAWN_TITLE = "Wappen",
	CODEX_DELVER_CALL_TITLE = "Ruf des Tiefenforschers",
	CODEX_DELVE_COACH_TITLE = "Delve-Coach",
	CODEX_DELVE_LOG_TITLE = "Delve-Log",
	CODEX_FOLIO_TITLE = "Omniumfoliant (12.0.7)",
	CODEX_PREY_BODY = "• |cffffffffEine Beutejagd ist ein verfolgter Abschuss, kein Dungeon.|r Du nimmst die Jagd bei Magister Astalor Bloodsworn in Murder Row, Silbermond, an, folgst ihr und schließt sie mit einem Kampf gegen ein einzelnes benanntes Ziel ab. Keine Gruppensuche, keine Sperre, um die du herumplanen müsstest.|n• |cffffffffSie zählt für die Great Vault.|r Beute speist dieselbe Weltzeile wie Delves und Ritualstätten, ist also ein echter Weg, diesen Belohnungsplatz zu füllen, und keine Nebensache.|n• |cffffffffEs gibt drei Schwierigkeitsmodi.|r Fang mit dem niedrigsten an. Ein schwererer Modus ist dieselbe Jagd mit mehr zu bewältigen, kein anderer Inhalt, den du sonst verpassen würdest.|n• |cffffffffJagden im War Mode werden getrennt gezählt.|r Spielst du ohne War Mode, entgeht dir nichts, was der Rest des Systems braucht.|n• |cffffffffDie ganze Zielliste ist ein Langzeitziel, keine Wochenpflicht.|r Wer sie durcharbeitet, bekommt am Ende einen Titel. Eine einzelne Jagd zu machen, wenn dir danach ist, ist eine völlig gute Art, das zu spielen.|n• |cffffffffSie öffnet außerdem ein Portal, und das ist der Teil, den dir niemand sagt.|r Steig in die Beute-Reihe ein, und ein Portal verbindet Astalor's Sanctum in Silbermond direkt mit dem Ziel: Die Gewundene Insel. Das spart dir bei jeder einzelnen Reise den langen Flug. Midnight Helper bietet es in der Routenführung erst an, wenn dein eigener Charakter es wirklich nutzen kann — siehst du es also noch nicht, mach mit Beute einfach weiter.|n• |cffffffffHier fängst du an|r: {WAY:2393:56.74:67.30:Magister Astalor Bloodsworn} in Murder Row, Silbermond. Klick darauf, um einen Wegpunkt zu setzen. Das Portal steht neben ihm, und der City Guide hat ebenfalls einen Pin dafür.|n• |cffffffffUnd der Weg zurück|r, die Hälfte, die niemand aufschreibt: {WAY:2512:58.12:48.48:Portal to Silvermoon} auf der Gewundenen Insel. Auf der Insel zu stehen und keine Ahnung zu haben, wo das Rückportal ist, passiert jedem einmal.|n• |cffffffffUm zu sehen, wo du stehst|r, tippe |cffffffff/mh prey|r, oder öffne den Abenteuerführer mit Shift-J. Beides liest deinen eigenen Fortschritt aus dem Spiel und nicht aus einer Liste, die wir aufgeschrieben haben.",
	CODEX_RITUAL_TITLE = "Ritualstätten",
	CODEX_S2GLOSS_BODY = "• |cffffffffWappen|r — eine Währung, um Ausrüstung aufzuwerten. Jede Track (Abenteurer bis Mythisch) hat ihr eigenes Wappen; du verdienst sie in Delves, Dungeons und Raids.|n• |cffffffffAufwertungs-Track|r — die Leiter, die ein Ausrüstungsteil erklimmt (Abenteurer, Veteran, Champion, Held, Mythisch). Höhere Track = höhere Obergrenze.|n• |cffffffffTier-Set|r — zusammengehörige Rüstungsteile. Trag 2 oder 4 davon, und du schaltest einen Bonus für deine Spezialisierung frei.|n• |cffffffffKatalysator|r — verwandelt ein normales Teil in ein Tier-Teil; in Saison 2 bleiben die Werte des Gegenstands dabei erhalten.|n• |cffffffffBountiful Delve|r — ein Delve mit einer garantierten Extra-Belohnung; braucht einen Coffer Key.|n• |cffffffffNemesis Delve|r — ein besonderer Saison-Delve mit eigenem Boss und eigenen Belohnungen.|n• |cffffffffLair|r — ein Weltboss, den du an einem festen Ort betrittst und für den du eine Schwierigkeit für deine Gruppe wählst, wie ein Mini-Raid.|n• |cffffffffNeuskalierung zum Saisonstart (Squish)|r — neue Ausrüstung beginnt bei höheren Zahlen, dadurch wirkt alte Ausrüstung niedriger. Jede Saison normal; alle setzen gemeinsam zurück.",
	CODEX_S2GLOSS_TITLE = "Saison 2 — neue Begriffe",
	CODEX_S2_BODY = "• Dein Charakter, deine Reittiere und deine Sammlungen bleiben alle — nichts geht verloren.|n• Ausrüstung wirkt \"niedriger\", weil die neue Saison auf einer höheren Skala beginnt. Das ist normal und so gewollt — alle setzen gemeinsam zurück.|n• Auch deine Mythic+-Wertung beginnt neu — auch das gilt für alle.|n• Es kommt in zwei Schritten: zuerst der Patch (Zone, Kampagne, Dungeon), etwa eine Woche später die Saison (Raid, Mythic+, PvP).|n• Was jetzt zu tun ist: folge dem Pfad Erste Schritte, ganz ohne Eile.",
	CODEX_S2_TITLE = "Eine neue Saison — was das bedeutet",
	CODEX_SEASONEND_BODY = "• |cffffffffDeine Ausrüstung wird nicht zurückgesetzt.|r Alles, was du trägst, kommt mit der Gegenstandsstufe mit, die es schon hat. Sie ist dann nicht mehr Spitze, aber sie ist ein echter Vorsprung am ersten Tag der nächsten Saison. Die Änderung, bei der die Zahlen bei allen auf einmal sinken, ist ein Squish, und der gehört zum Vorpatch einer Erweiterung — nicht zu einem Saisonwechsel.|n• |cffffffffDie Zahlen verschieben sich, nicht dein Fortschritt.|r Jede Saison hebt die Gegenstandsstufen an; ein Teil, das auf der höchsten Track ausgereizt ist, liegt in den neuen Zahlen also ein bis zwei Tracks tiefer. Das ist normal und passiert allen.|n• |cffffffffÖffne die Great Vault bis in die letzte Woche hinein weiter.|r Jede Wochenbelohnung ist kostenlose Ausrüstung, die anhebt, wo du nächste Saison startest.|n• |cffffffffSaisonwährungen überstehen einen Wechsel meist nicht unverändert|r — sie werden in der Regel umgewandelt oder verlieren ihren Nutzen. Ausgeben ist besser als Horten. Das genaue Verhalten unterscheidet sich je Währung und kann sich noch spät ändern; sieh also im Spiel im Währungsreiter nach, statt einem Guide zu vertrauen.|n• |cffffffffDie echte Frist sind die Dinge, die es nur in dieser Saison gibt:|r Reittiere, Titel und Erfolge, die an diese Saison gebunden sind, und Fortschrittspfade, die zurückgesetzt werden. Die lohnt es sich abzuschließen, solange du noch kannst.|n• |cffffffffFortschrittspfade werden zurückgesetzt, ihre Belohnungen sind aber meist nicht weg|r — sie wandern danach oft zu einem Händler, ohne die Rangvoraussetzung, dafür zu einem deutlich höheren Preis. Jetzt fertig zu werden ist billiger, als später zu kaufen.|n• |cffffffffEntscheide dich für eine Spur.|r Die letzten Wochen sind kurz. Einen Pfad abzuschließen ist mehr wert, als drei halb zu schaffen.",
	CODEX_SEASONEND_TITLE = "Wenn eine Saison endet",
	CODEX_TRACKS_TITLE = "Aufwertungs-Tracks der Ausrüstung",
	CODEX_VOID_TITLE = "Angriffe der Leere",
})

fill("frFR", {
	CODEX_127_FOLIO_TITLE = "Le feuillet de l'Omnium et les runes (12.0.7)",
	CODEX_ACCOUNT_TITLE = "Aperçu du compte",
	CODEX_CAT_COILEDISLE = "Île Annelée",
	CODEX_CAT_CURRENCIES = "Monnaies",
	CODEX_CAT_DELVES = "Gouffres",
	CODEX_CAT_DUNGEONS = "Donjons & M+",
	CODEX_CAT_PROFESSIONS = "Métiers",
	CODEX_CAT_WORLD = "Contenu de monde",
	CODEX_CRAFTGEAR_BODY = "• Tu n'as pas besoin du métier toi-même — un autre joueur peut te le fabriquer via une |cffffffffcommande d'artisanat|r.|n• L'équipement fabriqué est la voie |cfffffffffiable|r : aucun hasard de butin. C'est aussi le seul équipement qui peut porter un |cffffffffEmbellishment|r (un effet spécial — tu peux en porter deux au maximum).|n• |cffffffffCe que tu réunis d'abord :|r un |cffffffffSpark|r (2 pour une pièce d'armure ou une arme à une main, 4 pour une arme à deux mains) via la quête hebdomadaire de Lune-d'argent ; des |cffffffffécus|r si tu veux la version supérieure ; une |cffffffffMissive|r pour choisir tes stats secondaires (hôtel des ventes) ; et les matériaux.|n• |cffffffffL'étape des écus compte :|r sans écus, tu obtiens la version de base. Ajouter des écus d'un palier supérieur relève le niveau d'objet que la pièce peut atteindre — les écus du palier le plus haut donnent la fabrication la plus puissante. Ton propre onglet des écus montre ce que tu as.|n• |cffffffffPasse ensuite la commande :|r parle au PNJ des commandes d'artisanat dans le quartier Le Bazar, à Lune-d'argent, choisis l'objet, joins ton spark, tes écus et ta missive, puis place-la en commande publique ou envoie-la à un artisan que tu connais. Ajoute un pourboire pour que quelqu'un la prenne.|n• |cffffffffLes sparks et les écus ne peuvent pas être fournis par l'artisan|r — tu dois les posséder. C'est là que la plupart des premières commandes échouent.|n• La compétence de l'artisan décide de la qualité : un artisan que tu connais vaut mieux qu'une commande publique au hasard.|n• Ça vaut le coup quand un emplacement refuse de tomber pour toi, ou pour un Embellishment. Si de bons butins tombent facilement sur cet emplacement, garde tes écus.",
	CODEX_CRAFTGEAR_TITLE = "Faire fabriquer ton équipement",
	CODEX_CUR_ACCOLADES_TITLE = "Décorations de terrain",
	CODEX_CUR_DAWN_TITLE = "Écus",
	CODEX_DELVER_CALL_TITLE = "Appel du Gouffre",
	CODEX_DELVE_COACH_TITLE = "Coach gouffre",
	CODEX_DELVE_LOG_TITLE = "Journal des gouffres",
	CODEX_FOLIO_TITLE = "Le feuillet de l'Omnium (12.0.7)",
	CODEX_PREY_BODY = "• |cffffffffUne Traque est une mise à mort pistée, pas un donjon.|r Tu prends la chasse auprès de Magister Astalor Bloodsworn, à Murder Row, Lune-d'argent, tu la suis, et tu finis par un combat contre une seule cible nommée. Pas d'outil de recherche de groupe, pas de verrou d'instance à planifier.|n• |cffffffffÇa compte pour la Grande chambre forte.|r La Traque alimente la même rangée monde que les gouffres et les sites rituels : c'est donc une vraie façon de remplir cet emplacement de récompense, pas une attraction annexe.|n• |cffffffffIl y a trois modes de difficulté.|r Commence par le plus bas. Un mode plus dur, c'est la même chasse avec plus à gérer, pas un contenu différent que tu raterais.|n• |cffffffffLes chasses en mode Guerre sont comptées à part.|r Si tu ne joues pas avec le mode Guerre activé, tu ne rates rien de ce dont le reste du système a besoin.|n• |cffffffffLa liste complète des cibles est un objectif de longue haleine, pas une corvée hebdomadaire.|r La terminer se conclut par un titre. Faire une chasse quand l'envie te prend est une manière tout à fait valable d'y jouer.|n• |cffffffffÇa ouvre aussi un portail, et c'est la partie que personne ne te dit.|r Lance-toi dans la chaîne de Traque et un portail relie Astalor's Sanctum, à Lune-d'argent, directement à l'Île Annelée, ce qui t'épargne le long vol à chaque trajet. Midnight Helper ne le propose dans ses itinéraires qu'une fois que ton propre personnage peut vraiment l'emprunter : si tu ne le vois pas encore, continue la Traque.|n• |cffffffffCommence ici|r : {WAY:2393:56.74:67.30:Magister Astalor Bloodsworn} à Murder Row, Lune-d'argent. Clique dessus pour poser un point de route. Le portail se tient à côté de lui, et le Guide de la ville a lui aussi une broche pour ce portail.|n• |cffffffffEt le chemin du retour|r, la moitié que personne ne note : {WAY:2512:58.12:48.48:Portal to Silvermoon} sur l'Île Annelée. Se retrouver sur l'île sans savoir où est le portail de retour, ça arrive à tout le monde une fois.|n• |cffffffffPour voir où tu en es|r, tape |cffffffff/mh prey|r, ou ouvre le Guide d'aventure avec Shift-J. Les deux lisent ta propre progression dans le jeu, et non dans une liste que nous aurions écrite.",
	CODEX_RITUAL_TITLE = "Sites rituels",
	CODEX_S2GLOSS_BODY = "• |cffffffffÉcu|r — une monnaie qui sert à améliorer l'équipement. Chaque track (d'Adventurer à Myth) a son propre écu ; tu les gagnes dans les gouffres, les donjons et les raids.|n• |cffffffffTrack d'amélioration|r — l'échelle que gravit une pièce d'équipement (Adventurer, Vétéran, Champion, Hero, Myth). Track plus haute = plafond plus haut.|n• |cffffffffSet de tier|r — des pièces d'armure assorties. Portes-en 2 ou 4 et tu débloques un bonus pour ta spé.|n• |cffffffffCatalyseur|r — transforme une pièce normale en pièce de tier ; en Saison 2, il conserve les stats de l'objet.|n• |cffffffffGouffre généreux|r — un gouffre avec une récompense supplémentaire garantie ; il faut une Coffer Key.|n• |cffffffffGouffre Némésis|r — un gouffre saisonnier spécial avec son propre boss et ses propres récompenses.|n• |cffffffffLair|r — un boss de monde dans lequel tu entres à un endroit donné en choisissant une difficulté pour ton groupe, comme un mini-raid.|n• |cffffffffRééchelonnage de nouvelle saison (squish)|r — le nouvel équipement démarre sur des chiffres plus élevés, donc l'ancien paraît plus bas. C'est normal à chaque saison ; tout le monde repart en même temps.",
	CODEX_S2GLOSS_TITLE = "Saison 2 — nouveaux termes",
	CODEX_S2_BODY = "• Ton personnage, tes montures et tes collections restent — tu ne perds rien.|n• L'équipement paraît \"plus faible\" parce que la nouvelle saison démarre sur une échelle plus haute. C'est normal et prévu — tout le monde repart en même temps.|n• Ta cote Mythic+ repart de zéro elle aussi — là encore, pour tout le monde.|n• Ça arrive en deux temps : d'abord le patch (zone, campagne, donjon), puis environ une semaine plus tard la saison (raid, Mythic+, JcJ).|n• Quoi faire maintenant : suis le parcours Pour commencer, sans te presser.",
	CODEX_S2_TITLE = "Une nouvelle saison — ce que ça veut dire",
	CODEX_SEASONEND_BODY = "• |cffffffffTon équipement n'est pas réinitialisé.|r Tout ce que tu portes est conservé au niveau d'objet qu'il a déjà. Il cesse d'être au sommet, mais il te donne une vraie avance au premier jour de la saison suivante. Le changement où les chiffres de tout le monde baissent d'un coup, c'est un squish, et ça appartient au pré-patch d'une extension — pas au passage d'une saison à l'autre.|n• |cffffffffCe sont les chiffres qui bougent, pas ta progression.|r Chaque saison relève les niveaux d'objet : une pièce au maximum de la track la plus haute se retrouve une track ou deux plus bas dans les nouveaux chiffres. C'est normal et ça arrive à tout le monde.|n• |cffffffffContinue d'ouvrir la Grande chambre forte jusqu'à la dernière semaine.|r Chaque hebdomadaire, c'est de l'équipement gratuit qui relève ton point de départ pour la saison suivante.|n• |cffffffffLes monnaies saisonnières ne survivent en général pas intactes à un changement de saison|r — elles ont tendance à être converties ou à ne plus servir à rien. Mieux vaut les dépenser que les thésauriser. Le comportement exact varie d'une monnaie à l'autre et peut encore changer au dernier moment : vérifie donc l'onglet des monnaies en jeu plutôt que de te fier à un guide.|n• |cffffffffLa vraie échéance, ce sont les choses propres à la saison :|r montures, titres et hauts faits liés à cette saison, et pistes de progression qui se réinitialisent. Ce sont celles-là qui valent la peine d'être terminées tant que tu le peux encore.|n• |cffffffffLes pistes de progression se réinitialisent, mais leurs récompenses ne disparaissent en général pas|r — elles passent souvent ensuite chez un marchand, sans la condition de rang, à un prix bien plus élevé. Terminer maintenant coûte moins cher qu'acheter plus tard.|n• |cffffffffChoisis une seule voie.|r Les dernières semaines sont courtes. Terminer une piste vaut mieux qu'en faire trois à moitié.",
	CODEX_SEASONEND_TITLE = "Quand une saison se termine",
	CODEX_TRACKS_TITLE = "Tracks d'amélioration de l'équipement",
	CODEX_VOID_TITLE = "Assauts du Vide",
})

fill("esES", {
	CODEX_ACCOUNT_TITLE = "Instantánea de la cuenta",
	CODEX_CAT_COILEDISLE = "Isla Serpenteante",
	CODEX_CAT_CURRENCIES = "Monedas",
	CODEX_CAT_DUNGEONS = "Mazmorras y M+",
	CODEX_CAT_PROFESSIONS = "Profesiones",
	CODEX_CAT_WORLD = "Contenido de mundo",
	CODEX_CRAFTGEAR_BODY = "• No hace falta que tengas la profesión tú mismo: otro jugador puede fabricártelo mediante un |cffffffffCrafting Order|r.|n• El equipo fabricado es la vía |cfffffffffiable|r: no depende de la suerte del botín. Además es el único equipo que puede llevar un |cffffffffEmbellishment|r (un efecto especial; puedes llevar dos como máximo).|n• |cffffffffLo que reúnes primero:|r un |cffffffffSpark|r (2 para una pieza de armadura o un arma de una mano, 4 para un arma a dos manos) de la misión semanal de Lunargenta; |cffffffffblasones|r si quieres la versión superior; un |cffffffffMissive|r para elegir tus estadísticas secundarias (casa de subastas); y los materiales.|n• |cffffffffEl paso de los blasones importa:|r sin blasones obtienes la versión básica. Añadir blasones de un Tier superior sube el nivel de objeto que puede alcanzar: los blasones del Tier más alto dan la fabricación más fuerte. Tu propia pestaña de blasones te muestra los que tienes.|n• |cffffffffLuego haz el encargo:|r habla con el PNJ de Crafting Orders en el Bazar de Lunargenta, elige el objeto, adjunta tu Spark, tus blasones y tu Missive, y publícalo como Public Order o mándaselo a un artesano que conozcas. Añade una propina para que alguien lo coja.|n• |cffffffffLos Sparks y los blasones no los puede poner el artesano|r: tienes que tenerlos tú. Aquí es donde falla la mayoría de los primeros encargos.|n• La habilidad del artesano decide la calidad, así que un artesano conocido es mejor que un Public Order al azar.|n• Merece la pena cuando una ranura se te resiste, o para un Embellishment. Si en esa ranura te caen buenos objetos con facilidad, guárdate los blasones.",
	CODEX_CRAFTGEAR_TITLE = "Encargar equipo fabricado",
	CODEX_CUR_ACCOLADES_TITLE = "Galardones de campo",
	CODEX_CUR_DAWN_TITLE = "Blasones",
	CODEX_DELVER_CALL_TITLE = "Llamada de explorador de profundidades",
	CODEX_DELVE_COACH_TITLE = "Entrenador de profundidades",
	CODEX_DELVE_LOG_TITLE = "Registro de profundidades",
	CODEX_FOLIO_TITLE = "El folio del Omnium (12.0.7)",
	CODEX_PREY_BODY = "• |cffffffffUna cacería de Presa es una muerte con seguimiento, no una mazmorra.|r Recoges la cacería con Magister Astalor Bloodsworn, en Murder Row, Lunargenta, la sigues y la cierras con un combate contra un único objetivo con nombre. Sin buscador de grupo y sin bloqueo que planificar.|n• |cffffffffCuenta para la Great Vault.|r Presa alimenta la misma fila de mundo que los Delves y los lugares de ritual, así que es una forma real de llenar esa ranura de recompensa y no un añadido secundario.|n• |cffffffffHay tres modos de dificultad.|r Empieza por el más bajo. Un modo más difícil es la misma cacería con más cosas que manejar, no contenido distinto que te estés perdiendo.|n• |cffffffffLas cacerías con War Mode se cuentan aparte.|r Si no juegas con War Mode activado, no te pierdes nada de lo que el resto del sistema necesita.|n• |cffffffffLa lista completa de objetivos es una meta a largo plazo, no una tarea semanal.|r Terminarla acaba en un título. Hacer una cacería cuando te apetezca es una forma perfectamente válida de jugarlo.|n• |cffffffffTambién abre un portal, y esa es la parte que nadie te cuenta.|r En cuanto entras en la línea de Presa, un portal conecta Astalor's Sanctum, en Lunargenta, directamente con la Isla Serpenteante, lo que te ahorra el vuelo largo en cada viaje. Midnight Helper solo te lo ofrece en la guía de rutas cuando tu propio personaje puede usarlo de verdad, así que si aún no lo ves, sigue con Presa.|n• |cffffffffEmpieza aquí|r: {WAY:2393:56.74:67.30:Magister Astalor Bloodsworn} en Murder Row, Lunargenta. Haz clic ahí para poner un punto de ruta. El portal está a su lado, y la Guía de la ciudad también tiene un pin para él.|n• |cffffffffY la vuelta|r, que es la mitad que nadie escribe: {WAY:2512:58.12:48.48:Portal a Lunargenta} en la Isla Serpenteante. Estar en la isla sin saber dónde está el portal de vuelta le pasa a todo el mundo una vez.|n• |cffffffffPara ver cómo vas|r, escribe |cffffffff/mh prey|r, o abre la Guía de aventuras con Mayús-J. Los dos leen tu progreso desde el juego y no de una lista escrita por nosotros.",
	CODEX_RITUAL_TITLE = "Lugares de ritual",
	CODEX_S2GLOSS_BODY = "• |cffffffffBlasón|r — una moneda para mejorar el equipo. Cada vía (de Aventurero a Mito) tiene su propio blasón; los consigues en Delves, mazmorras y Raids.|n• |cffffffffVía de mejora|r — la escalera por la que sube una pieza de equipo (Aventurero, Veterano, Campeón, Héroe, Mito). Vía más alta = techo más alto.|n• |cffffffffTier set|r — piezas de armadura que hacen juego. Lleva 2 o 4 y desbloqueas una bonificación para tu especialización.|n• |cffffffffCatalizador|r — convierte una pieza normal en una pieza de Tier; en la Temporada 2 conserva las estadísticas del objeto.|n• |cffffffffBountiful Delve|r — un Delve con una recompensa extra garantizada; necesita una Coffer Key.|n• |cffffffffNemesis Delve|r — un Delve de temporada especial con su propio jefe y sus propias recompensas.|n• |cffffffffLair|r — un jefe de mundo en el que entras desde un punto concreto y para el que eliges una dificultad para tu grupo, como una mini-Raid.|n• |cffffffffReescalado de temporada nueva (squish)|r — el equipo nuevo empieza con números más altos, así que el antiguo parece más bajo. Es normal cada temporada; todo el mundo se reinicia a la vez.",
	CODEX_S2GLOSS_TITLE = "Temporada 2 — términos nuevos",
	CODEX_S2_BODY = "• Tu personaje, tus monturas y tus colecciones se quedan tal cual: no se pierde nada.|n• El equipo parece \"más bajo\" porque la temporada nueva empieza en una escala más alta. Eso es normal y esperado: todo el mundo se reinicia a la vez.|n• Tu puntuación de Mythic+ también empieza de cero; de nuevo, para todo el mundo.|n• Llega en dos pasos: primero el parche (zona, campaña, mazmorra) y aproximadamente una semana después la temporada (Raid, Mythic+, PvP).|n• Qué hacer ahora: sigue el camino de Para empezar, sin prisa.",
	CODEX_S2_TITLE = "Una temporada nueva — qué significa",
	CODEX_SEASONEND_BODY = "• |cffffffffTu equipo no se reinicia.|r Todo lo que llevas puesto pasa contigo con el nivel de objeto que ya tiene. Deja de ser lo más alto, pero es una ventaja real el primer día de la temporada siguiente. El cambio en el que los números de todo el mundo bajan a la vez es un squish, y eso pertenece al parche previo de una expansión, no a un cambio de temporada.|n• |cffffffffLos números se mueven, tu progreso no.|r Cada temporada sube los niveles de objeto, así que una pieza que ahora está al máximo en la vía más alta queda una o dos vías más abajo con los números nuevos. Es normal y le pasa a todo el mundo.|n• |cffffffffSigue abriendo la Great Vault hasta la última semana.|r Cada semanal es equipo gratis que sube el punto desde el que empiezas la temporada siguiente.|n• |cffffffffLas monedas de temporada normalmente no sobreviven intactas a un cambio de temporada|r: suelen convertirse o dejar de ser útiles. Gastarlas es mejor que acumularlas. El comportamiento exacto varía según la moneda y puede cambiar a última hora, así que consulta la pestaña de monedas dentro del juego en lugar de fiarte de una guía.|n• |cffffffffEl plazo de verdad son las cosas exclusivas de la temporada:|r monturas, títulos y logros ligados a esta temporada, y las vías de progreso que se reinician. Esas son las que merece la pena terminar mientras puedas.|n• |cffffffffLas vías de progreso se reinician, pero sus recompensas normalmente no desaparecen|r: después suelen pasar a un vendedor sin el requisito de rango, a un precio mucho más alto. Terminarlas ahora sale más barato que comprarlas después.|n• |cffffffffElige una sola línea.|r Las últimas semanas son cortas. Terminar una vía es mejor que dejar tres a medias.",
	CODEX_SEASONEND_TITLE = "Cuando termina una temporada",
	CODEX_TRACKS_TITLE = "Vías de mejora del equipo",
	CODEX_VOID_TITLE = "Asaltos del Vacío",
})

fill("ptBR", {
	CODEX_ACCOUNT_TITLE = "Instantâneo da conta",
	CODEX_CAT_COILEDISLE = "A Ilha Enrolada",
