	CMDLIST_READY = "Bereitschaftsprüfung für Verbrauchsgüter in der Gruppe.",
	CMDLIST_RITUALBOSS = "Der Boss-Coach für die Ritualstätten.",
	CMDLIST_SCORECARD = "Die Wertung für deinen letzten Lauf.",
	CMDLIST_SEASON = "Saison-Statistiken für diesen Charakter.",
	CMDLIST_SETTINGS = "Schnelleinstellungen.",
	CMDLIST_SETUP = "Deine Leisten und deine Tastenbelegung einrichten, wobei der aktuelle Stand zuerst gezeigt wird.",
	CMDLIST_SIZE = "Das Hauptfenster skalieren.",
	CMDLIST_SKIP = "Das aktuelle Routenziel überspringen.",
	CMDLIST_TITLE = "Alle Befehle",
	CMDLIST_TRACKS = "Welche Plätze an ihrer Aufwertungsgrenze sitzen, und was sie anhebt.",
	CMDLIST_TRAIL = "Gibt einen gemessenen Reisetest aus. Für echte Wegbeschreibungen nutze /mh plan.",
	CMDLIST_VALEERA = "Valeeras Delve-Fortschritt anzeigen (erscheint in Delves von selbst)",
	CMDLIST_WEEKLIES = "Gibt die IDs der Wochenquests aus und ob dein Questlog sie hat.",
	CMDLIST_ZONE = "Was dieses Addon über die Zone weiß, in der du gerade bist.",
	DELVE_CHAT_VENOMFALL_DEEPS_BOSS = "Feste Reihenfolge: Noxious Bile, Void Toxin, Soul Extinction, Venom Storm - die dritte ist also der Kick. Soul Extinction tötet dich sofort, unterbrich sie jedes Mal. Bei 90/60/30% teilt sich der Raum in vier: stell dich in das freie Viertel, merk dir die REIHENFOLGE, er wiederholt sie, ohne etwas anzuzeigen. Ein Treffer = +500% Naturschaden für den Rest des Kampfes.",
	DELVE_CHAT_VENOMFALL_DEEPS_OVERVIEW = "Nemesis-Delve, Nordinsel der Gewundenen Insel. Azta'rec. Bring 290 ilvl für ? mit, 309 für ??. Valeera auf Heiler. Hier drin funktionieren keine Koordinaten.",
	DELVE_CHEST_ALL_DONE = "Jede Robuste Truhe hier hast du schon offen.",
	DELVE_CHEST_BTN = "Truhen",
	DELVE_CHEST_LEARNED = "Diese Liste ist das, was ich dich hier habe öffnen sehen, keine geprüfte — sie kann nicht wissen, was schon erledigt ist.",
	DELVE_CHEST_NO_DATA = "Für diesen Delve gibt es noch keine Truhenliste.",
	DELVE_CHEST_ROUTING = "Robuste Truhe %d von %d — folge dem Pfeil.",
	DELVE_CHEST_UNSURE = "%d davon kann ich nicht prüfen — du läufst vielleicht zu einer, die du schon hast.",
	DELVE_COACH_SEC_DANGER = "Daran stirbst du",
	DELVE_REWARDS_CAP_AT_8 = "|cffffffffDie Ausrüstung ist dieselbe|r: Tier 9, 10 und 11 geben genau das, was Tier 8 gibt, abgelesen am Delve-Eingang selbst und nicht aus einem Guide.|n|cffffffffDie Wappen nicht.|r Auf diesem Client am 19. August gemessen: ein Lauf auf Tier 8 zahlte |cffffffffChampion|r Mistcrest, ein Lauf auf Tier 11 zahlte |cffffffffHero|r Mistcrest. Über 8 hinauszuklettern bringt dir also doch etwas — nur nicht aus der Truhe.|nDie Vault-Zahlen sind weiterhin ungemessen; diese Zeile ist eine eigene Grenze, die der Eingang nicht zeigt.",
	DELVE_REWARDS_VAULT_LEARNED = "Eine Vault-Zahl mit einem * kommt nicht aus einer Tabelle — sie ist das, was deine eigene Great Vault für diesen Tier tatsächlich angeboten hat. Sie füllt sich, während du spielst. Die Vault nimmt die NIEDRIGSTE deiner zwei besten Aktivitäten dieser Woche, behandle eine gelernte Zahl also als Untergrenze und nicht als Versprechen.",
	DELVE_TIP_VENOMFALL_BOSS = "• |cffffffffSeine Fähigkeiten wiederholen sich in fester Reihenfolge|r: Noxious Bile, Void Toxin, Soul Extinction, Venom Storm. Du weißt also immer, dass die dritte der Kick ist.|n• |cffffffffSoul Extinction|r ist der One-Shot. Unterbrich sie jedes Mal. Heb deinen Kick dafür auf und lass Valeera Void Toxin entfernen, statt den Unterbrecher dort zu verbrauchen.|n• |cffffffffNoxious Bile|r ist ein Frontalangriff, der Pfützen hinterlässt. Richte ihn auf den Rand des Raums und tritt heraus, dann bleibt die Mitte für die Zwischenphase sauber.|n• |cffffffffVenom Storm|r schickt langsame Wellen von den Pfützen am Rand los. Kämpfst du in der Nähe des Eingangs, kommen sie dir nicht in den Rücken.|n• |cffffffffBei 90%, 60% und 30%|r kanalisiert er Sermon of Ula'tek und nimmt fast keinen Schaden — hör auf anzugreifen und schau zu. Er zeigt dir bei jedem Schritt das sichere Viertel und spielt danach die ganze Abfolge noch einmal ab, ohne etwas anzuzeigen. Merk dir die Reihenfolge, nicht nur das erste Feld.|n• Geh vor jeder dieser Schwellen in die Mitte; er ist schnell, und du kannst draußen erwischt werden. Vier Bodenmarkierungen machen aus dem Muster Zahlen — tipp |cffffffff/mh mark|r, bevor du pullst.",
	DELVE_TIP_VENOMFALL_DANGER = "• |cffffffffWrath of Ula'tek tötet dich aus vollem Leben.|r Naturschaden, und deine eigene Todesübersicht schreibt |cffffffffAvoidable|r dazu — es gibt also einen Ausweg und keinen Defensivzauber, den man drücken könnte.|n• Er kommt während der Zwischenphase, wenn der Raum in vier Viertel geteilt wird und drei davon volllaufen. Wirst du erwischt, bleibst du außerdem mit +500% erlittenem Naturschaden für den Rest des Kampfes zurück — ein einziger Fehler beendet den Versuch also, selbst wenn du ihn überlebst.|n• |cffffffffDieser Delve gibt keine Koordinaten heraus.|r Blizzard hat das Auslesen der Position hier drin blockiert, deshalb schweigen der Routenpfeil und jeder Wegpunkt — das ist nicht Midnight Helper, der versagt.",
	DELVE_TIP_VENOMFALL_DISPEL_NOTYOU = "• |cffff6b6bWarum Valeera bei dir ganz speziell auf Heiler gehört|r: Void Toxin ist ein magischer Debuff, und deine Spezialisierung kann ihn nicht von dir nehmen. Damit ist ihre Rolle hier eine Voraussetzung und keine Vorliebe — sie ist die Einzige, die ihn entfernen kann.",
	DELVE_TIP_VENOMFALL_DISPEL_YOU = "• |cffffd966Void Toxin ist ein magischer Debuff, und du kannst ihn selbst entfernen.|r Valeeras Rolle ist für dich also eine echte Wahl, anders als bei den meisten Spezialisierungen — vergiss nur nicht, dass das Entfernen an dir hängt.",
	DELVE_TIP_VENOMFALL_OVERVIEW = "• Der Nemesis-Delve der Saison 2, mitten auf der Nordinsel der Gewundenen Insel. Azta'rec ist der Boss.|n• Komm mit der empfohlenen Gegenstandsstufe, sonst wird der Kampf nicht einmal knapp: |cffffffff290|r für ? und |cffffffff309|r für ??. Diese beiden Zahlen stehen am Delve-Eingang selbst, sie sind also der Rat des Spiels.|n• Lauf erst einen normalen Delve, wenn du darunter liegst. Ein Bountiful Coffer auf Tier 8 gibt 295, und aus seiner schweren Truhe kann |cffffffffBlessing of Potency|r kommen — +10% Sekundärwerte für einen vollen Tag, bis zu deinem nächsten Delve. Damit hineinzugehen ist ein anderer Kampf.|n• |cffffffffValeera gehört auf Heiler|r, für fast jeden: sie entfernt Void Toxin, und das können die meisten Spezialisierungen nicht. Stell sie nur auf DPS, wenn du dich selbst heilst, und hier niemals auf Tank.|n• Quellen: die Namen der Fähigkeiten und die Regeln der Zwischenphase weiter unten stammen aus einem Community-Guide, nicht aus einer Messung. Nimm sie als gute Karte, nicht als Evangelium.",
	DGN_BADGE_S1 = "Saison 1",
	DGN_BADGE_S2 = "Saison 2",
	DGN_WIN_BOSS_PROMPT = "Boss gepullt — Boss-Guide öffnen?",
})

fill("frFR", {
	ACADEMY_DPS_BOTH_BODY = "Tu connais déjà les combats depuis le siège DPS, et c'est l'essentiel du travail. Tanker t'ouvre des files de donjon instantanées ; soigner demande le plus de sang-froid, mais c'est le rôle le plus recherché.\n\nEssaie d'abord le nouveau rôle dans un gouffre ou un donjon avec suiveurs, là où personne ne t'attend. Garde ensuite un seul rôle comme rôle principal pendant un moment, au lieu d'en changer à chaque pug.",
	ACADEMY_DPS_BOTH_TITLE = "Tenté par le tank ou le soin ?",
	ACADEMY_DPS_COOLDOWNS_BODY = "Tes cooldowns de dégâts représentent la plus grande partie de tes dégâts. Les lancer dès qu'ils sont prêts vaut mieux que les garder pour un moment « parfait » qui n'arrive jamais.\n\nSur un boss, ouvre le combat avec eux ou garde-les pour la phase qui compte. Ta boîte à outils ci-dessus les liste pour ta spé.",
	ACADEMY_DPS_COOLDOWNS_TITLE = "Aligne tes cooldowns",
	ACADEMY_DPS_INTRO_BODY = "Ton job, ce sont les dégâts - mais un DPS mort en fait zéro. Rester en vie et faire les mécaniques passe en premier, les dégâts en second.\n\nTu n'as pas besoin d'être en haut du compteur. Des dégâts réguliers en faisant ton travail valent mieux que des chiffres énormes suivis d'une mort.",
	ACADEMY_DPS_INTRO_TITLE = "État d'esprit DPS",
	ACADEMY_DPS_MECHANICS_BODY = "Sors de ce qui fait mal, même si ça te coûte une incantation. Une pile de dégâts évitables wipe le groupe plus vite que des DPS faibles.\n\nÊtre gourmand, c'est rester dans le feu pour une incantation de plus. Bien jouer, c'est prendre une demi-seconde pour te replacer et rester en vie pour lancer tout le reste.",
	ACADEMY_DPS_MECHANICS_TITLE = "Les mécaniques passent avant les dégâts",
	ACADEMY_DPS_MISTAKES_BODY = "1. Rester assis sur ses cooldowns « au cas où »\n2. Plafonner sa ressource (génération gaspillée)\n3. Rester dans ce qui fait mal pour une incantation de plus\n4. Ne jamais interrompre ni utiliser son utilitaire\n5. Faire une fixation sur les dégâts pendant que ta vie tombe à zéro\n\nChoisis-en un à corriger par run - pas les cinq d'un coup.",
	ACADEMY_DPS_MISTAKES_TITLE = "Erreurs de débutant courantes",
	ACADEMY_DPS_PRACTICE_BODY = "Tape deux minutes sur un mannequin d'entraînement : garde ta ressource en mouvement, intercale tes cooldowns, et regarde ce qui expire.\n\nEnsuite les gouffres, puis les donjons normaux. Tu n'as pas besoin d'une rotation parfaite pour commencer - tu as besoin de continuer à appuyer et de rester en vie.",
	ACADEMY_DPS_PRACTICE_TITLE = "Entraînement sur cible",
	ACADEMY_DPS_ROTATION_BODY = "La plupart des spés accumulent une ressource, puis la dépensent. Garde ton générateur et ton dépensier en mouvement ; ne plafonne pas ta ressource et ne laisse pas tes dots/buffs expirer.\n\nUn ou deux boutons appuyés au bon moment valent mieux que cinq martelés. Apprends la priorité, pas un ordre appris par cœur.",
	ACADEMY_DPS_ROTATION_TITLE = "Une priorité, pas une rotation figée",
	ACADEMY_DPS_UTILITY_BODY = "Interromps les incantations dangereuses, utilise ton contrôle de foule, et lance ta défensive personnelle quand tu prends un gros coup.\n\nUn DPS qui interrompt et qui survit vaut bien plus que celui qui se contente de pomper des chiffres.",
	ACADEMY_DPS_UTILITY_TITLE = "Tu n'es pas qu'un robot à dégâts",
	ACADEMY_HEAL_CONFIDENCE_BODY = "Quelqu'un mourra sous ta garde. Tous les soigneurs qui existent ont laissé mourir des gens - c'est comme ça qu'on apprend où sont les limites.\n\nUne mort n'est pas un wipe, et un wipe n'est pas un verdict sur toi. Retiens la seule chose que tu ferais autrement, puis passe à autre chose.\n\nLes groupes se souviennent bien plus d'un soigneur calme qui communique que d'un soigneur parfait.",
	ACADEMY_HEAL_CONFIDENCE_TITLE = "Perdre quelqu'un, ça arrive",
	ACADEMY_HEAL_COOLDOWNS_BODY = "Tes grands cooldowns de soin servent aux gros dégâts prévus - un coup du boss sur tout le raid - pas aux égratignures aléatoires.\n\nGarder un cooldown « au cas où » pendant tout le combat, c'est le gâcher. Un cooldown lancé à 90 % du bon moment vaut mieux qu'un cooldown jamais lancé.\n\nTape /mh healcds pour voir les cooldowns de ta spé et le moment où garder chacun d'eux.",
	ACADEMY_HEAL_COOLDOWNS_TITLE = "Garde tes grands cooldowns",
	ACADEMY_HEAL_MANA_BODY = "Le mana est ta vraie barre de vie. Si tu la vides, tu ne peux plus soigner du tout.\n\nUtilise des soins rapides et peu coûteux pour les petites baisses ; garde tes gros soins coûteux pour les vraies urgences. Tout le monde n'a pas besoin d'être au maximum - laisse les gens rouler à 80 %.\n\nBois entre chaque pull. Dire « plus de mana, 5 sec » est une phrase normale et professionnelle.",
	ACADEMY_HEAL_MANA_TITLE = "Mana et efficacité",
	ACADEMY_HEAL_MISTAKES_BODY = "1. Faire une fixation sur une barre de vie pendant que trois autres descendent\n2. Sur-soigner en panique jusqu'à 100 % et vider son mana\n3. Rester dans ce qui fait mal, les yeux rivés sur les cadres de groupe\n4. Ne jamais lancer ses cooldowns\n5. Soigner à travers des dégâts qu'on peut supprimer au lieu de demander une interruption\n\nChoisis-en un à surveiller par run - pas les cinq d'un coup.",
	ACADEMY_HEAL_MISTAKES_TITLE = "Erreurs de débutant courantes",
	ACADEMY_HEAL_POSITION_BODY = "Reste à portée de tout le groupe, mais pas collé au boss. Un coin en retrait d'où tu vois tout le monde vaut mieux que de coller au tank.\n\nToi aussi, tu dois esquiver. Un soigneur mort ne soigne personne - sors de ce qui fait mal, même si ça coûte une demi-seconde d'incantation.\n\nGarde la ligne de vue : tu ne peux pas soigner quelqu'un à travers un mur ou un pilier.",
	ACADEMY_HEAL_POSITION_TITLE = "Où te placer",
	ACADEMY_PREF_DPS_COOLDOWNS = "Cooldowns de dégâts sur un raccourci (pas perdus dans la barre)",
	ACADEMY_PREF_DPS_DEFENSIVE = "Une défensive personnelle sur ma barre",
	ACADEMY_PREF_DPS_INTERRUPT = "Mon interruption sur un raccourci (testée une fois sur un mannequin)",
	ACADEMY_PREF_DPS_ROTATION = "Capacités principales sur des touches faciles d'accès",
	ACADEMY_TRACK_DPS = "Piste DPS",
	ACH_LORE_HONORED_DEAD = "Les morts honorés (Caveaux d'Atal'Utek)",
	ACH_META_PREVIEW_HINT = "Clic : aperçu de la monture",
	ACH_MIX_RECIPE_FMT = "Nécessite : %s",
	ACH_NOTE_BRINE_CRUSTED = "Verrouillé. Ouvre une Palourde pétillante pour obtenir une perle, puis pose-la sur la flèche au sol à côté du PNJ - elle lâche la clé. Si aucune palourde ne s'ouvre, c'est que tu as déjà une perle.",
	ACH_NOTE_GRAVE_FORGOTTEN = "Verrouillé. Parle d'abord aux trois esprits, puis reviens à la tombe.",
	ACH_NOTE_LOST_SPIRIT = "Verrouillé. Ramasse l'objet perdu et rapporte-le à l'esprit qui se trouve ici.",
	ACH_NOTE_MIX_GATES = "Deux choses bloquent l'accès. La Renommée 3 auprès de Zul'jarra's Forces fait apparaître les conteneurs, et c'est le nœud Ofi's Offerings sur l'Autel de la Corrosion qui met les ingrédients dedans - avec le premier mais pas le second, tu ne pilleras rien et tu croiras que c'est cassé.",
	ACH_NOTE_MIX_MASTER = "Un par jour, préparé au chaudron d'Ofi the Sly en 57.4 / 48.7 - pas l'Ofi du marais, qui ne sait pas mélanger. Chaque offrande est une combinaison exacte de trois ingrédients et le jeu ne t'affiche rien pendant que tu choisis : la recette ci-dessous est donc tout le travail. Les ingrédients viennent des Cracked Canopic Jars, Venom-Clotted Baubles et Singing Shells répartis sur l'île, et ils sont échangeables, donc l'hôtel des ventes marche aussi.",
	ACH_NOTE_PRIVATEERS_CACHE = "Verrouillé. Pêche dans le Banc de morues macabres, donne le poisson au dauphin sous l'eau, puis suis-le jusqu'à la caisse et à l'urne et combine les deux moitiés. Reste sous l'eau - remonter à la surface fait partir le dauphin.",
	ACH_NOTE_PROFANE_SPOILS = "Verrouillé. Place-toi face à la statue et clique les braseros dans cet ordre : en haut à droite, en haut à gauche, en bas à droite, en bas à gauche.",
