fill("ptBR", {
	ACADEMY_DPS_BOTH_BODY = "Você já conhece as lutas do lugar do DPS, e isso é a maior parte do trabalho. Tankar te dá filas de masmorra instantâneas; curar exige mais sangue-frio, mas é a função mais procurada.\n\nExperimente a função nova primeiro num delve ou numa follower dungeon, onde ninguém depende de você. Depois mantenha uma função como principal por um tempo, em vez de trocar a cada pug.",
	ACADEMY_DPS_BOTH_TITLE = "Pensando em tankar ou curar?",
	ACADEMY_DPS_COOLDOWNS_BODY = "Seus cooldowns de dano são a maior parte do seu dano. Apertá-los assim que ficam prontos vale mais do que guardá-los para um momento \"perfeito\" que nunca chega.\n\nNum chefe, abra com eles ou guarde-os para a fase que importa. O kit acima lista os da sua spec.",
	ACADEMY_DPS_COOLDOWNS_TITLE = "Alinhe seus cooldowns",
	ACADEMY_DPS_INTRO_BODY = "Seu trabalho é dano - mas um DPS morto causa zero. Ficar vivo e cumprir as mecânicas vem primeiro; o dano vem depois.\n\nVocê não precisa do topo do medidor. Dano constante enquanto você faz seu trabalho vale mais do que números enormes seguidos de uma morte.",
	ACADEMY_DPS_INTRO_TITLE = "Mentalidade de DPS",
	ACADEMY_DPS_MECHANICS_BODY = "Saia do chão ruim mesmo que isso custe uma conjuração. Um acúmulo de dano evitável mata o grupo mais rápido do que DPS baixo.\n\nGanância é ficar no fogo por mais uma conjuração. O certo é gastar meio segundo se reposicionando e sobreviver para apertar o resto.",
	ACADEMY_DPS_MECHANICS_TITLE = "Mecânicas valem mais que dano",
	ACADEMY_DPS_MISTAKES_BODY = "1. Segurar cooldowns \"por via das dúvidas\"\n2. Estourar o limite do seu recurso (geração desperdiçada)\n3. Ficar no chão ruim por mais uma conjuração\n4. Nunca interromper nem usar utilidade\n5. Só olhar o dano enquanto sua vida despenca\n\nEscolha um para corrigir a cada run - não os cinco de uma vez.",
	ACADEMY_DPS_MISTAKES_TITLE = "Erros comuns de iniciante",
	ACADEMY_DPS_PRACTICE_BODY = "Bata num boneco de treino por dois minutos: mantenha seu recurso girando, encaixe seus cooldowns e veja o que expira.\n\nDepois delves, depois masmorras normais. Você não precisa de uma rotação perfeita para começar - precisa continuar apertando e ficar vivo.",
	ACADEMY_DPS_PRACTICE_TITLE = "Prática no alvo",
	ACADEMY_DPS_ROTATION_BODY = "A maioria das specs acumula um recurso e depois o gasta. Mantenha o gerador e o gastador girando; não estoure o limite do recurso e não deixe dots/buffs expirarem.\n\nUm ou dois botões apertados na hora certa valem mais do que martelar cinco. Aprenda a prioridade, não uma ordem decorada.",
	ACADEMY_DPS_ROTATION_TITLE = "Prioridade, não uma rotação fixa",
	ACADEMY_DPS_UTILITY_BODY = "Interrompa conjurações perigosas, use seu controle e aperte seu defensivo pessoal quando levar um golpe grande.\n\nUm DPS que interrompe e sobrevive vale muito mais do que um que só bombeia números.",
	ACADEMY_DPS_UTILITY_TITLE = "Você não é só um robô de dano",
	ACADEMY_HEAL_CONFIDENCE_BODY = "Alguém vai morrer sob os seus cuidados. Todo curandeiro vivo já deixou gente morrer - é assim que se aprende onde ficam os limites.\n\nUma morte não é um wipe, e um wipe não é um veredito sobre você. Anote a única coisa que você faria diferente e siga em frente.\n\nOs grupos lembram muito mais de um curandeiro calmo que se comunica do que de um curandeiro perfeito.",
	ACADEMY_HEAL_CONFIDENCE_TITLE = "Tudo bem perder alguém",
	ACADEMY_HEAL_COOLDOWNS_BODY = "Seus grandes cooldowns de cura são para dano grande e planejado - o golpe do chefe que pega o raid inteiro - não para arranhões aleatórios.\n\nSegurar um cooldown \"por via das dúvidas\" a luta inteira é desperdiçá-lo. Um cooldown apertado a 90% do momento certo vale mais do que um que nunca foi apertado.\n\nDigite /mh healcds para ver os cooldowns da sua spec e quando guardar cada um.",
	ACADEMY_HEAL_COOLDOWNS_TITLE = "Guarde seus grandes cooldowns",
	ACADEMY_HEAL_MANA_BODY = "A mana é a sua verdadeira barra de vida. Se você esvaziá-la, não cura mais nada.\n\nUse curas baratas e rápidas para quedas pequenas; guarde as curas grandes e caras para emergências de verdade. Ninguém precisa ficar com a vida cheia o tempo todo - deixe o pessoal andar com 80%.\n\nBeba entre um pull e outro. \"Sem mana, 5 seg\" é uma coisa normal e profissional de se dizer.",
	ACADEMY_HEAL_MANA_TITLE = "Mana e eficiência",
	ACADEMY_HEAL_MISTAKES_BODY = "1. Ficar preso em uma barra de vida enquanto outras três caem\n2. Curar demais em pânico até 100% e esvaziar a mana\n3. Ficar no chão ruim de olho grudado nos frames\n4. Nunca apertar seus cooldowns\n5. Curar por cima de um dano que dá para evitar em vez de pedir uma interrupção\n\nEscolha um para vigiar a cada run - não os cinco de uma vez.",
	ACADEMY_HEAL_MISTAKES_TITLE = "Erros comuns de iniciante",
	ACADEMY_HEAL_POSITION_BODY = "Fique no alcance do grupo inteiro, mas não em cima do chefe. Um canto atrás, de onde você vê todo mundo, vale mais do que ficar colado no tanque.\n\nVocê ainda precisa desviar. Curandeiro morto não cura ninguém - saia do chão ruim mesmo que isso custe meio segundo de conjuração.\n\nMantenha a linha de visão: você não cura ninguém através de uma parede ou de um pilar.",
	ACADEMY_HEAL_POSITION_TITLE = "Onde ficar",
